import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Inställningar för ACP-körmiljön för att aktivera dirigering, välja backends, begränsa tillåtna målagenter och välja hur strömmade turer presenteras.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Tillåtna ACP-agenter`},help:{"v1-f2mw0d-3a":`Lista över tillåtna målagent-id:n för sessioner i ACP-körmiljön. En tom lista innebär ingen ytterligare begränsning.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`ACP-backend`},help:{"v1-1s1l6bz-2v":`Standard-id för backend i ACP-körmiljön (till exempel: acpx). Måste matcha en registrerad plugin-backend för ACP-körmiljön.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Standardagent för ACP`},help:{"v1-7donnu-2c":`Reserv-id för ACP-målagent som används när inget uttryckligt mål anges vid start av ACP-sessioner.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`ACP-dirigering aktiverad`},help:{"v1-1ug9t9m-3w":`Separat styrning av dirigering för turer i ACP-sessioner (standard: true). Ange false för att behålla ACP-kommandon tillgängliga men blockera körning av ACP-turer.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP aktiverat`},help:{"v1-1uonl1v-2a":`Global aktivering av ACP-funktionen. Låt vara inaktiverad om inte ACP-körmiljön och policyn är konfigurerade.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Reservbackends för ACP`},help:{"v1-1wvdifq-5m":`Ordnad lista över id:n för reservbackends för ACP som provas när primär backend misslyckas med UNAVAILABLE (till exempel: anropsgränsen nådd eller kvoten förbrukad). Varje post måste matcha en registrerad plugin-backend för ACP-körmiljön.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Installationskommando för ACP-körmiljön`},help:{"v1-1jjuv9m-39":"Valfritt installations- eller konfigurationskommando för operatören som visas av `/acp install` och `/acp doctor` när anslutningen till ACP-backend saknas."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`ACP-ström`},help:{"v1-1bka5p-2v":`Inställningar för ACP-strömningsprojektion som styr chunkstorlek, metadatasynlighet och leverans utan dubbletter.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Leveransläge för ACP-ström`},help:{"v1-19gdmx1-3s":`Leveranssätt för ACP: live strömmar projicerad utdata stegvis, medan final_only buffrar all projicerad ACP-utdata tills händelser som avslutar turen inträffar.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Undertryckning av upprepningar i ACP-ström`},help:{"v1-manh32-3d":`När värdet är true (standard) undertrycks upprepade projektionsrader för ACP-status och verktyg under en tur, medan råa ACP-händelser förblir oförändrade.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Taggsynlighet i ACP-ström`},help:{"v1-1ybhx22-34":`Åsidosättningar av synlighet per sessionUpdate för ACP-projektion (till exempel usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agenter`},help:{"v1-2rc4v8-55":`Rot för agenternas körningskonfiguration. Inställningar på samma nivå som roten ansvarar för infrastruktur och agentövergripande standardvärden; agents.defaults ansvarar för agentloopens beteende; agentposter kan åsidosätta båda där det stöds.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Standardinställningar för agenter`},help:{"v1-1af7k5b-5a":`Gemensamma standardinställningar som ärvs av agenter om de inte åsidosätts per post i agents.entries. Använd standardinställningar för att säkerställa ett enhetligt grundbeteende och minska duplicerad konfiguration per agent.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Mål för autentiseringsarv`},help:{"v1-2d16wl-2x":`Ägare för det ärvda lagret av autentiseringsuppgifter för kompatibilitet vid uppgradering, tills autentiseringsuppgifterna flyttas till respektive agent.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Ägare för autentiseringsarv`},help:{"v1-1a1s7nm-4s":`Agent vars äldre autentiseringslager förblir källa för arv efter att standardmarkören har tagits bort. Skrivs automatiskt vid uppgradering när den tidigare ägaren inte var main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Maximalt antal tecken för initiering`},help:{"v1-drlo3i-37":`Maximalt antal tecken från varje initieringsfil i arbetsytan som infogas i systemprompten före trunkering (standard: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Maximalt totalt antal tecken för initiering`},help:{"v1-1evwsjb-2c":`Maximalt totalt antal tecken från alla infogade initieringsfiler i arbetsytan (standard: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Kompaktering`},help:{"v1-1qxdwz8-5p":`Kompakteringsbeteende när kontexten närmar sig tokengränserna, inklusive strategi och hur minnet sparas före kompaktering. Använd detta när långvariga sessioner behöver stabil kontinuitet med snäva kontextfönster.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Inbyggd automatisk kompaktering`},help:{"v1-1et7vwu-5l":`Aktivera inbyggd proaktiv automatisk kompaktering (standard: true). Ange false för att stoppa tröskelstyrd inbyggd kompaktering men behålla återställning vid överskriden kontextgräns i OpenClaw, kompaktering vid förhandskontroll och manuellt /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Identifierarpolicy för kompaktering`},help:{"v1-hby01l-4l":`Policy för bevarande av identifierare i komprimeringssammanfattningar: "strict" lägger till inbyggda anvisningar om att bevara opaka identifierare som prefix (standard), medan "off" inaktiverar detta prefix.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Komprimering: bevara senaste token`},help:{"v1-tgysub-5h":`Minsta tokenbudget som bevaras från det senaste konversationsfönstret vid komprimering. Använd högre värden för att skydda kontinuiteten i den aktuella kontexten och lägre värden för att behålla mer äldre historik.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Komprimering: storleksgräns för aktiv konversationslogg`},help:{"v1-u715n1-90":`Gräns i byte som utlöser normal lokal komprimering i förkontrollen när det fönster av konversationsloggen som modellen ser (sedan den senaste komprimeringen eller återställningen) når denna storlek (byte eller strängar som "20mb"). Ange 0 eller lämna värdet oangivet för att inaktivera. Begränsar även inbyggda körningsloggar i Codex app-server; inbyggda trådar som är för stora startas om från början.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Komprimering: minnessparning`},help:{"v1-18q0ve9-55":`Inställningar för minnessparning före komprimering som låter agenten skriva till minnet före omfattande komprimering. Behåll funktionen aktiverad för långa sessioner så att viktig kontext sparas före kraftig nedkortning.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Komprimering: minnessparning aktiverad`},help:{"v1-9xllgp-5o":`Aktiverar minnessparning före komprimering, innan körmiljön utför en mer omfattande historikreducering nära tokengränserna. Låt vara aktiverat om du inte avsiktligt vill stänga av sidoeffekter på minnet i begränsade miljöer.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Storleksgräns för konversationsutskrift vid minnessparning före komprimering`},help:{"v1-1rzov1e-93":`Tvingar fram minnessparning före komprimering när den del av konversationsutskriften som är synlig för modellen når denna gräns (byte eller strängar som "2mb"). Efter komprimering omfattar detta den bevarade slutdelen och efterföljande turer, inte borttagen historik. Använd detta för att förhindra att långa sessioner hänger sig även när tokenräknarna är inaktuella. Ange 0 för att inaktivera.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Modellåsidosättning för minnessparning före komprimering`},help:{"v1-1r3ctyu-7w":`Valfri åsidosättning av leverantör/modell som endast används för turer med minnessparning före komprimering. Ange en lokal modell som ollama/qwen3:8b när extrahering till beständigt minne inte ska använda den aktiva sessionens betalda modell. Åsidosättningen är exakt och ärver inte den aktiva modellens kedja av reservmodeller.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Mjuk gräns för minnessparning före komprimering`},help:{"v1-1dqo2l1-5c":`Avstånd till komprimeringsgränsen (i token) som utlöser minnessparning före komprimering. Använd tidigare gränser för säkrare lagring eller snävare gränser för mindre frekvent minnessparning.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Förhandskontroll av komprimering mitt i en tur`},help:{"v1-am6gbh-6x":`Valfri förkontroll i inbäddade OpenClaw-verktygsloopar som upptäcker kontextbelastning efter att ett verktygsresultat har lagts till och före nästa modellanrop. När funktionen är aktiverad återanvänder OpenClaw den befintliga återställningsmekanismen för förkontroller för att trunkera verktygsresultat eller komprimera kontexten före ett nytt försök.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Förkontroll för komprimering under pågående tur aktiverad`},help:{"v1-engbwe-5u":`Aktivera strukturerade kontroller av kontextbelastning under pågående tur i inbäddade OpenClaw-verktygsloopar. Standardvärde: false. Låt funktionen vara inaktiverad om inte långa sessioner med många verktygsanrop överskrider kontextgränsen innan den vanliga komprimeringen vid turens slut hinner köras.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Komprimeringsläge`},help:{"v1-1unahwc-76":`Strategiläge för komprimering: "safeguard" (standardläget när inget anges) tillämpar skyddsmekanismer för att bevara den senaste kontexten, medan "default" använder grundläggande sammanfattning utan dessa. Ange "default" endast om sammanfattning med safeguard orsakar problem hos din leverantör.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Åsidosättning av komprimeringsmodell`},help:{"v1-cfeys9-6q":`Valfri leverantör/modell eller konfigurerat alias utan prefix som endast används för sammanfattning vid komprimering. Alias utan prefix löses upp innan anropet skickas. Ett konfigurerat uttryckligt modell-ID har företräde vid konflikt med ett alias. Lämna inställningen tom för att fortsätta använda agentens primära modell.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Meddela användaren vid komprimering`},help:{"v1-lvymm8-bv":`När detta är aktiverat skickas korta meddelanden om kontextunderhåll till användaren: när komprimeringen börjar och slutförs (till exempel ”🧹 Komprimerar kontext...” och ”🧹 Komprimeringen är klar”), och när försöken att spara minnet före komprimeringen är uttömda så att svaret fortsätter med försämrad funktion (till exempel ”⚠️ Minnesunderhållet misslyckades tillfälligt; fortsätter med ditt svar.”). Inaktiverat som standard för att kontextunderhållet ska ske tyst och utan att störa.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Kontextavsnitt efter komprimering`},help:{"v1-1n0ln2u-5f":`Namn på valfria H2/H3-avsnitt i AGENTS.md som återinfogas efter komprimering. Lämna värdet oangivet eller ange [] för att inaktivera återinfogning. Ange uttryckligen ["Session Startup", "Red Lines"] för att aktivera det tidigare standardparet.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Indexsynkronisering efter komprimering`},help:{"v1-ekpjeq-6l":`Styr läget för omindexering av sessionsminnet efter komprimering: "off", "async" eller "await" (standard: "async"). Använd "await" för att hålla indexet så aktuellt som möjligt, "async" för kortare komprimeringstid och "off" endast när synkroniseringen av sessionsminnet hanteras på annat håll.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Komprimeringsleverantör`},help:{"v1-2zoy3b-7v":`Id för ett registrerat komprimeringsleverantörsplugin som används för sammanfattning. När värdet är angivet och leverantören är registrerad anropas dess summarize()-metod i stället för den inbyggda sammanfattningsbegäran. Återgår till den inbyggda funktionen om leverantören misslyckas. Lämna värdet oangivet för att använda den inbyggda standardsammanfattningen.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Kvalitetskontroll för komprimering`},help:{"v1-u9ognp-4k":`Inställningar för återförsök vid kvalitetsgranskning av sammanfattningar i safeguard-komprimering. Läget safeguard aktiverar detta som standard; ange enabled: false för att hoppa över granskning och omgenerering av sammanfattningar.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Kvalitetskontroll för komprimering aktiverad`},help:{"v1-1xk2vt3-36":`Aktiverar kvalitetsgranskning av sammanfattningar och återförsök med omgenerering för safeguard-komprimering. Standard: true i läget safeguard.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Maximalt antal återförsök för komprimeringens kvalitetskontroll`},help:{"v1-n7l46y-3y":`Maximalt antal återförsök med omgenerering efter en underkänd kvalitetsgranskning av en safeguard-sammanfattning. Använd låga värden för att begränsa extra fördröjning och tokenkostnad.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Bevara senaste samtalsturer vid komprimering`},help:{"v1-y34ihi-5k":`Antal av de senaste samtalsturerna mellan användare och assistent som bevaras ordagrant utanför safeguard-sammanfattningen (standard: 3). Höj värdet för att bevara den senaste dialogens exakta kontext, eller sänk det för att maximera komprimeringsvinsten.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Resonemangsnivå vid komprimering`},help:{"v1-1vafgaw-g1":`Resonemangsnivå som endast används för sammanfattningar vid komprimering i den inbäddade OpenClaw-körmiljön: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" eller "inherit". Standardvärdet är leverantörens föredragna nivå för komprimering, annars "low"; lokal Ollama med inbyggt stöd föredrar "off". Ange "inherit" för att återanvända sessionens nivå. Explicita inställningar åsidosätter leverantörens standardvärden, och den valda nivån begränsas till vad den faktiska komprimeringsmodellen och körmiljön stöder. Inbyggd komprimering i Codex app-server ignorerar den här inställningen eftersom dess komprimeringsbegäran inte har någon åsidosättning av resonemangsnivån per åtgärd, och OpenClaw loggar en varning.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Tidsgräns för komprimering (sekunder)`},help:{"v1-9elpfn-96":`Antal sekunder som en begäran till den inbyggda komprimeringsmodellen får fortgå utan framsteg (standard: 180). Varje begäransstart och varje strömmad utdatatoken återställer tidsfönstret, så en långsam begäran som fortsätter att strömma avbryts inte; hela komprimeringen stoppas efter 10 tidsfönster. Komprimering som hanteras av ett insticksprogram får ett tidsfönster för hela åtgärden.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Kontextinjektion`},help:{"v1-u18x0-7u":`Styr injektion av arbetsytans initieringsfiler i den inbäddade körmiljön: "always" använder normal injektion (standard), "continuation-skip" hoppar över kvalificerade fortsättningsturer efter en registrerad tur med fullständig initiering, och "never" inaktiverar injektion. Styr inte CLI-baserad promptförberedelse.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Standardgränser för kontext`},help:{"v1-1coeez8-5d":`Riktade standardgränser för kontextbudget per agent för utvalda stora utdrag och infogade promptblock. Använd detta för att justera storleksgränser för läsning och infogning utan att åter öppna några obegränsade anropsvägar.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Standardgräns för antal tecken från memory_get`},help:{"v1-1qb40qv-4v":`Standardgräns för hur många tecken memory_get returnerar innan metadata om trunkering och ett fortsättningsmeddelande läggs till. Höj gränsen för att efterlikna äldre, större utdrag, men behåll en övre gräns.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Standardgräns för antal tecken efter komprimering`},help:{"v1-64qo8g-5r":`Standardgräns för hur många tecken från AGENTS.md som behålls och infogas vid kontextuppdatering efter komprimering. Sänk gränsen för att göra återställningen efter komprimering mindre kostsam, eller höj den för agenter som behöver längre startinstruktioner.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Arbetskatalog`},help:{"v1-1y8wlxn-6a":`Arbetskatalog för körningar som genererar agentsvar, separat från arbetsytans initieringsfiler och minnesfiler. Agentspecifik cwd och cwd från sessionsstart har företräde. Stöder ~ och relativa sökvägar; en separat cwd kräver en körning utanför sandlådan.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Beslutsmodell`},help:{"v1-7nd7ze-64":`Valfri leverantör/modell för typade val, poäng och sannolikheter för booleska värden. Om värdet inte anges eller är tomt inaktiveras beslutsanrop. Insticksprogram med stöd för detta skickar storleksbegränsat uppgiftsunderlag till den här leverantören; chatt- och hjälpmodeller ändras inte.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`Inbäddad OpenClaw`},help:{"v1-1keek32-3k":`Säkerhetskontroller för den inbäddade OpenClaw-körmiljön som styr hur arbetsytans lokala agentinställningar betros och tillämpas i OpenClaw-sessioner.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Reservväxling vid cyberpolicyavslag`},help:{"v1-xvv6wl-2r":`Automatisk eskalering till Daybreak vid avslag enligt OpenAI:s cyberpolicy som säkert kan köras om i den inbäddade körmiljön.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Väntetid för reservväxling vid cyberpolicyavslag`},help:{"v1-16smtrl-25":`Hur länge ett otillgängligt eskaleringsmål hoppas över i den aktuella sessionen.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Läge för reservväxling vid cyberpolicyavslag`},help:{"v1-rzsd2b-2h":`Aktivera automatisk eskalering ("auto", standard) eller låt leverantörens avslag avsluta körningen ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Modell för reservväxling vid cyberpolicyavslag`},help:{"v1-1aaj8nn-1t":`Leverantör/modell som används som mål för automatisk eskalering vid cyberpolicyavslag.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Körningskontrakt för inbäddad OpenClaw`},help:{"v1-1fch2ig-66":`Körningskontrakt för inbäddad OpenClaw: "default" behåller körmiljöns standardbeteende, medan "strict-agentic" aktiverar strukturerad planuppföljning och osynlig återställning av samtalsturer för körningar med modeller i OpenAI/OpenAI Codex GPT-5-familjen som stöds.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Policy för projektinställningar i inbäddad OpenClaw`},help:{"v1-fdyy04-65":'Hur inbäddad OpenClaw hanterar arbetsytans lokala `.openclaw/settings.json`: "sanitize" (standard) tar bort shellPath/shellCommandPrefix, "ignore" inaktiverar projektinställningarna helt och "trusted" tillämpar projektinställningarna som de är.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Experimentella agentflaggor`},help:{"v1-cvv5cl-2w":`Experimentella standardflaggor för agenter. Låt dem vara avstängda om du inte avsiktligt testar en förhandsversion av en funktion.`}},"agents%2Edefaults%2Eexperimental%2EdecisionAssistance":{label:{"v1-1tepbyi-y":`Beslutsstöd (experimentellt)`},help:{"v1-1fmo3r9-ew":`Global aktivering av experimentellt stöd från den ägande agentens konfigurerade beslutsmodell (standard: false; kräver uttryckligen true). Den gällande decisionModel kan ärvas från globala standardinställningar eller väljas per agent; ett tomt värde för en agent inaktiverar stödet. Användningsområden som stöds kan skicka utvalda data till den leverantören och medföra leverantörsavgifter. Se dokumentationen om beslutsstöd för användningsområden som stöds, konfiguration och datahantering. Den här inställningen styr inte explicita decision_evaluate-anrop, väljer inte leverantörer och ger inte behörighet att utföra åtgärder.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Aktivera resurssnålt läge för lokala modeller (experimentellt)`},help:{"v1-gj06u6-7b":`Avancerad åsidosättning för felsökning som begränsar valfria verktyg som browser, automations och message. Avstängd som standard; lokala körmiljöer som stöds använder automatisk verktygssökning utan denna begränsning. Uttryckliga verktygstillåtelser och nödvändiga leveransverktyg bevaras.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Standardläge för agentens snabbläge`},help:{"v1-6q8gx8-3c":`Standardpolicy för snabbläge i agentloopen ("auto", "ultrafast", true eller false). Enskilda agentposter åsidosätter den.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Agent för hjärtslag`},help:{"v1-1jynxej-3w":`Agent som ansvarar för hjärtslagskörningar i bakgrunden när ingen agentspecifik hjärtslagskonfiguration finns. Lämna oinställt för att behålla den konfigurerade standardroutningen.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Policy för direkta hjärtslagsmeddelanden`},help:{"v1-nhyxa9-41":`Styr om hjärtslag får levereras till direktchattar/DM: "allow" (standard) tillåter DM-leverans och "block" förhindrar sändning till direkta mottagare.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Tidsgräns för hjärtslag (sekunder)`},help:{"v1-1se21py-5f":`Maximal tid i sekunder för en agenttur med hjärtslag innan den avbryts. Lämna oinställt för att använda agents.defaults.timeoutSeconds om det är inställt, annars hjärtslagsintervallet med en övre gräns på 600 sekunder.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Maximal mänsklig fördröjning (ms)`},help:{"v1-vnmvli-1m":`Maximal fördröjning i ms för anpassad humanDelay (standard: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Minimal mänsklig fördröjning (ms)`},help:{"v1-5nrtr5-1l":`Minimal fördröjning i ms för anpassad humanDelay (standard: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Läge för mänsklig fördröjning`},help:{"v1-k7hyg3-1n":`Fördröjningstyp för svar i block ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Maximal bilddimension (px)`},help:{"v1-vju8x-2u":`Maximal sidlängd för bilder i pixlar vid bearbetning av bilddata i konversationshistorik och verktygsresultat (standard: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Reservmodeller för bilder`},help:{"v1-1kgx5i9-1b":`Reservmodeller för bilder i prioritetsordning (leverantör/modell).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Bildmodell`},help:{"v1-dstqyh-2c":`Valfri bildmodell (leverantör/modell) som används när den primära modellen inte stöder bildindata.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Bildkvalitet`},help:{"v1-1uyxc5s-6u":`Inställning för mediekomprimering i bildverktyget: "auto" anpassar sig efter leverantörens/modellens begränsningar och antalet bilder, "efficient" sparar token och byte, "balanced" behåller den nuvarande avvägningen och "high" bevarar fler detaljer i skärmbilder och dokumentbilder.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Reservmodeller för bildgenerering`},help:{"v1-oljfk4-1m":`Reservmodeller för bildgenerering i prioritetsordning (leverantör/modell).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Modell för bildgenerering`},help:{"v1-g4yw0h-2o":`Valfri modell för bildgenerering (leverantör/modell) som används av den gemensamma bildgenereringsfunktionen.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Tidsgräns för bildgenerering (ms)`},help:{"v1-9yesfj-31":`Standardtidsgräns i millisekunder för förfrågningar till leverantören vid image_generate-anrop. timeoutMs för enskilda anrop åsidosätter detta.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Reservmodeller för musikgenerering`},help:{"v1-wyg9xe-1m":`Reservmodeller för musikgenerering i prioritetsordning (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Modell för musikgenerering`},help:{"v1-xs1e2h-2o":`Valfri modell för musikgenerering (provider/model) som används av den gemensamma funktionen för musikgenerering.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Reservmodeller för videogenerering`},help:{"v1-wpbf1e-1m":`Reservmodeller för videogenerering i prioritetsordning (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Modell för videogenerering`},help:{"v1-hfmlbl-2o":`Valfri modell för videogenerering (provider/model) som används av den gemensamma funktionen för videogenerering.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Tidsgräns för videogenerering (ms)`},help:{"v1-1bqj80s-4i":`Standardtidsgräns i millisekunder för förfrågningar till leverantören vid video_generate-anrop. timeoutMs för enskilda anrop åsidosätter detta, och detta värde åsidosätter leverantörens standardvärden.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Reservmodeller`},help:{"v1-t4djq2-24":`Reservmodeller i prioritetsordning (provider/model). Används när den primära modellen misslyckas.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Primär modell`},help:{"v1-1i8a1v4-v":`Primär modell (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Modellpolicy`},help:{"v1-z0txb7-2e":`Uttrycklig policy för modellåsidosättningar. Utelämna den eller lämna allow tomt för att tillåta valfri modell.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Tillåtna modeller`},help:{"v1-1fqace-3x":`Tillåtna modellreferenser för åsidosättningar. Accepterar alias, fullständiga "provider/model"-referenser och jokertecken för leverantörer, till exempel "openai/*". Om fältet är tomt tillåts valfri modell.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Modeller`},help:{"v1-13cvq23-4i":`Konfigurerad modellkatalog och inställningar per modell. Posterna anger alias, parametrar, metadata för körmiljön och åsidosättningar för kodläge; de begränsar inte modellåsidosättningar.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Modellkörmiljö för standardagenten`},help:{"v1-6km9kx-41":`Valfri körmiljöpolicy per modell för standardagenten. Använd detta för modellspecifika körmiljöundantag i stället för att ange en körmiljö för hela agenten.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`ID för standardagentens modellkörmiljö`},help:{"v1-1co96w7-4a":`ID för standardagentens modellkörmiljö: "openclaw", "auto", ett registrerat ID för en plugin-köradapter som "codex", eller ett alias för en CLI-backend som stöds, till exempel "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Kodläge`},help:{"v1-rsdl5o-6x":`OpenClaw Code Mode för just denna leverantör/modell: På tvingar fram aktivering, Av inaktiverar det och Standard ärver tools.codeMode.enabled. Agentspecifika aktiveringsinställningar har företräde. Detta ändrar inte den valda körmiljön eller Codex inbyggda Code Mode.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Omfattning för modellval`},help:{"v1-sj8owq-bl":`Omfattning för chattkommandon och uppdateringar av sessionsmodeller i Gateway utan uttrycklig omfattning: "session" (standard) ändrar endast den aktuella sessionen, "agent" uppdaterar även agentens primära modell och "global" uppdaterar även den gemensamma reservmodellen agents.defaults.model. Uttryckliga omfattningsflaggor har företräde; ändringar av konfigurerade standardvärden kräver ägar- eller administratörsbehörighet. Callback-väljare i Telegram och det inbäddade lokala TUI-gränssnittet gäller fortfarande endast sessionen.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Maximal PDF-storlek (MB)`},help:{"v1-1uig1dr-1u":`Maximal PDF-filstorlek i megabyte för PDF-verktyget (standard: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Maximalt antal PDF-sidor`},help:{"v1-11na7hp-1y":`Maximalt antal PDF-sidor som PDF-verktyget får bearbeta (standard: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Reservmodeller för PDF`},help:{"v1-89ebd8-19":`Reservmodeller för PDF i prioritetsordning (leverantör/modell).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`PDF-modell`},help:{"v1-2ktkxt-2y":`Valfri PDF-modell (leverantör/modell) för PDF-analysverktyget. Använder som standard imageModel, därefter sessionsmodellen.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Kodarkivets rotkatalog`},help:{"v1-j3sh74-2h":`Valfri rotkatalog för kodarkivet som visas på systempromptens körtidsrad (åsidosätter automatisk identifiering).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Källportsintervall för sandlådewebbläsarens CDP`},help:{"v1-1jkowdc-2b":`Valfri CIDR-lista över tillåtna källor för inkommande CDP-trafik vid containergränsen (till exempel 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Nätverk för sandlådewebbläsare`},help:{"v1-8m74ud-5w":`Docker-nätverk för sandlådewebbläsarens containrar (standard: openclaw-sandbox-browser). Använd det dedikerade standardnätverket eller ett anpassat bryggnätverk; "none" stöds inte eftersom webbläsarstyrning kräver publicerade CDP-portar.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Tillåt anslutning till containerns namnrymd i Docker-sandlådan`},help:{"v1-qm39de-4c":`FARLIG åsidosättning för nödfall som tillåter Docker-nätverksläget container:<id> i sandlådan. Detta ansluter till en annan containers namnrymd och försvagar sandlådans isolering.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPU:er för Docker-sandlådan`},help:{"v1-jj0yhw-4k":`Valfritt värde för GPU-vidarekoppling i Docker som skickas till --gpus, till exempel "all" eller "device=GPU-uuid". Kräver en kompatibel körmiljö på värden, såsom NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Mål för äldre sessionslagring`},help:{"v1-1xkej6i-2g":`Ägare för uppgraderingskompatibilitet för utfasade huvudagentrader och fasta äldre sessionslager.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Ägare av äldre sessionslagring`},help:{"v1-ommm7e-5w":`Agent som äger avvecklade huvudagentrader eller rader utan agentkoppling i ett fast äldre sessionslager efter att standardmarkören har avvecklats. Skrivs automatiskt vid uppgradering när den tidigare ägaren inte var main eller den enda agenten.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Valfri standardlista över tillåtna färdigheter som ärvs av agenter som utelämnar agents.entries.*.skills. Utelämna för obegränsade färdigheter, ange [] för att inte ge ärvande agenter några färdigheter och kom ihåg att ett uttryckligt agents.entries.*.skills ersätter denna standardinställning i stället för att slås samman med den.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Hoppa över skapande av initieringsfiler för arbetsytan`},help:{"v1-kbstgw-5v":`Hoppar över automatiskt skapande av arbetsytans initieringsfiler, men inte infogning av befintliga filer. För den inbäddade körmiljön anger du agents.defaults.contextInjection till "never" för att inaktivera infogning, såvida inställningen inte åsidosätts per agent.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Valfria initieringsfiler som hoppas över`},help:{"v1-1j2z4yj-4c":`Valfria initieringsfiler som inte ska skapas i agenternas arbetsytor. Giltiga värden: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md accepteras men har ingen effekt).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Startkontext`},help:{"v1-1ugsihy-5o":`Inledning till den första turen som hanteras av körmiljön för "/new" och "/reset" utan argument. Använd detta för att styra om de senaste dagliga minnesfilerna ska förladdas i den första prompten i stället för att be modellen avgöra vad som ska läsas.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Tillämpa startkontext vid`},help:{"v1-wav4a5-36":`Väljer vilka återställningskommandon utan argument som får startkontext: inkludera "new", "reset" eller båda (standard: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Antal dagar med dagligt minne i startkontext`},help:{"v1-4i5xcm-3p":`Antal daterade minnesfiler som ska läsas in, räknat bakåt från idag i användarens konfigurerade tidszon (standard: 2 för idag + igår).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Aktivera startkontext`},help:{"v1-1d5vz2u-4i":`Aktivera inledningen med startkontext för sessionsåterställningar utan argument (standard: true). Inaktivera detta för att återgå till beteendet med enbart prompt, utan dagligt minne som läses in vid körning.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Maximalt antal byte per fil i startkontext`},help:{"v1-11cbian-41":`Maximalt tillåtet antal byte per daglig minnesfil när startkontexten byggs (standard: 16384). Filer som överskrider denna gränssäkra läsgräns hoppas över.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Maximalt antal tecken per fil i startkontext`},help:{"v1-10z53s-2u":`Maximalt antal tecken som behålls från varje inläst daglig minnesfil i startinledningen (standard: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Maximalt totalt antal tecken i startkontext`},help:{"v1-sf676u-54":`Maximalt totalt antal tecken som behålls från alla inlästa dagliga minnesfiler i startinledningen (standard: 2800). Ytterligare filinnehåll kapas från inledningen när denna gräns nås.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Delegeringsläge för underagenter`},help:{"v1-pqewbk-5o":`Styr hur starkt delegering till underagenter uppmuntras enbart via prompten. Standardvärdet är "prefer" i varje agents huvudsession och "suggest" i övriga sessioner; "prefer" instruerar agenten starkt att delegera mer omfattande arbete via sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Mål för systemagent`},help:{"v1-1wwimo9-34":`Målinställningar för bakgrundsinferens med OpenClaw-systemagenten och Custodian samt utvalda operatörsläsningar utan angiven avgränsning.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Systemagentens ägare`},help:{"v1-15rvt92-8c":`Agent vars modell och autentiseringsuppgifter används för bakgrundskonsultationer med systemagenten och Custodian. Används även när models.list, models.authStatus, skills.status, doctor.memory.status eller ett infer-CLI-kommando som fastställer agentens modell- eller autentiseringstillstånd utelämnar agentId eller --agent; ett uttryckligen angivet agentId i begäran har alltid företräde.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Skrivindikatorns intervall (sekunder)`},help:{"v1-1y701ox-42":`Styr intervallet i sekunder för uppdateringar som håller skrivindikatorn aktiv för alla agenter. Öka värdet för att minska uppdateringsfrekvensen i alla kanaler som stöder skrivindikatorer.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Skrivindikatorns läge`},help:{"v1-m2hvpw-3m":`Styr när skrivindikatorn aktiveras för agenter: "never", "instant", "thinking" eller "message". Agentspecifika typingMode-inställningar åsidosätter detta standardvärde.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Hjälpmodell`},help:{"v1-1wg7h1a-7s":`Valfri billigare modell (provider/model eller alias) för korta interna uppgifter som att generera titlar och beskriva förloppet. Om värdet inte anges används den primära leverantörens deklarerade lilla modell när den finns tillgänglig (annars den primära modellen). Ange en tom sträng för att inaktivera routning till hjälpmodellen.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Reservmodeller för röst`},help:{"v1-faazv4-1b":`Röstmodeller i prioritetsordning att använda som reserv (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Röstmodell`},help:{"v1-1yeh3h4-2t":`Valfri röstmodell (provider/model) som används för tal, transkribering och röstfunktioner i realtid.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Tidsgräns för röst (ms)`},help:{"v1-1sbergs-32":`Standardtidsgräns i millisekunder för förfrågningar till leverantören vid röstmodellåtgärder, när anroparen stöder tidsgränser.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Arbetsyta`},help:{"v1-1u5ipll-5t":`Agentens standardarbetsyta för initierings- och minnesfiler. Används även som arbetskatalog när agents.defaults.cwd inte har angetts. Ange detta uttryckligen vid körning via omslutande skript så att sökvägar tolkas konsekvent.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Agentlista`},help:{"v1-1e0blk1-5i":`Uttrycklig lista över konfigurerade agenter med ID:n och valfria åsidosättningar för modell, verktyg, identitet och arbetsyta. Behåll samma ID:n över tid så att bindningar, godkännanden och sessionsroutning förblir konsekventa.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Äldre körmiljö för agenter`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`ID för äldre körmiljö för agenter`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Maximalt antal tecken för agentens initiering`},help:{"v1-rsf1es-4j":`Agentspecifik inställning för maximalt antal tecken i varje initieringsfil från arbetsytan som infogas i agentens systemprompt. Utelämna för att ärva agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Maximalt totalt antal tecken för agentens initiering`},help:{"v1-1bal68p-4y":`Agentspecifik inställning för maximalt totalt antal tecken i alla initieringsfiler från arbetsytan som infogas i agentens systemprompt. Utelämna för att ärva agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Kontextinfogning för agenten`},help:{"v1-1j68ys8-50":`Agentspecifik inställning för infogning av arbetsytans initieringsfiler i den inbäddade körmiljön. Utelämna för att ärva agents.defaults.contextInjection. Styr inte CLI-baserad promptförberedelse.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Kontextgränser för agenten`},help:{"v1-f1qxq8-3c":`Valfria agentspecifika inställningar för de riktade kontextbudgetparametrarna. Utelämnade fält ärver agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Maximalt antal tecken för agentens memory_get`},help:{"v1-12hlmsv-1v":`Agentspecifik inställning som ersätter standardgränsen för maximalt antal tecken för memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Maximalt antal tecken för agenten efter komprimering`},help:{"v1-15s0npd-1w":`Agentspecifik inställning för budgeten för utdrag ur AGENTS.md efter komprimering.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Agentens arbetskatalog`},help:{"v1-mv43ak-6a":`Arbetskatalog för den här agentens svarskörningar. Åsidosätter agents.defaults.cwd men inte cwd som skapats av sessionen; bootstrap- och minnesfiler stannar i arbetsytan. Stöder ~ och relativa sökvägar; en separat cwd kräver en körning utanför sandlådan.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Agentens beslutsmodell`},help:{"v1-1mih8bf-3j":`Agentspecifik beslutsmodell. Om värdet inte anges ärvs agents.defaults.decisionModel; en tom sträng inaktiverar beslutsanrop för den här agenten.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`Agentens inbäddade OpenClaw`},help:{"v1-uoomza-4b":`Valfria agentspecifika åsidosättningar för inbäddad OpenClaw. Använd detta för att aktivera striktare GPT-5-körningsbeteende för specifika agenter utan att ändra den globala standardinställningen.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Körningskontrakt för agentens inbäddade OpenClaw`},help:{"v1-1d1jaoi-7k":`Valfri agentspecifik åsidosättning av körningskontraktet för inbäddad OpenClaw. Ange "strict-agentic" för att aktivera strukturerad planuppföljning och återställning av turer utan synlig utdata för den agenten vid körningar som stöds med OpenAI/OpenAI Codex i GPT-5-familjen, eller "default" för att ärva standardbeteendet för körningar.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Agentens experimentella flaggor`},help:{"v1-1r06jov-2a":`Agentspecifika experimentella flaggor. Utelämnade fält ärver agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Agentens resurssnåla läge för lokala modeller`},help:{"v1-5o3tgx-58":`Åsidosättning per agent för felsökning av resurssnålt läge för lokala modeller. Aktivera endast när begränsning av valfria verktyg löser ett påvisat modellfel, utan att begränsa verktygen för alla agenter.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Standardinställning för agentens snabbläge`},help:{"v1-ev6028-41":`Valfri standardinställning per agent för snabbläge ("auto", "ultrafast", true eller false). Gäller när ingen åsidosättning av snabbläget har angetts för meddelandet eller sessionen.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Policy för direkta hjärtslagsmeddelanden`},help:{"v1-11gl9l0-41":`Åsidosättning per agent av policyn för leverans av hjärtslag via direktmeddelanden (DM). Använd "block" för agenter som endast ska skicka hjärtslagsaviseringar till andra destinationer än DM.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Tidsgräns för hjärtslag (sekunder)`},help:{"v1-kdetv4-6s":`Maximal tid i sekunder per agent för en agenttur med hjärtslag innan den avbryts. Lämna oangivet för att ärva den sammanslagna tidsgränsen för hjärtslag, därefter agents.defaults.timeoutSeconds om den är angiven, annars hjärtslagsintervallet begränsat till 600 sekunder.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Identitetsavatar`},help:{"v1-pzp9gr-1t":`Agentens avatar (sökväg relativ till arbetsytan, http(s)-URL eller data-URI).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Modellpolicy för agent`},help:{"v1-17d5je8-2r":`Policy för modellåsidosättning per agent. En uttrycklig tillåtelselista ersätter standardpolicyn för denna agent.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Tillåtna agentmodeller`},help:{"v1-v1ueke-5b":`Tillåtna referenser för modellåsidosättningar för den här agenten. Accepterar alias, fullständiga "provider/model"-referenser och prefix med avslutande jokertecken, till exempel "provider/*" eller "provider/namespace/*". Om värdet är tomt tillåts alla modeller.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Modellåsidosättningar för agenten`},help:{"v1-nld1vq-1v":`Agentspecifika åsidosättningar av modellkatalogen med fullständiga provider/model-ID:n som nycklar.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Körmiljö för agentens modell`},help:{"v1-7b59y-3s":`Valfri körmiljöpolicy per modell för den här agenten. Använd detta för agentspecifika modellundantag i stället för att ange en körmiljö för hela agenten.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`Körmiljö-ID för agentens modell`},help:{"v1-1ckfc39-46":`Agentspecifikt ID för modellens körmiljö: "openclaw", "auto", ett registrerat ID för ett insticksprograms körningsramverk, till exempel "codex", eller ett CLI-backendalias som stöds, till exempel "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Kodläge`},help:{"v1-91zu7f-7m":`OpenClaw-kodläge för den här agenten och exakt angiven provider/model: På tvingar fram aktivering, Av inaktiverar det och Standard ärver agentens aktiveringsinställning, därefter den delade modellåsidosättningen och slutligen tools.codeMode.enabled. Detta ändrar inte den valda körmiljön eller det inbyggda kodläget i Codex.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Standardinställning för agentens resonemang`},help:{"v1-13ly0xf-3m":`Valfri standardinställning per agent för resonemangets synlighet (on|off|stream). Gäller när ingen åsidosättning för resonemang har angetts för meddelandet eller sessionen.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Agentens körmiljö`},help:{"v1-avjgkf-3l":`Valfri körmiljöbeskrivning för den här agenten. Använd embedded för standardkörning i OpenClaw eller acp för standardinställningar för externa ACP-körningsramverk.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Agentens ACP-körmiljö`},help:{"v1-91zvdk-3i":`Standardinställningar för den här agentens ACP-körmiljö när runtime.type=acp. ACP-åsidosättningar på bindningsnivå har fortfarande företräde per konversation.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Agent i ACP-körningsramverket för agenten`},help:{"v1-1pm98vp-37":`Valfritt agent-ID i ACP-körningsramverket som ska användas för den här OpenClaw-agenten (till exempel codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Agentens ACP-backend`},help:{"v1-1u3cdsg-2n":`Valfri åsidosättning av ACP-backend för den här agentens ACP-sessioner (använder annars globala acp.backend).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Agentens ACP-arbetskatalog`},help:{"v1-d9p9rf-1t":`Valfri standardarbetskatalog för den här agentens ACP-sessioner.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Agentens ACP-läge`},help:{"v1-yatuk4-21":`Valfritt standardläge för den här agentens ACP-sessioner (persistent eller oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Agentens körmiljötyp`},help:{"v1-139fbk6-2r":`Körmiljötyp för den här agenten: "embedded" (OpenClaws standardkörmiljö) eller "acp" (standardinställningar för ACP-körsystemet).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`CDP-källintervall för agentens sandlådewebbläsare`},help:{"v1-1q1qyso-1d":`Agentspecifik åsidosättning av listan över tillåtna CIDR-intervall för CDP-källor.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Nätverk för agentens sandlådewebbläsare`},help:{"v1-13bdfww-4c":`Agentspecifik åsidosättning av Docker-nätverket för sandlådewebbläsaren. Använd ett bryggnätverk; "none" stöds inte eftersom webbläsarstyrning kräver publicerade CDP-portar.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Tillåt anslutning till containerns namnrymd i Docker för agentens sandlåda`},help:{"v1-1xtnseb-2i":`FARLIG agentspecifik åsidosättning för anslutningar till containerns namnrymd i sandlådans Docker-nätverksläge.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`Docker-GPU:er för agentens sandlåda`},help:{"v1-1kek1n2-1t":`Agentspecifik åsidosättning av direkt GPU-åtkomst via Docker för sandlådecontainrar.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Skills-filter för agent`},help:{"v1-igchue-6v":`Valfri tillåtelselista för agentens Skills. Om den utelämnas ärver agenten agents.defaults.skills om det är angivet; annars förblir Skills obegränsade. Ange [] för att inte tillåta några Skills. En uttrycklig lista ersätter ärvda standardvärden helt i stället för att slås samman med dem.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Gränser för agentens Skills`},help:{"v1-1sv10v9-4y":`Valfria agentspecifika åsidosättningar av budgetarna för Skills-delsystemet. Använd detta när en agent behöver en annan promptbudget för Skills utan att införa en andra generell konfigurationssökväg för kontextgränser.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Maximalt antal tecken i agentens Skills-prompt`},help:{"v1-dys63y-52":`Agentspecifik åsidosättning av teckenbudgeten för Skills-prompten. Detta utökar den befintliga konfigurationssökvägen skills.limits.maxSkillsPromptChars i stället för att hantera samma budget via contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegateToolsTo":{label:{"v1-bycm06-m":`Målagenter för verktygsdelegering`},help:{"v1-y7q6z7-d6":`Exakt angivna inbyggda målagenter som får utelämna den begärande agentens tools.deny när de startas. Kräver även allowAgents separat. Överlämningar med enbart nekanderegler bevarar alla icke-lokala begränsningar; restriktiva initiala profiler/tillåtelselistor eller transportmekanismer som inte stöds gör att överlämningen nekas i stället för att behörigheterna utökas. Inbyggda hjälpagenter med samma mål behåller sina egna ytterligare begränsningar. Avsändarbegränsade begäranden och ACP-begäranden använder aldrig denna behörighet. Återkallelse återställer den ursprungliga ögonblicksbilden av den begärande agenten.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Delegeringsläge för underagenter`},help:{"v1-1rkgh6p-4s":`Agentspecifik åsidosättning av hur starkt delegering till underagenter uppmuntras. Utelämna för att använda "prefer" i den här agentens huvudsession och "suggest" på andra ställen; ett uttryckligt "prefer" eller "suggest" har alltid företräde.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Agentens standardnivå för tänkande`},help:{"v1-173q7vy-43":`Valfri agentspecifik standardnivå för tänkande. Åsidosätter agents.defaults.thinkingDefault för den här agenten när ingen åsidosättning har angetts för meddelandet eller sessionen.`}},"agents%2Eentries%2E*%2Etools%2EagentToAgent":{label:{"v1-q7r7ya-o":`Agentens utgående meddelanden`},help:{"v1-xo2o9d-5d":`Policy enbart för agentens utgående meddelanden. Uttryckliga sändningsdestinationer ger inte läsbehörighet till sessioner eller åtkomst till status och begränsas fortfarande av globala regler för deltagande mellan agenter och begränsningar i sandlådan.`}},"agents%2Eentries%2E*%2Etools%2EagentToAgent%2Esend":{label:{"v1-1lxwft1-w":`Tillåtelselista för agentens sändningsdestinationer`},help:{"v1-tfolqu-ar":`Agent-id:n eller *-mönster som den här agenten får kontakta med sessions_send, även när tools.sessions.visibility är begränsad. Om värdet utelämnas ärvs synligheten; [] nekar vanliga sändningar mellan agenter. Globala tools.agentToAgent och sandlådebegränsningar gäller fortfarande. Ger inte åtkomst till listning, historik, sökning, status eller bevakning; svar hör endast till den skickade turen. Åtkomst till underordnade sessioner som ägs av den begärande parten är oförändrad.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Tillägg till agentens tillåtelselista för verktyg`},help:{"v1-1550ui9-46":`Agentspecifik tillåtelselista som lägger till verktyg utöver den globala policyn och profilpolicyn. Håll den snäv för att undvika att specialiserade agenters behörigheter utökas av misstag.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Agentens verktygspolicy per leverantör`},help:{"v1-mthxv9-4t":`Agentspecifika åsidosättningar av verktygspolicyn per leverantör för kanalavgränsad kontroll av funktioner. Använd detta när en enskild agent behöver striktare begränsningar för en leverantör än för andra.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Agentens kodläge`},help:{"v1-118t8u5-65":`Alternativ för kodläge per agent. Ett uttryckligt värde för enabled åsidosätter standardvärdena för aktivering i den delade modellen och globalt; en agentspecifik åsidosättning av modellens codeMode har företräde. Övriga alternativ slås samman med tools.codeMode och har företräde utan att ändra aktiveringen.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Agentens tidsgräns för körning (sekunder)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Åsidosättning av agentens GitHub CLI-identitet`},help:{"v1-mjwdh4-38":`Fullständig åsidosättning av den hanterade GitHub CLI-identiteten och Git-författaren för denna agent. Utelämna detta för att ärva systemidentiteten.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EallowInSandbox":{label:{"v1-1rxew98-12":`Tillåt agentens GitHub-identitet i sandlådan`},help:{"v1-17rsbdj-6g":`Tillåter denna agents hanterade GitHub-autentiseringsuppgifter och Git-författare i dess egen Docker- eller Podman-sandlåda (standard: false). Delad omfattning tillåter inte identitetsinjektion; andra backend-system avvisar provisionering. Säkerhetsgranskningen varnar medan detta är aktiverat.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`E-postadress för agentens Git-författare`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Namn på agentens Git-författare`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Typ av GitHub-autentiseringsuppgifter för agenten`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Version av agentens GitHub-profil`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Tillåtelselista för agentens meddelandeåtgärder`},help:{"v1-1g5gov3-67":`Tillåtelselista per agent för åtgärder i meddelandeverktyget. Ange en minimal lista, till exempel ["send"], för offentliga sandboxagenter så att läsning, redigering, borttagning, reaktioner och andra leverantörsspecifika meddelandeåtgärder förblir dolda och blockerade.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Agentens meddelanden mellan kontexter (mellan leverantörer)`},help:{"v1-pehesn-49":`Åsidosättning per agent för att skicka mellan leverantörer. Ärver den globala inställningen (standard: true). Ange false för att blockera meddelanden mellan leverantörer för den här agenten.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Agentens meddelanden mellan kontexter (samma leverantör)`},help:{"v1-s9u09h-4t":`Meddelandeskydd per agent för att skicka till andra konversationer hos samma leverantör. Ange både detta och allowAcrossProviders till false för offentliga agenter som endast ska kunna använda den aktuella konversationen.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Agentens verktygsprofil`},help:{"v1-1du76ix-57":`Åsidosättning per agent av valet av verktygsprofil när en agent behöver en annan grunduppsättning funktioner. Använd detta sparsamt så att skillnader i policy mellan agenter förblir avsiktliga och möjliga att granska.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Agentsvärm`},help:{"v1-420ljs-2c":`Agentspecifik åsidosättning för swarm. Värdena slås samman med och har företräde framför konfigurationen tools.swarm på toppnivå.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Agentens skrivindikatorläge`},help:{"v1-oxir52-2e":`Åsidosätter standardpolicyn för när skrivindikatorn ska aktiveras för en agent utan att påverka andra agenter.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Agentens hjälpmodell`},help:{"v1-1v9oskz-2z":`Valfri agentspecifik åsidosättning av hjälpmodellen för korta interna uppgifter. Åsidosätter agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Generation för agentägarskap`},help:{"v1-1lf38yr-95":`Beständig generationsmarkör för ägarskap i fleragentsystem. "explicit" innebär att bakgrundskanaler, heartbeat, konsultationer med systemagenter, Talk, cron och fristående CLI-operationer måste fastställa en ytspecifik ägare eller avbrytas när ingen ägare kan identifieras. OpenClaw anger detta automatiskt när en agentflotta skapas eller migreras; utelämna det för en ensam agent.`}},approvals:{label:{"v1-1m405m7-9":`Godkännanden`},help:{"v1-4y3in-5w":`Inställningar för dirigering av godkännanden som vidarebefordrar godkännandeförfrågningar för exec och insticksprogram till chattdestinationer utanför den ursprungliga sessionen. Låt dessa vara inaktiverade om inte operatörer behöver uttrycklig insyn i godkännanden via en separat kanal.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Vidarebefordran av exec-godkännanden`},help:{"v1-1r2mozk-5v":`Samlar inställningar för vidarebefordran av exec-godkännanden, inklusive aktivering, dirigeringsläge, filter och uttryckliga mål. Konfigurera detta när godkännandeförfrågningar måste nå driftkanaler i stället för enbart ursprungstråden.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Agentfilter för godkännanden`},help:{"v1-xip9a-4k":'Valfri lista över agent-ID:n som får ta emot vidarebefordrade godkännandeförfrågningar, till exempel `["primary", "ops-agent"]`. Använd detta för att undvika att skicka kanalaviseringar för orelaterade agenter.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Vidarebefordra körningsgodkännanden`},help:{"v1-1t0whe8-5s":`Aktiverar vidarebefordran av förfrågningar om körningsgodkännande till konfigurerade leveransdestinationer (standard: false). Låt detta vara inaktiverat i miljöer med låg risk och aktivera det endast när personer som hanterar godkännanden behöver förfrågningar som syns i kanaler.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Läge för vidarebefordran av godkännanden`},help:{"v1-1dedfo4-69":`Styr vart godkännandeförfrågningar skickas: "session" använder ursprungschatten, "targets" använder konfigurerade mål och "both" skickar till båda. Använd "session" som utgångspunkt och utöka endast när arbetsflödet kräver redundans.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Sessionsfilter för godkännanden`},help:{"v1-smeg8e-5u":'Valfria filter för sessionsnycklar som matchas som delsträngar eller mönster av typen reguljära uttryck, till exempel `["discord:", "^agent:ops:"]`. Använd snäva mönster så att endast avsedda godkännandekontexter vidarebefordras till delade destinationer.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Mål för vidarebefordran av godkännanden`},help:{"v1-17ah848-5u":`Uttryckliga leveransmål som används när vidarebefordringsläget omfattar targets, vart och ett med uppgifter om kanal och destination. Begränsa mållistor enligt principen om minsta behörighet och validera varje destination innan du aktiverar bred vidarebefordran.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`Konto-ID för godkännandemål`},help:{"v1-16zopng-5e":`Valfri kontoväljare för kanalkonfigurationer med flera konton när godkännanden måste skickas via ett specifikt konto. Använd detta endast när målkanalen har flera konfigurerade identiteter.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Målkanal för godkännanden`},help:{"v1-ji1igl-59":`Kanal-/leverantörs-ID som används för att leverera vidarebefordrade godkännanden, till exempel discord, slack eller ett kanal-ID för ett insticksprogram. Använd endast giltiga kanal-ID:n så att godkännanden inte misslyckas utan felmeddelande på grund av okända routningsvägar.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`Måltrådens ID för godkännanden`},help:{"v1-1axynw7-59":`Valfri måltråd eller målämne för kanaler som stöder leverans av vidarebefordrade godkännanden i trådar. Använd detta för att hålla godkännandetrafiken i drifttrådar i stället för i huvudkanaler.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Destination för godkännanden`},help:{"v1-1ijng7e-5n":`Destinationsidentifierare i målkanalen (kanal-ID, användar-ID eller trådens rotmeddelande beroende på leverantör). Kontrollera betydelsen för varje leverantör eftersom destinationsformatet skiljer sig mellan kanalintegrationer.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Vidarebefordran av godkännanden för insticksprogram`},help:{"v1-1m6pzxv-6b":`Samlar inställningar för vidarebefordran av godkännanden för insticksprogram, inklusive aktivering, routningsläge, filter och uttryckligen angivna mål. Oberoende av vidarebefordran av exekveringsgodkännanden. Konfigurera detta när godkännandeförfrågningar för insticksprogram måste nå driftkanaler.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Agentfilter för godkännanden för insticksprogram`},help:{"v1-b3test-4y":'Valfri lista över agent-ID:n som tillåts få godkännandeförfrågningar för insticksprogram vidarebefordrade, till exempel `["primary", "ops-agent"]`. Använd detta för att välja vilka agenters godkännandeförfrågningar som vidarebefordras.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Vidarebefordra godkännandeförfrågningar för insticksprogram`},help:{"v1-1ntctaf-3v":`Aktiverar vidarebefordran av godkännandeförfrågningar för insticksprogram till konfigurerade leveransdestinationer (standard: false). Oberoende av approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Läge för vidarebefordran av godkännandeförfrågningar för insticksprogram`},help:{"v1-1h62vy4-3z":`Styr vart godkännandeförfrågningar för insticksprogram skickas: "session" använder ursprungschatten, "targets" använder konfigurerade mål och "both" skickar till båda.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Sessionsfilter för godkännandeförfrågningar för insticksprogram`},help:{"v1-1eppxmt-57":'Valfria sessionsnyckelfilter som matchas som delsträngar eller mönster av typen reguljära uttryck, till exempel `["discord:", "^agent:ops:"]`. Använd snäva mönster så att endast avsedda godkännandekontexter vidarebefordras.'}},"approvals%2Eplugin%2Eslack":{label:{"v1-o7dlxi-m":`Slack-granskare för insticksprogram`},help:{"v1-1svd0ag-4x":`Policy för Slack-granskare vid godkännande av insticksprogram. Utelämna standardlistan över godkännare för att behålla kontots behörighetskontroll via allowFrom/defaultTo; ange [] för att neka beslut via Slack som standard.`}},"approvals%2Eplugin%2Eslack%2Eapprovers":{label:{"v1-r39jnl-u":`Standardgranskare i Slack för insticksprogram`},help:{"v1-auy576-5v":`Standardgranskare i Slack för insticksprogram, angivna som råa U/W-användar-ID:n inom det valda Slack-kontot eller som arbetsytekvalificerade värden i formatet team:<team-id>:user:<user-id>. Listor för insticksprogram och verktyg åsidosätter denna lista för sina egna förfrågningar.`}},"approvals%2Eplugin%2Eslack%2Eplugins":{label:{"v1-13wg4dk-v":`Åsidosättningar av granskare för Slack-plugin`},help:{"v1-16kb0vj-2r":`Åsidosättningar av granskare med det valda inbyggda verktygspluginets ID som nyckel. Verktygsnycklar kodar det råa verktygsnamnet.`}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Mål för vidarebefordran av plugingodkännanden`},help:{"v1-o92qze-3k":`Uttryckliga leveransmål som används när läget för vidarebefordran av plugingodkännanden inkluderar mål, vart och ett med kanal- och destinationsuppgifter.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`Konto-ID för plugingodkännandets mål`},help:{"v1-1wf3lqn-3j":`Valfri kontoväljare för kanalkonfigurationer med flera konton när plugingodkännanden måste dirigeras via en specifik kontokontext.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Målkanal för plugingodkännande`},help:{"v1-1mzhzi9-34":`Kanal-/leverantörs-ID som används för leverans av vidarebefordrade plugingodkännanden, till exempel discord, slack eller ett plugins kanal-ID.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`Tråd-ID för plugingodkännandets mål`},help:{"v1-1scaw9c-2v":`Valfri måltråd eller målämne för kanaler som stöder trådad leverans av vidarebefordrade plugingodkännanden.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Måldestination för plugingodkännande`},help:{"v1-sh5te1-31":`Destinationsidentifierare inom målkanalen (kanal-ID, användar-ID eller trådens rot beroende på leverantör).`}},attachments:{label:{"v1-8925gh-b":`Bilagor`},help:{"v1-1xvgkss-40":`Övergripande lagringsregler som delas av leverantörer och verktyg som lagrar medier. Använd ttlHours när allmänna mellanlagrade medier behöver rensas efter en viss tid.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`TTL för lagring av bilagor (timmar)`},help:{"v1-1g90day-9e":`Valfri lagringstid i timmar för lagrade medier som hanteras av den allmänna mtime-rensningen. Lämna värdet oangivet för att inaktivera rensningen, eller ange värden som 24 (1 dag) eller 168 (7 dagar) för att regelbundet ta bort äldre mellanlagrade medier. Hanterade utgående medier (bilagor som genereras i chatten) undantas och följer egna lagringsregler som tar hänsyn till SQLite och konversationshistorik.`}},audio:{label:{"v1-11wczsp-5":`Ljud`}},auth:{label:{"v1-5xz433-4":`Autentisering`},help:{"v1-1eu3aud-5c":`Rot för autentiseringsprofiler som används för leverantörsuppgifter i flera profiler och reservväxlingsordning baserad på väntetid. Håll profilerna minimala och tydliga så att den automatiska reservväxlingen förblir granskningsbar.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Ordning för autentiseringsprofiler`},help:{"v1-1x6kknp-1w":`Ordnade ID:n för autentiseringsprofiler per leverantör (används för automatisk reservväxling).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Autentiseringsprofiler`},help:{"v1-kzoqcn-1j":`Namngivna autentiseringsprofiler (leverantör + läge + valfri e-postadress).`}},bindings:{label:{"v1-1hcih9f-8":`Bindningar`},help:{"v1-y7hrzb-4i":`Övergripande bindningsregler för routning och beständigt ägarskap för ACP-konversationer. Använd type=route för normal routning och type=acp för beständiga bindningar till ACP-körmiljön.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Åsidosättningar för ACP-bindningar`},help:{"v1-1t4lisi-44":`Valfria ACP-åsidosättningar per bindning för bindings[].type=acp. Det här lagret åsidosätter standardvärdena i agents.entries.*.runtime.acp för den matchade konversationen.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`ACP-backend för bindning`},help:{"v1-rsrbkp-2x":`Åsidosättning av ACP-backend för den här bindningen (använder annars ACP-backend i agentens körmiljö och därefter globala acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Arbetskatalog för ACP-bindning`},help:{"v1-ngpkj0-1y":`Åsidosättning av arbetskatalog för ACP-sessioner som skapas från den här bindningen.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Etikett för ACP-bindning`},help:{"v1-azce82-23":`Lättläst etikett för ACP-status och diagnostik i den här bundna konversationen.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Läge för ACP-bindning`},help:{"v1-cgq8xv-1v":`Åsidosättning av ACP-sessionsläge för den här bindningen (persistent eller oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`Agent-ID för bindning`},help:{"v1-17ra0cl-4m":`ID för målagenten som tar emot trafik när bindningens motsvarande matchningsregel uppfylls. Använd endast giltiga, konfigurerade agent-ID:n så att routningen inte misslyckas vid körning.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Matchningsregel för bindning`},help:{"v1-sc1w2e-51":`Objekt med matchningsregler som avgör när en bindning gäller, inklusive kanal och valfria begränsningar för konto eller motpart. Håll reglerna snävt avgränsade för att undvika att agenter oavsiktligt tar över i andra sammanhang.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`Konto-ID för bindning`},help:{"v1-1d209g7-56":`Valfri kontoväljare för kanalkonfigurationer med flera konton, så att bindningen endast gäller en identitet. Använd detta när routningen behöver avgränsas till ett konto och lämna det annars utan värde.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Kanal för bindning`},help:{"v1-d22m5-54":"Identifierare för den kanal eller leverantör som bindningen gäller, till exempel `telegram`, `discord` eller ett kanal-ID för ett insticksprogram. Använd den konfigurerade kanalnyckeln exakt så att utvärderingen av bindningar fungerar tillförlitligt."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`Guild-ID för bindning`},help:{"v1-jzzfj1-4x":`Valfri begränsning baserad på guild-/server-ID av Discord-typ för utvärdering av bindningar i miljöer med flera servrar. Använd detta när samma motpartsidentifierare kan förekomma i olika guilds.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Motpartsmatchning för bindning`},help:{"v1-gcjxff-4i":`Valfri motpartsmatchning för specifika konversationer, inklusive motpartstyp och motparts-ID. Använd detta när endast en direktkonversation, grupp eller kanal ska knytas till en agent.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`Motparts-ID för bindning`},help:{"v1-86fbh7-4b":`Konversationsidentifierare som används vid motpartsmatchning, till exempel ett chatt-ID, kanal-ID eller grupp-ID från leverantören. Ange detta exakt för att undvika uteblivna matchningar utan varning.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Motpartstyp för bindning`},help:{"v1-uufscp-4x":`Motpartens konversationstyp: "direct", "group", "channel" eller äldre "dm" (föråldrat alias för direct). Använd helst "direct" i nya konfigurationer och se till att typen stämmer överens med kanalens semantik.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Roller för bindning`},help:{"v1-6s891m-4k":`Valfri rollbaserad filterlista som används av leverantörer som kopplar roller till chattkontexten. Använd detta för att dirigera trafik från privilegierade roller eller driftroller till specialiserade agenter.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`Team-ID för bindning`},help:{"v1-hh9ps2-48":`Valfri begränsning till team-/arbetsyte-ID för leverantörer som organiserar chattar under team. Lägg till detta när du behöver isolera bindningar till en viss arbetsyta.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Bindningssession`},help:{"v1-x325l2-4v":`Valfria åsidosättningar av routningssessionen för konversationer som matchas av denna bindning. Använd detta när en avgränsad routning ska behålla samma agent men isolera sessionskontinuiteten på ett annat sätt.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`DM-omfattning för bindningssession`},help:{"v1-10sg3xw-4s":`Valfri åsidosättning av DM-sessionens omfattning för denna routningsbindning. Behåll till exempel session.dmScope="main" globalt och använd samtidigt "per-account-channel-peer" för utvalda direktkontakter.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Gruppomfattning för bindningssession`},help:{"v1-1ys2u7k-6n":`Valfri åsidosättning av grupp-/kanalsessionens omfattning för denna routningsbindning. "per-group" håller matchade rum åtskilda och låter agentens huvudsession bevaka dem i bakgrunden oavsett dmScope; "main" slår samman deras kontext med huvudsessionen och kräver ingen bevakning.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Bindningstyp`},help:{"v1-172mhtk-3o":`Typ av bindning. Använd "route" (eller utelämna för äldre routningsposter) för normal routning och "acp" för beständiga ACP-konversationsbindningar.`}},broadcast:{label:{"v1-awqjh0-j":`Grupptrådar för agenter`},help:{"v1-1tz72sr-6b":`Använd grupptrådar för agenter för att köra flera konfigurerade agenter i en och samma inkommande konversation, var och en i sin egen session. Kanalspecifika poster stöder ett begränsat antal uppföljningsrundor; äldre arrayer med WhatsApp-kontakter behåller beteendet med en enda körning.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Deltagare och alternativ för agentgrupper`},help:{"v1-1b63zmt-7d":`Använd ett kanalkvalificerat peer-ID (till exempel "telegram:-100123") för att konfigurera en array med agent-ID:n eller ett strikt objekt med agents, mentionGating, maxRounds och maxTurns. Kvalificerade poster har företräde framför äldre WhatsApp-peer-nycklar och tillåter högst 16 agenter.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Deltagare i agentgruppen`},help:{"v1-g5o0ky-43":`Deltagarnas agent-ID:n från agents.entries (högst 16). Varje deltagare använder sin egen session för denna kanal, detta konto, denna konversation och denna tråd.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Maximalt antal omgångar för agentgruppen`},help:{"v1-i6v4jc-5a":`Maximalt antal omgångar per inkommande meddelande, inklusive den första omgången (heltal: 1–4, standard: 1). Uppföljande omgångar delar svar från övriga deltagare i begränsad omfattning och med angiven avsändare, och avslutas när alla deltagare avstår.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Maximalt antal turer för agentgruppen`},help:{"v1-1kiv8dy-72":`Maximalt antal deltagarturer per inkommande meddelande över alla omgångar (heltal: 1–32, standard: agents.length). Platser reserveras före parallell fördelning; detta begränsar agentturer, inte faktiska meddelandedelar eller sändningar via verktyg. Budgetar återupptas inte efter omstart.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Urval via omnämnanden i agentgruppen`},help:{"v1-uay9zu-5u":`Välj endast uttryckligen @omnämnda deltagare när någon matchar; kör annars alla deltagare (standard: true). Enbart namn eller emojier väljer inte deltagare. Kanalernas tillåtelselistor och tillträdesregler gäller fortfarande.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Strategi för agentgruppen`},help:{"v1-p4k9hu-4q":`Deltagarnas körordning: "parallel" (standard) kör agenter samtidigt, medan "sequential" kör dem i konfigurerad ordning. Varje omgång slutförs innan nästa börjar.`}},browser:{label:{"v1-13dzmen-7":`Webbläsare`},help:{"v1-5b74wi-5l":`Körningsinställningar för webbläsaren för lokal CDP-anslutning eller CDP-anslutning på distans, profilroutning och hantering av skärmbilder/ögonblicksbilder. Behåll standardinställningarna om ditt automatiseringsflöde inte kräver anpassade transportinställningar för webbläsaren.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Tillåt import av systemprofil`},help:{"v1-1lsvlxw-5w":`Tillåter macOS-värdar att importera kakor från en lokal systemprofil för en webbläsare i Chrome-familjen till en hanterad OpenClaw-webbläsarprofil. Inaktivera detta för att förhindra import av kakor från webbläsarprofiler och den tillhörande samtyckesdialogen för macOS-nyckelringen.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Webbläsarläge med enbart anslutning`},help:{"v1-xaw7xm-4s":`Begränsar webbläsarläget till enbart anslutning utan att starta lokala webbläsarprocesser. Använd detta när alla webbläsarsessioner hanteras externt av en CDP-leverantör på distans.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`Webbläsarens CDP-URL`},help:{"v1-2n72jb-65":`URL till CDP/DevTools-slutpunkten som används för att ansluta till en externt hanterad webbläsarinstans. Använd detta för centraliserade webbläsarvärdar, tunnlar eller anslutning till befintliga sessioner, och begränsa åtkomsten till URL:en till betrodda nätverksvägar.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Webbläsarens standardprofil`},help:{"v1-a6xo96-52":`Namnet på den webbläsarprofil som väljs som standard när anropare inte uttryckligen väljer en profil. Använd en stabil profil med begränsade behörigheter som standard för att minska risken att tillstånd från ett annat sammanhang används av misstag.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Webbläsare aktiverad`},help:{"v1-1m3zcs-5g":`Aktiverar webbläsarfunktioner i gatewayen så att webbläsarverktyg och CDP-drivna arbetsflöden kan köras. Inaktivera när webbläsarautomatisering inte behövs för att begränsa tillgängliga funktioner och minska arbetet vid uppstart.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Skriptutvärdering i webbläsaren aktiverad`},help:{"v1-1oa79mq-59":`Aktiverar hjälpfunktioner på webbläsarsidan för skriptutvärdering under körning där detta stöds. Låt vara inaktiverat om dina arbetsflöden inte kräver utvärderingsfunktioner utöver ögonblicksbilder och navigering.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Sökväg till webbläsarens körbara fil`},help:{"v1-1dshhkn-6g":`Uttrycklig sökväg till webbläsarens körbara fil när automatisk identifiering inte räcker till i din värdmiljö. Använd en stabil absolut sökväg, eller en sökväg som börjar med ~ för hemkatalogen i ditt operativsystem, så att startbeteendet förblir förutsägbart efter omstarter.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Relä för webbläsartillägg`},help:{"v1-6ywlwr-4e":`Kompatibilitetsinställningar för autentisering i Chrome-tilläggsreläet. Behåll stödet för äldre autentisering endast så länge äldre parkopplade tillägg eller externa CDP-klienter fortfarande behöver det.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Tillåt äldre autentisering för webbläsarrelä`},help:{"v1-pj2e90-63":`Accepterar tillfälligt äldre reläautentisering med Bearer, Basic och token-underprotokoll. Standardvärde: true under en migreringsperiod. Ange false när alla tillägg och externa CDP-klienter använder Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Webbläsarläge utan grafiskt gränssnitt`},help:{"v1-1rswq8j-5a":`Tvingar webbläsaren att starta utan grafiskt gränssnitt när den lokala startfunktionen startar webbläsarinstanser. Behåll detta läge aktiverat i servermiljöer och inaktivera det endast när felsökning med synligt gränssnitt krävs.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Webbläsarläge utan sandlåda`},help:{"v1-slntux-4w":`Inaktiverar flaggor för sandlådeisolering i Chromium för miljöer där sandlådan inte fungerar vid körning. Låt detta vara avstängt när det är möjligt eftersom skyddet genom processisolering försämras.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Webbläsarprofiler`},help:{"v1-1x8lf05-51":`Anslutningsmappning för namngivna webbläsarprofiler som används för explicit routning till CDP-portar eller URL:er med valfria metadata. Använd konsekventa profilnamn och undvik överlappande definitioner av ändpunkter.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Läge för enbart anslutning i webbläsarprofil`},help:{"v1-2b5zs0-5a":`Profilspecifik åsidosättning som hoppar över lokal webbläsarstart och endast ansluter till en befintlig CDP-ändpunkt. Användbart när en profil hanteras externt medan andra startas lokalt.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`CDP-port för webbläsarprofil`},help:{"v1-gx1yiq-49":`Profilspecifik lokal CDP-port som används vid anslutning till webbläsarinstanser via port i stället för URL. Använd unika portar för varje profil för att undvika anslutningskonflikter.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`CDP-URL för webbläsarprofil`},help:{"v1-x491r0-64":`Profilspecifik URL till en CDP/DevTools-ändpunkt som används för explicit webbläsarroutning via profilnamn. Använd detta för fjärrvärdar för CDP, tunnlar eller profiler med befintliga sessioner som ska ansluta via en aktiv Chrome DevTools-ändpunkt.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Drivrutin för webbläsarprofil`},help:{"v1-17byyx6-5r":`Drivrutinsläge för varje webbläsarprofil. Använd "openclaw" (eller äldre "clawd") för CDP-baserade profiler, "existing-session" för anslutning via Chrome DevTools MCP eller "extension" för den autentiserade reläfunktionen i Chrome-tillägget.`}},"browser%2Eprofiles%2E*%2Eengine":{label:{"v1-w0e8eg-m":`Motor för webbläsarprofil`},help:{"v1-r9zu90-8k":`Förinställning för webbläsarmotorns funktioner: "chromium" (standard) eller experimentella "lightpanda" för semantisk DOM-navigering. Lightpanda kräver en uttryckligen angiven ws/wss cdpUrl som är dedikerad till en enda profil samt attachOnly: true, startar aldrig en lokal webbläsare och stöder inte visuella skärmbilder eller andra funktioner som endast finns i Chromium.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Sökväg till körbar fil för webbläsarprofil`},help:{"v1-29azyv-4w":`Profilspecifik sökväg till webbläsarens körbara fil för hanterade webbläsarprofiler som startas lokalt. Åsidosätter browser.executablePath och accepterar sökvägar som börjar med ~ för operativsystemets hemkatalog.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Läge utan grafiskt gränssnitt för webbläsarprofil`},help:{"v1-p4jtgv-4u":`Profilspecifik inställning som åsidosätter läget utan grafiskt gränssnitt för webbläsarinstanser som startas lokalt. Använd detta när en profil ska köras utan grafiskt gränssnitt utan att tvinga fram browser.headless för alla andra profiler.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Chrome MCP-argument för webbläsarprofil`},help:{"v1-rc45ke-5g":`Extra profilspecifika Chrome DevTools MCP-argument för anslutning med existing-session, till exempel --no-usage-statistics. Slutpunktsargument här åsidosätter den inbyggda automatiska anslutningen eller valet av webbläsar-URL.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Chrome MCP-kommando för webbläsarprofil`},help:{"v1-1xpty8o-2h":`Profilspecifikt Chrome DevTools MCP-kommando för anslutning till en befintlig session. Standardvärdet är npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Katalog för användardata i webbläsarprofil`},help:{"v1-5xvgex-9h":`Profilspecifik katalog för Chromium-användardata för anslutning till en befintlig session via Chrome DevTools MCP. Använd detta för Brave, Edge, Chromium eller andra Chrome-profiler än standardprofilen när den inbyggda automatiska anslutningen skulle välja fel katalog för webbläsardata på den valda värden eller webbläsarnoden. Sökvägar som börjar med ~ expanderas till operativsystemets hemkatalog.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Standardinställningar för webbläsarögonblicksbilder`},help:{"v1-v19wdy-4y":`Standardkonfiguration för att ta ögonblicksbilder som används när anropare inte anger uttryckliga alternativ för ögonblicksbilder. Anpassa detta för ett enhetligt beteende i alla kanaler och automatiseringsflöden.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Läge för webbläsarögonblicksbilder`},help:{"v1-joeyxp-5c":`Standardläge för extrahering av ögonblicksbilder som styr hur sidinnehåll omvandlas för användning av agenter. Välj det läge som ger rätt balans mellan läsbarhet, återgivningstrohet och tokenförbrukning för dina arbetsflöden.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`SSRF-policy för webbläsaren`},help:{"v1-1qbp9im-5e":`Inställningar för skydd mot förfalskade förfrågningar på serversidan för hämtningsvägar i webbläsaren och nätverket som kan nå interna värdar. Behåll restriktiva standardinställningar i produktion och tillåt endast uttryckligen godkända mål.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Tillåtna värdnamn för webbläsaren`},help:{"v1-1rng39-2k":`Exakta värdnamn eller IP-adressliteraler som tillåts av webbläsarens SSRF-policykontroller. Håll listan så kort som möjligt.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Tillåt unikt lokalt IPv6-adressintervall i webbläsaren`},help:{"v1-1glx5cy-2c":`Tillåt unika lokala IPv6-adresser (fc00::/7) i betrodda proxymiljöer med falska IP-adresser.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Tillåt RFC 2544-adressintervallet för prestandatester i webbläsaren`},help:{"v1-10ateu3-2i":`Tillåt IP-adresser i RFC 2544-intervallet för prestandatester (198.18.0.0/15) i betrodda proxymiljöer med falska IP-adresser.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Blockerade värdnamn i webbläsaren`},help:{"v1-nug0we-6k":`Värdnamnsmönster som blockeras före DNS och tillåtelseregler, även när åtkomst till privata nätverk är aktiverad. Stöder exakta värdnamn och "*.example.com" för enbart underdomäner; lägg till "example.com" separat för att blockera rotdomänen. Om värdet är tomt eller inte angivet läggs inga blockeringar till.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Tillåt privata nätverk i webbläsaren (riskfyllt)`},help:{"v1-17103pi-4m":`Tillåter åtkomst till privata nätverks adressintervall från webbläsarverktyg. Inaktiverat som standard när värdet inte är angivet; aktivera endast för uttryckligen betrodda destinationer i privata nätverk.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Rensning av webbläsarflikar`},help:{"v1-1ctwaad-4y":`Policy för rensning efter bästa förmåga av webbläsarflikar som öppnas av primäragentens sessioner. Behåll aktiverad för att undvika att inaktuella flikar i sandlådor eller hanterade webbläsare samlas i långlivade gateways.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Rensning av webbläsarflikar aktiverad`},help:{"v1-4sv97p-3u":`Aktiverar rensning av inaktiva, spårade webbläsarflikar för primäragentens sessioner. Inaktivera endast när externa verktyg hanterar flikarnas hela livscykel.`}},channels:{label:{"v1-1ju93md-8":`Kanaler`},help:{"v1-12yv6ma-5n":`Konfigurationer för kanalleverantörer samt gemensamma standardinställningar som styr åtkomstpolicyer, synlighet för livstecken och beteende per gränssnitt. Håll standardinställningarna centraliserade och åsidosätt dem per leverantör endast vid behov.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Standardinställningar för kanaler`},help:{"v1-uz6veb-4p":`Standardbeteende för kanaler som tillämpas för alla leverantörer när leverantörsspecifika inställningar saknas. Använd detta för att säkerställa en enhetlig grundpolicy innan inställningarna finjusteras per leverantör.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Standardskydd mot botloopar`},help:{"v1-1lpznyk-4w":`Standardinställningar för parvist loopskydd för kanalleverantörer som stöder skydd mot loopar mellan botar. Använd leverantörsspecifika åsidosättningar endast när en kanal behöver en annan budget.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Standardväntetid för botloopar i sekunder`},help:{"v1-1yl5ird-2z":`Väntetid i sekunder som tillämpas på ett par när det överskrider loopbudgeten. Standardvärdet för kanaler som stöder funktionen är 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Standardskydd mot botloopar aktiverat`},help:{"v1-3ruik-4r":`Aktiverar parvist loopskydd som standard för kanaler som stöder funktionen när botskrivna meddelanden kan nå vidarebefordran. Leverantörer kan fortfarande inaktivera skyddet när botar ignoreras.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Standardantal händelser per tidsfönster för botloopar`},help:{"v1-1u0mdjc-41":`Maximalt antal händelser som ett avsändar-/mottagarpar får utbyta inom det konfigurerade tidsfönstret innan händelser börjar undertryckas. Standardvärdet för kanaler som stöder detta är 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Standardlängd på tidsfönster för botloopar i sekunder`},help:{"v1-12xpmen-2m":`Längden i sekunder på det glidande tidsfönstret för loopgränser per par. Standardvärdet för kanaler som stöder detta är 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Standardsynlighet för kontext`},help:{"v1-1hze3g1-5o":`Standardsynlighet för kompletterande kontext från hämtade citat, trådar och historik: "all" (behåll all kontext), "allowlist" (endast tillåtna avsändare) eller "allowlist_quote" (tillåtna avsändare samt uttryckliga citat).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Standardpolicy för grupper`},help:{"v1-ntl9m4-4n":`Standardpolicy för grupper i alla kanaler: "open", "disabled" eller "allowlist". Behåll "allowlist" för säkrare produktionsmiljöer om inte brett gruppdeltagande är avsikten.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Standardsynlighet för livstecken`},help:{"v1-49bw75-4v":`Standardinställningar för synlighet för livstecken i statusmeddelanden från leverantörer/kanaler. Justera detta globalt för att minska störande uppdateringar om normal drift samtidigt som varningar förblir synliga.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Visa varningar för livstecken`},help:{"v1-8dk8zx-4g":`Visar varningar från livsteckenskontrollen om försämrad status eller fel när värdet är true, så att problem snabbt uppmärksammas i operatörskanaler. Låt vara aktiverat i produktion så att fel i kanalerna syns.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Visa OK för livsteckenskontroll`},help:{"v1-17tg3mk-4z":`Visar poster med normal/OK-status från livsteckenskontrollen i kanalernas statusutdata när värdet är true. Behåll false i miljöer med mycket brus och aktivera endast när operatörer behöver uttrycklig bekräftelse på normal drift.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Använd indikator för livsteckenskontroll`},help:{"v1-1w12cs2-4m":`Aktiverar kompakt visning av livsteckenskontrollen med indikatorer i stället för utförlig statustext där det stöds. Använd indikatorläget för informationstäta instrumentpaneler med många aktiva kanaler.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Implicita omnämnanden som standard`},help:{"v1-4gtdyv-48":`Standardpolicy för om svar till boten, citering av boten och trådar där boten deltar aktiverar meddelandekanaler som stöder detta utan ett uttryckligt omnämnande.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Implicita omnämnanden vid citering av boten som standard`},help:{"v1-va1u5v-2v":`Behandla citerade botmeddelanden som implicita omnämnanden som standard. Standardvärdet är true för bakåtkompatibilitet.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Implicita omnämnanden vid svar till boten som standard`},help:{"v1-lm44c3-39":`Behandla svar på botens egna meddelanden som implicita omnämnanden som standard. Standardvärdet är true för bakåtkompatibilitet.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Implicita omnämnanden vid tråddeltagande som standard`},help:{"v1-160205h-3o":`Behandla som standard uppföljningar i trådar där boten har deltagit som implicita omnämnanden. Standardvärdet är true för bakåtkompatibilitet.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Modellåsidosättningar per kanal`},help:{"v1-1b01spx-2p":`Mappa leverantör -> kanal-id / DM-motpartens id -> modellåsidosättning (värdena är provider/model eller alias).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Molnarbetare`},help:{"v1-10carc4-5v":`Valfria profiler för molnarbetare i tillfälliga fjärrmiljöer. När det här avsnittet utelämnas eller saknar profiler är det fortsatt inte möjligt att skapa molnarbetare, och det befintliga beteendet för gateway-/nodstatus förblir oförändrat.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Skrivbord för molnarbetare (experimentellt)`},help:{"v1-vllayc-3n":`Aktiverar det experimentella gränssnittet worker.desktop.observe och skrivbordspanelen i Control UI för molnarbetarmiljöer med skrivbordsstöd.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Pool med förberedda molnarbetare`},help:{"v1-rw51o5-6b":`Gränser för förberedda molnarbetare som hålls redo för senare sessioner. Reserver medför kostnader för maskiner i drift tills leverantörens rensning är klar. Deras fasta utgångstid följer projektets faktiska behov och leverantörens befintliga inaktivitetspolicy.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Maxgräns för redo molnarbetare i reserv`},help:{"v1-1mpd1dt-7u":`Gemensam gräns för Gateway för otilldelade, förberedda molnarbetare i alla projekt och profiler (standard: 4). Arbetare som förbereds och reserver vars rensning inte har bekräftats räknas in i gränsen. Ange 0 för att avveckla otilldelade reserver och inaktivera påfyllning, men behålla återanvändning av ögonblicksbilder och aktiva sessioner.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Molnarbetarprofiler`},help:{"v1-eii67l-3j":`Namngivna molnarbetarprofiler. Varje profil väljer en arbetarleverantör som registrerats av ett insticksprogram och innehåller leverantörsspecifika inställningar.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Molnarbetarprofil`},help:{"v1-1v2w7jl-4u":`En molnarbetarprofil som väljs efter namn när en miljö skapas. Lagra leverantörens autentiseringsuppgifter i referenser som stöds i stället för att bädda in hemliga uppgifter i det här blocket.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Installationsmetod för molnarbetare`},help:{"v1-blrtbf-74":`Installationsmetod för arbetare: "bundle" (standard) överför gatewayens installerade bygge med innehållshash och stöder publicerade versioner, utvecklingsversioner och opublicerade versioner; "npm" installerar exakt samma version som gatewayen och är bara tillgänglig när den versionen har publicerats.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Molnarbetarleverantör`},help:{"v1-1p4s4c1-44":`Id för arbetarleverantören som registrerats av ett insticksprogram. Det konfigurerade insticksprogrammet måste exponera detta id innan gatewayen kan skapa miljöer utifrån profilen.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Målantal för reserven av klara molnarbetare`},help:{"v1-1nwve9s-7w":`Målantal otilldelade, förberedda arbetare per kvalificerat projekt som använder den här profilen (standard: 1), begränsat av det Gateway-övergripande taket för poolen av förberedda arbetare. Ange 0 för att inaktivera profilens reserver men behålla återanvändning av ögonblicksbilder. Arbetare som förbereds och reserver vars rensning ännu inte bekräftats räknas in i målantalet.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Leverantörsinställningar för molnarbetare`},help:{"v1-mq7u32-4j":`Leverantörsspecifika inställningar som valideras av det valda insticksprogrammet. Använd SecretRef-objekt för värden som innehåller hemligheter; opaka inställningar får ingen automatisk upplösning av hemligheter.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Inaktivitetstid före paus av molnarbetare`},help:{"v1-1keuwgh-4w":`Frigör automatiskt en inaktiv molnarbetare efter den här tiden, till exempel 45m eller 2h; nästa meddelande etablerar en ersättare. Minimum: 1m. Lämna oangivet för att låta arbetarna fortsätta köras.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Projektprofiler för molnarbetare`},help:{"v1-1kkfrif-46":`Standardprofilnamn för molnarbetare med normaliserad kodförrådsidentitet i gemener (host/owner/repo) som nyckel. Explicit angivna profil-id:n vid utsändning har företräde.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Projektprofil för molnarbetare`},help:{"v1-1mux5u0-30":`Profilnamn för molnarbetare som används som standard när origin för en sessions arbetskatalog matchar den här kodförrådsidentiteten.`}},"cloudWorkers%2ErequiredProfile":{label:{"v1-1rqoa9j-n":`Obligatorisk arbetarprofil`},help:{"v1-1q30qf7-57":`Kräv att varje session körs med den här arbetsnodsprofilen. Sessioner placeras automatiskt och kan inte falla tillbaka på körning i Gateway. Otillgängliga arbetsnoder blockerar samtalsturer, inte starten av Gateway.`}},commands:{label:{"v1-15x4mpf-8":`Kommandon`},help:{"v1-1gi0dr2-5a":`Styr gränssnitt för chattkommandon, ägarbegränsningar och åtkomst till kommandon med utökad behörighet hos olika leverantörer. Behåll standardinställningarna om du inte behöver striktare operatörskontroller eller bredare tillgång till kommandon.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Åtkomstregler för kommandon med utökad behörighet`},help:{"v1-7azkw-5g":`Definierar regler för att tillåta kommandon med utökad behörighet per kanal och avsändare i kommandogränssnitt på ägarnivå. Använd snävt avgränsade, leverantörsspecifika identiteter så att privilegierade kommandon inte blir tillgängliga för breda grupper av chattanvändare.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Tillåt chattkommandot Bash`},help:{"v1-83ah7w-36":"Tillåt chattkommandot bash (`!`; alias `/bash`) att köra skalkommandon på värddatorn (standard: false; kräver tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Tid för Bash i förgrunden (ms)`},help:{"v1-1o0o4dw-2c":`Hur länge bash väntar innan körningen flyttas till bakgrunden (standard: 2000; 0 flyttar körningen till bakgrunden omedelbart).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Tillåt /config`},help:{"v1-151bb7c-21":`Tillåt chattkommandot /config att läsa och skriva konfiguration på disk (standard: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Tillåt /debug`},help:{"v1-y1lc3j-1y":`Tillåt chattkommandot /debug för åsidosättningar som endast gäller under körning (standard: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Tillåt /mcp`},help:{"v1-1rtwcgd-2o":`Tillåt chattkommandot /mcp att hantera konfigurationen för OpenClaw MCP-servrar under mcp.servers (standard: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Inbyggda kommandon`},help:{"v1-dighr2-5n":`Registrerar inbyggda snedstrecks- och menykommandon i kanaler som stöder kommandoregistrering (Discord, Slack, Telegram). Låt detta vara aktiverat så att kommandona är lätta att hitta, om du inte avsiktligt använder arbetsflöden med enbart textkommandon.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Inbyggda färdighetskommandon`},help:{"v1-19gtqci-5h":`Registrerar inbyggda färdighetskommandon så att användare kan anropa färdigheter direkt från leverantörens kommandomenyer där detta stöds. Anpassa detta efter din färdighetspolicy så att de tillgängliga kommandona motsvarar operatörernas förväntningar.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Kommandoägare`},help:{"v1-1di38gv-3y":`Uttrycklig tillåtelselista över ägare för kommandon som är begränsade till ägare. Använd kanalspecifika ID:n (valfritt med prefix som "whatsapp:+15551234567"). '*' ignoreras.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Tillåt /plugins`},help:{"v1-akwy9y-33":`Tillåt chattkommandot /plugins att lista upptäckta insticksprogram och aktivera eller inaktivera insticksprogram i konfigurationen (standard: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Tillåt omstart`},help:{"v1-m32fv2-27":`Tillåt /restart, /update och externa omstartsbegäranden via SIGUSR2 (standard: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Textkommandon`},help:{"v1-1utu76s-5j":`Aktiverar tolkning av textkommandon i chattinmatningen utöver inbyggda kommandogränssnitt där sådana finns. Låt detta vara aktiverat för kompatibilitet mellan kanaler som inte stöder inbyggd kommandoregistrering.`}},cron:{label:{"v1-1qlte4b-b":`Automatiseringar`},help:{"v1-4md8ic-5u":`Globala schemaläggningsinställningar för sparade automatiseringar, samtidiga körningar, reservleverans och lagringstid för körningssessioner. Behåll standardinställningarna om du inte skalar upp antalet automatiseringar eller integrerar externa webhook-mottagare.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automatiseringar aktiverade`},help:{"v1-y8otx6-5i":`Aktiverar körning av automatiseringar för sparade scheman som hanteras av Gateway. Låt vara aktiverat för vanliga påminnelse- och automatiseringsflöden. Inaktivera endast för att pausa alla automatiseringskörningar utan att ta bort jobb.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Lagringstid för automatiseringssessioner`},help:{"v1-4wagu6-7e":"Styr hur länge avslutade automatiseringssessioner sparas innan de rensas bort (`24h`, `7d`, `1h30m` eller `false` för att inaktivera rensning; en varaktighet på noll, till exempel `0h`, inaktiverar också rensning; standard: `24h`). Använd kortare lagringstid för att minska lagringstillväxten vid scheman med täta körningar."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Hoppa över missade återkommande automatiseringar`},help:{"v1-w9wfmo-66":`Hoppar över missade återkommande cron/every-körningstillfällen när Gateway startar och schemalägger nästa framtida tillfälle i stället för att köra ikapp. Standard: false. Aktivera för att undvika inaktuella påminnelser efter driftstopp; engångsjobb av typen at körs fortfarande ikapp.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`SSRF-policy för automatiseringarnas webhooks`},help:{"v1-1xlfqnu-5h":`SSRF-policy som tillämpas på varje utgående webhook för automatiseringar. Privata, loopback-, länklokala och interna mål förblir blockerade om inte denna policy uttryckligen tillåter dem. Lämna inställningen tom för strikt leveranskontroll.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Tillåtna värdnamn för automatiseringarnas webhooks`},help:{"v1-1i94hyz-3n":`Exakta värdnamn eller IP-adresser som tillåts för leverans av automatiseringswebhooks, inklusive mål som annars blockeras. Håll listan så kort som möjligt.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Automatiseringswebhooks: tillåt unikt lokalt IPv6-adressintervall`},help:{"v1-rke0oj-3b":`Tillåter automatiseringswebhooks till unika lokala IPv6-adresser (fc00::/7). Använd endast i betrodda proxymiljöer med simulerade IP-adresser.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Automatiseringswebhooks: tillåt adressintervallet för prestandatest enligt RFC 2544`},help:{"v1-x1usg4-3h":`Tillåter automatiseringswebhooks till IP-adresser i intervallet för prestandatest enligt RFC 2544 (198.18.0.0/15). Använd endast i betrodda proxymiljöer med simulerade IP-adresser.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Automatiseringswebhooks: blockerade värdnamn`},help:{"v1-16cv1ic-6a":`Värdnamnsmönster som blockeras före DNS och tillåtelseregler vid leverans av automatiseringswebhooks. Stöder exakta värdnamn och "*.example.com" för enbart underdomäner; lägg till "example.com" separat för att blockera rotdomänen. Om värdet är tomt eller inte har angetts läggs inga blockeringar till.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Automatiseringswebhooks: tillåt privata nätverk (riskfyllt)`},help:{"v1-1n9710c-3t":`Tillåter automatiseringswebhooks till mål i privata och interna nätverk. Låt vara inaktiverat om inte alla konfigurerade webhookdestinationer är betrodda.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Automatiseringswebhooks: Bearer-token`},help:{"v1-1l90hxg-5l":`Bearer-token som bifogas vid POST-leveranser till automatiseringswebhooks när webhook-läge används. Använd helst substitution via hemligheter eller miljövariabler och rotera denna token regelbundet om delade webhook-slutpunkter är åtkomliga från internet.`}},database:{label:{"v1-1kfz0nx-n":`Databas (experimentell)`},help:{"v1-xkd3yy-5l":`Val av databasmotor. SQLite är det standardalternativ som stöds; experimentellt stöd för PostgreSQL gäller för de lagringsfamiljer som stöds. Doctor rapporterar motorn för varje datalager och varnar för datalager som fortfarande använder SQLite.`}},"database%2Eengine":{label:{"v1-iq8nxn-u":`Databasmotor (experimentell)`},help:{"v1-5rmdm2-6m":`Lagringsmotor (standard: sqlite). Det experimentella alternativet postgres väljer alla datalager med ett registrerat PostgreSQL-schema; övriga datalager fortsätter att använda SQLite. Migrera befintliga data i de familjer som stöds med openclaw database port medan Gateway är stoppad.`}},"database%2Epostgres":{label:{"v1-1ry5iqk-p":`PostgreSQL (experimentellt)`},help:{"v1-12fqc4x-3f":`Experimentell PostgreSQL-anslutning och schemanamngivning. Säkerhetskopiera varje PostgreSQL-lagringsschema tillsammans med dess SQLite-ankare.`}},"database%2Epostgres%2Econnection":{label:{"v1-1gtr2s2-10":`PostgreSQL-anslutning (experimentell)`},help:{"v1-21cnk3-7i":`Experimentell DSN för PostgreSQL-anslutning, krävs när database.engine är postgres. Använd en SecretRef av typen env/file/exec; referenser som hämtas från datalager kan inte initiera databasen. Värden löser upp referensen innan den lämnas vidare till databasens arbetsprocesser. Vid anslutningsfel sker aldrig någon återgång till SQLite.`}},"database%2Epostgres%2EschemaPrefix":{label:{"v1-1yyxsc3-13":`PostgreSQL-schemaprefix (experimentellt)`},help:{"v1-1pun5uv-5l":`Prefix för nya experimentella PostgreSQL-lagringsscheman (standard: openclaw). Använd 1–27 gemener, siffror eller understreck, med en bokstav eller ett understreck först. Befintliga ankare behåller sitt schema.`}},desktop:{label:{"v1-rs698z-7":`Skrivbord`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Lokalt skrivbord`},help:{"v1-99weio-30":`Skrivbordsobservation för parkopplade noder eller den experimentella Gateway-värdkällan, med stöd av en lokal VNC-server.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Skrivbordsdelning`},help:{"v1-m9lbcj-83":`Aktiverar den här datorns skrivbordskälla. För parkopplade macOS-, Windows- och Linux-noder är den aktiverad som standard; en uttrycklig delningsinställning i skrivbordsappen har företräde. Gateway-värdens Labs-källa är inaktiverad som standard och tillämpar ändringar direkt. Starta om en parkopplad nod efter att du ändrat dess skrivbordskonfiguration.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Hanterat skrivbord på Linux-värd`},help:{"v1-1r7n22m-49":`Kör och övervakar ett TigerVNC/XFCE-skrivbord utan fysisk skärm på Linux, endast tillgängligt via loopback. En uttryckligen angiven port eller en befintlig VNC-server på standardporten har fortfarande företräde.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Lokal VNC-lösenordsfil`},help:{"v1-1m5lsox-37":`Absolut sökväg till VNC-lösenordsfilen. Utelämna på macOS för att ange kontouppgifter när skrivbordsvisaren öppnas.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Lokal VNC-port`},help:{"v1-1ku4w9b-2b":`RFB-port på loopback för en VNC-server som redan körs på den här datorn (standard: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnostik`},help:{"v1-1d5rnym-5p":`Diagnostikinställningar för riktad spårning, telemetriexport och cacheinspektion vid felsökning. Håll den grundläggande diagnostiken på en minimal nivå i produktion och aktivera mer detaljerade signaler endast vid utredning av problem.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Cachespårning`},help:{"v1-10523zm-5b":`Loggningsinställningar för cachespårning som visar cachebeslut och nyttolastens kontext vid inbäddade körningar. Aktivera detta tillfälligt för felsökning och inaktivera det efteråt för att minska mängden känsliga uppgifter i loggarna.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Cachespårning aktiverad`},help:{"v1-2c1umi-1v":`Logga ögonblicksbilder av cachespårning för inbäddade agentkörningar (standard: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnostik aktiverad`},help:{"v1-a46pxt-4h":`Huvudreglage för diagnostikinstrumenteringens utdata i loggar och telemetrianslutningar. Aktiverat som standard; ange false endast i mycket begränsade miljöer.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Diagnostikflaggor`},help:{"v1-x4w5ok-33":`Aktivera riktade diagnostikloggar med flaggor (t.ex. ["telegram.http"]). Stöder jokertecken som "telegram.*" eller "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Exportinställningar för OpenTelemetry för spårningar, mätvärden och loggar som genereras av gateway-komponenter. Använd detta vid integrering med centraliserade backend-system för observerbarhet och pipelines för distribuerad spårning.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Innehållsinsamling för OpenTelemetry`},help:{"v1-19tid4t-2t":`Valfri insamling av innehåll i OTEL-spann. Avstängt som standard; true samlar in innehåll från verktyg och meddelanden som inte är systemmeddelanden.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry aktiverat`},help:{"v1-193bm0-5b":`Aktiverar OpenTelemetry-export för spårningar, mätvärden och loggar baserat på konfigurerade inställningar för slutpunkt och protokoll. Låt vara inaktiverat tills insamlarens slutpunkt och autentisering är fullständigt konfigurerade.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Slutpunkt för OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL till insamlarens slutpunkt som används för OpenTelemetry-export, inklusive schema och port. Använd en nåbar, betrodd insamlarslutpunkt och övervaka inmatningsfel efter driftsättning.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Tömningsintervall för OpenTelemetry (ms)`},help:{"v1-1moqogc-53":`Intervall i millisekunder för regelbunden tömning av telemetridata från buffertar till insamlaren. Öka intervallet för att minska exporttrafiken eller sänk det för snabbare insyn under aktiv incidenthantering.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`HTTP-huvuden för OpenTelemetry`},help:{"v1-s26t2a-52":`Ytterligare HTTP-begärandehuvuden som skickas med OpenTelemetry-exportbegäranden, ofta för klientautentisering eller routning. Lagra hemligheter i värden som hämtas från miljövariabler och undvik onödigt många huvuden.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`OpenTelemetry-loggar aktiverade`},help:{"v1-12wo6rv-4k":`Aktivera export av loggsignaler via OpenTelemetry utöver lokala loggmål. Använd detta när centraliserad loggkorrelation krävs mellan tjänster och agenter.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Slutpunkt för OpenTelemetry-loggar`},help:{"v1-1vgzldu-40":`Signalspecifik OTLP/HTTP-slutpunkt för loggar. När den anges åsidosätter den diagnostics.otel.endpoint och OTEL_EXPORTER_OTLP_ENDPOINT endast för loggexport.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Loggexportör för OpenTelemetry`},help:{"v1-9bzywd-5q":`Exportmål för loggar från diagnostics.otel.logs. Använd "otlp" för den konfigurerade OTLP-slutpunkten för loggar, "stdout" för en JSON-post per stdout-rad i loggpipelines för containrar och "both" när båda exportmålen behövs.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Prefix för mätvärdesnamn i OpenTelemetry`},help:{"v1-1epdpi9-b2":`Ersätter standardprefixet "openclaw." i mätvärdesnamn som tillhör OpenClaw. Använd en tom sträng för att ta bort prefixet, eller upp till 128 ASCII-bokstäver, siffror, understreck, punkter, bindestreck och snedstreck med en bokstav först. Ta med eventuella avgränsare du behöver, till exempel "acme."; standardnamn för mätvärden av typen gen_ai.* ändras inte. Om du ändrar det här värdet måste du uppdatera instrumentpaneler och larm som använder de gamla namnen i frågor.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Mätvärden i OpenTelemetry aktiverade`},help:{"v1-13r4cf4-4x":`Aktivera export av mätvärdessignaler till den konfigurerade slutpunkten för OpenTelemetry-insamlaren. Låt detta vara aktiverat för instrumentpaneler som visar driftstatus och inaktivera det endast om mängden mätvärden måste minimeras.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Slutpunkt för mätvärden i OpenTelemetry`},help:{"v1-qlfh7x-47":`Signalspecifik OTLP/HTTP-slutpunkt för mätvärden. När den anges åsidosätter den diagnostics.otel.endpoint och OTEL_EXPORTER_OTLP_ENDPOINT endast för export av mätvärden.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Protokoll för OpenTelemetry`},help:{"v1-17ine8s-5e":`OTel-transportprotokoll för telemetriexport. Endast "http/protobuf" accepteras; kör "openclaw doctor --fix" för att korrigera ett sparat äldre "grpc"-värde eller få källspecifik vägledning för manuell redigering.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Samplingsfrekvens för OpenTelemetry-spårningar`},help:{"v1-brcwep-50":`Samplingsfrekvens för spårningar (0–1) som styr hur mycket spårningsdata som exporteras till observerbarhetsplattformar. Lägre frekvenser minskar resursåtgång och kostnader, medan högre frekvenser ger bättre detaljrikedom vid felsökning.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Tjänstenamn för OpenTelemetry`},help:{"v1-1hpiqon-5d":`Tjänstenamn som rapporteras i telemetrins resursattribut för att identifiera denna Gateway-instans i observerbarhetsplattformar. Använd stabila namn så att instrumentpaneler och larm förblir konsekventa mellan driftsättningar.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`OpenTelemetry-spårningar aktiverade`},help:{"v1-j7zrrp-4s":`Aktivera export av spårningssignaler till den konfigurerade insamlarändpunkten för OpenTelemetry. Behåll detta aktiverat när spårning av latens eller felsökning behövs, och inaktivera om du bara vill ha mätvärden och loggar.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Ändpunkt för OpenTelemetry-spårningar`},help:{"v1-8yw5p1-43":`Signalspecifik OTLP/HTTP-ändpunkt för spårningar. När den anges åsidosätter den diagnostics.otel.endpoint och OTEL_EXPORTER_OTLP_ENDPOINT endast för spårningsexport.`}},discovery:{label:{"v1-l2sr05-9":`Tjänsteidentifiering`},help:{"v1-1sqleij-4w":`Inställningar för tjänsteidentifiering via lokal mDNS-annonsering och valfri närvarosignalering över större nätverk. Begränsa tjänsteidentifieringen till avsedda nätverk för att undvika att tjänstemetadata läcker ut.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`mDNS-identifiering`},help:{"v1-vtbyyq-4w":`Konfigurationsgrupp för mDNS-identifiering som styr annonsering i lokala nätverk och finjustering av identifieringsbeteendet. Behåll minimalt läge för vanlig identifiering i LAN om inte extra metadata krävs.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Läge för mDNS-upptäckt`},help:{"v1-1p28pd5-2m":`Läge för mDNS-utsändning ("minimal" är standard, "full" inkluderar cliPath/sshPort, "off" inaktiverar mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Upptäckt över större nätverk`},help:{"v1-1akkqjm-53":`Konfigurationsgrupp för upptäckt över större nätverk som gör upptäcktssignaler tillgängliga utanför den lokala länken. Aktivera endast i driftsättningar som avsiktligt samlar information om gateway-närvaro från flera platser.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Domän för upptäckt över större nätverk`},help:{"v1-rxrygo-4m":`Valfri unicast-DNS-SD-domän för upptäckt över större nätverk, till exempel openclaw.internal. Använd detta när du avsiktligt publicerar information för gateway-upptäckt utanför det lokala mDNS-området.`}},env:{label:{"v1-1zc80q-b":`Miljö`},help:{"v1-1ao5po6-55":`Inställningar för import och åsidosättning av miljövariabler som tillhandahåller körningsvariabler till gateway-processen. Använd det här avsnittet för att styra inläsning av skalmiljön och explicit tillförsel av variabler.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Import av skalmiljö`},help:{"v1-1gw487t-4y":`Inställningar för import av skalmiljön som läser in variabler från ditt inloggningsskal vid start. Låt detta vara aktiverat om du är beroende av hemligheter som definierats i profilen eller anpassningar av PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Import av skalmiljö aktiverad`},help:{"v1-5tiuup-5u":`Aktiverar inläsning av miljövariabler från användarens skalprofil vid initiering under start. Låt detta vara aktiverat på utvecklardatorer, eller inaktivera det i låsta tjänstemiljöer med explicit hantering av miljövariabler.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Tidsgräns för import av skalmiljö (ms)`},help:{"v1-nsk2yf-5c":`Maximal tid i millisekunder för att läsa in skalmiljön innan reservbeteendet aktiveras. Använd kortare tidsgränser för snabbare start, eller öka dem om skalinitieringen är resurskrävande.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Åsidosättningar av miljövariabler`},help:{"v1-1uloveo-5t":`Explicita åsidosättningar av miljövariabler som nyckel/värde-par som slås samman med processmiljön för OpenClaw vid körning. Använd detta för förutsägbar miljökonfiguration i stället för att enbart förlita dig på skalprofilens bieffekter.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Körningsinställningar för Gateway som omfattar bindningsläge, autentisering, kontrollgränssnitt, fjärrtransport och driftsäkerhetskontroller. Behåll försiktiga standardvärden om du inte avsiktligt exponerar Gateway utanför betrodda lokala gränssnitt.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Tillåt x-real-ip som reservalternativ för Gateway`},help:{"v1-1wr3qmw-4c":`Aktiverar x-real-ip som reservalternativ när x-forwarded-for saknas i proxyscenarier. Låt detta vara inaktiverat om inte din ingressinfrastruktur kräver detta kompatibilitetsbeteende.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Gateway-autentisering`},help:{"v1-70b6ni-50":`Autentiseringspolicy för HTTP/WebSocket-åtkomst till Gateway, inklusive läge, autentiseringsuppgifter, beteende för betrodda proxyservrar och frekvensbegränsning. Behåll autentisering aktiverad för alla driftsättningar som inte är begränsade till loopback.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Tillåt Tailscale-identitet för Gateway-autentisering`},help:{"v1-vqtmgw-53":`Tillåter betrodda Tailscale-identitetsflöden att uppfylla autentiseringskontrollerna för Gateway när detta har konfigurerats. Använd detta endast när identitetssäkerheten i ditt tailnet är stark och operatörernas arbetsflöden är beroende av det.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Tilldelade identitetsbehörigheter för Gateway`},help:{"v1-1h0zxy7-5n":`Mappar verifierade trusted-proxy- eller Tailscale-identiteter till operatörsbehörigheter som endast gäller anslutningen. E-postnycklar matchas utan hänsyn till skiftläge; tilldelade behörigheter utökar enhetens behörigheter innan anslutningens behörighetstak tillämpas.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Autentiseringsläge för Gateway`},help:{"v1-j8rodq-9t":`Autentiseringsläge för Gateway: "none", "token", "password" eller "trusted-proxy" beroende på din nätverksgränsarkitektur. Token-/lösenordsläget väljer den konfigurerade hemligheten (gateway.auth.token eller gateway.auth.password); klienter kan skicka den i valfritt autentiseringsfält vid anslutning. Använd token/lösenord vid direkt exponering och trusted-proxy endast bakom säkerhetshärdade, identitetsmedvetna proxyservrar.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Lösenord för Gateway`},help:{"v1-1ndt0u2-4g":`Delad hemlighet som väljs med gateway.auth.mode=password. Klienter kan skicka den i antingen auth.token eller auth.password. Lösenordsläge krävs för Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Frekvensbegränsning för Gateway-autentisering`},help:{"v1-1kstr42-54":`Inställningar för begränsning av inloggnings- och autentiseringsförsök för att minska risken för brute force-attacker mot inloggningsuppgifter vid gatewaygränsen. Behåll funktionen aktiverad i exponerade miljöer och anpassa tröskelvärdena till din normala trafiknivå.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Token för Gateway`},help:{"v1-16i7cxs-5q":`Delad hemlighet som väljs med gateway.auth.mode=token, standardläget vid ny lokal konfiguration. Klienter kan skicka den i antingen auth.token eller auth.password. Bindningar till andra adresser än loopback kräver ett aktiverat autentiseringsläge.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Gateway-autentisering via betrodd proxy`},help:{"v1-12fsi5d-58":`Mappning av autentiseringshuvuden för betrodda proxyservrar, för överordnade identitetsleverantörer som infogar användaranspråk. Använd endast med kända CIDR-intervall för proxyservrar och strikta tillåtelselistor för huvuden för att förhindra förfalskade identitetshuvuden.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`GitHub-identitet via Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Valfri verifierad GitHub-identitet från en vald Cloudflare Access OIDC-leverantör. Kräver Access standardhuvuden för e-post och intyg. Om anspråk saknas behålls profiler med enbart e-post; befintliga profilroller och inställningar för medförfattarskap bevaras.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Anspråk för GitHub-konto-ID`},help:{"v1-qd4qvh-87":`Exakt vidarebefordrat OIDC-anspråk vars värde är ett verifierat GitHub-konto-ID i form av en sträng med ett positivt decimaltal. Konfigurera Access att vidarebefordra det och granska sedan det autentiserade identitetssvaret från Access. OpenClaw läser oidc_fields, eller custom när oidc_fields saknas. Använd aldrig ett overifierat anspråk som användaren kan redigera.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Cloudflare Access-utfärdare`},help:{"v1-gykv03-56":`Exakt HTTPS-ursprung för det betrodda Cloudflare Access-teamet, till exempel https://example.cloudflareaccess.com, utan avslutande snedstreck. Anspråk från andra utfärdare tillhandahåller inte GitHub-identitet.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Leverantörs-ID för Cloudflare Access OIDC`},help:{"v1-kbyo5w-44":`Exakt ID för identitetsleverantören i Access för den betrodda OIDC-integrationen. Enbart leverantörens visningsnamn eller ett matchande anspråksnamn etablerar inte tillit.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Automatiskt enhetsgodkännande via betrodd proxy`},help:{"v1-uh32ha-6z":`Valfri policy för att automatiskt godkänna nya operatörsenheter med webbläsarbaserat eller inbyggt användargränssnitt samt utökningar av behörighetsomfång med samma nyckel efter autentisering via betrodd proxy. Beviljade behörigheter begränsas av deviceAutoApprove.scopes och proxyns x-openclaw-scopes-header när den finns.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Automatiskt enhetsgodkännande via betrodd proxy aktiverat`},help:{"v1-1nntwls-78":`Godkänner automatiskt nya operatörsenheter med webbläsarbaserat eller inbyggt användargränssnitt samt utökningar av behörighetsomfång med samma nyckel efter att den omvända proxyn har autentiserat en tillåten användare. Standardvärde: false. Aktivera endast om proxyns tillitsgräns för identiteter är tillräckligt stark för att ersätta manuell enhetsparkoppling.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Behörighetsomfång för automatiskt enhetsgodkännande via betrodd proxy`},help:{"v1-raeila-g3":`Maximala behörighetsomfattningar som beviljas automatiskt godkända operatörsenheter. Standardvärdena är operator.read, operator.write, operator.approvals och operator.questions. Begärda behörighetsomfattningar begränsas till denna lista; begäranden utan behörighetsomfattningar tilldelas denna lista. Om inget värde anges lägger automatiskt godkännande även till operator.questions för äldre UI-klienter; en uttryckligen angiven lista utökas aldrig. Om operator.admin uttryckligen anges kan varje proxyautentiserad användare automatiskt godkänna fullständiga administratörsbehörigheter, och begäranden utan behörighetsomfattningar tilldelas automatiskt fullständiga administratörsbehörigheter; detta utlöser även en kritisk anmärkning vid säkerhetsgranskning och en varning när Gateway startas.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Bindningsläge för Gateway`},help:{"v1-1unqude-4y":`Nätverksbindningsprofil: "auto", "lan", "loopback", "custom" eller "tailnet" för att styra vilka gränssnitt som exponeras. Behåll "loopback" för enbart lokal drift; "auto" kan exponera alla gränssnitt.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`CLI-agenter`},help:{"v1-1qqo8m2-5a":`Identifiering i Control UI av externa CLI-sessionsmotorer som exponeras via sessionskatalogen i Gateway. Aktiverat som standard; inaktivera för att förhindra att dessa motorer startas från modellväljaren för nya sessioner.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`CLI-agenter aktiverade`},help:{"v1-ufu7fx-8p":`Visar katalogbaserade CLI-agenter i modellväljaren för nya sessioner i Control UI när värdet är true (standard: true). Ange false för att inaktivera CLI-agenter och skapande av inbyggda CLI-sessioner. Endast kataloger som anger stöd för att skapa sessioner listas, och väljaren förblir dold när Gateway inte anger stöd för sessionskataloger.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Inställningar för drift av Control UI, inklusive aktivering, sökvägar och säkerhetshärdning för webbläsarursprung och autentisering. Begränsa exponeringen av gränssnittet och använd starka autentiseringskontroller innan det görs tillgängligt via internet.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Tillåtna ursprung för Control UI`},help:{"v1-1pf3zqm-at":`Tillåtna webbläsarursprung för anslutningar till Control UI/WebChat (endast fullständiga ursprung, t.ex. https://control.example.com). Om inställningen utelämnas används gateway.publicOrigin som standard, om den är konfigurerad. En uttrycklig lista, inklusive [], åsidosätter detta standardvärde; befintliga regler för lokala och privata ursprung gäller fortfarande. Inställningen ["*"] tillåter alla webbläsarursprung och bör undvikas utanför strikt kontrollerade lokala tester.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Tillåt externa URL:er för inbäddning i Control UI`},help:{"v1-obwpfg-6s":`FARLIG inställning som tillåter värdbaserade inbäddningar att läsa in absoluta externa http(s)-URL:er. Låt den vara avstängd om inte ditt Control UI avsiktligt bäddar in betrodda tredjepartssidor; värdbaserade dokument på /__openclaw__/canvas och /__openclaw__/a2ui behöver den inte.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Hämta länkarnas favikoner automatiskt`},help:{"v1-bn9u34-ag":`Hämta länkarnas favikoner och förhandsvisningar för sociala medier för webbläsarflikar via Gateway (aktiverat som standard). Korten för webbläsarflikar läser in offentliga sidmetadata och angivna bilder utan webbläsarkakor eller inloggningsuppgifter för webbplatser. Alla förfrågningar använder strikta SSRF-kontroller och begränsad HTML- och bildbehandling. Ange false för att inaktivera automatisk hämtning av både favikoner och sidförhandsvisningar; skärmbilder från webbläsaren i realtid påverkas inte.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Bassökväg för Control UI`},help:{"v1-1dx68ar-1w":`Valfritt URL-prefix där Control UI tillhandahålls (t.ex. /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Communityinbjudan i Control UI`},help:{"v1-cuu59-7t":`Visa communityinbjudan med länkar till Reddit, Discord och X i Control UI som tillhandahålls av denna Gateway (aktiverat som standard). Ange false för att dölja den i alla webbläsare som använder denna UI-driftsättning. Ändringar träder i kraft när webbläsaren uppdateras eller återansluts. Vid återaktivering förblir inbjudan dold i webbläsare där användaren tidigare har stängt den.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Tillåt farlig reservlösning för ursprung baserad på Host-headern`},help:{"v1-1t1qi4c-7v":`FARLIG inställning som aktiverar en reservlösning för ursprung baserad på Host-headern vid WebSocket-kontroller för Control UI/WebChat. Detta läge stöds när driftsättningen avsiktligt förlitar sig på en ursprungspolicy baserad på Host-headern. En explicit angiven gateway.controlUi.allowedOrigins är fortfarande det rekommenderade säkerhetsförstärkta standardalternativet.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Sandlådeläge för inbäddningar i Control UI`},help:{"v1-d54l3a-7c":'Sandlådepolicy för iframe-inbäddningar i det tillhandahållna Control UI. "strict" inaktiverar skript, "scripts" tillåter interaktiva inbäddningar med bibehållen ursprungsisolering (standard), och "trusted" lägger till `allow-same-origin` för dokument från samma webbplats som avsiktligt behöver utökade behörigheter.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI aktiverat`},help:{"v1-1hhyymc-4w":`Gör det möjligt att tillhandahålla Control UI för Gateway via dess HTTP-process när värdet är true. Behåll aktiverat för lokal administration och inaktivera när ett externt kontrollgränssnitt ersätter det.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Miljö för Control UI`},help:{"v1-paarso-4n":`Valfri offentlig miljöidentitet som visas i färgremsan i Control UI, agentens avatar, etiketter, webbläsarens titel och webbplatsikonen. Utelämna den för att behålla standardutseendet.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Miljöfärg i Control UI`},help:{"v1-mp6cta-2i":`Namngiven färgskala för miljön: teal, amber, purple, coral, pink, blue, green, red eller gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Miljöetikett i Control UI`},help:{"v1-1njve3z-3z":`Miljöetikett som visas i Control UI och webbläsarfliken. Inledande och avslutande blanksteg tas bort och etiketten måste innehålla 1 till 24 tecken.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Experimentella funktioner i Control UI`},help:{"v1-1qobi2m-3g":`Experiment i Control UI som aktiveras frivilligt. Dessa funktioner kan ändras mellan versioner och förblir inaktiverade om de inte uttryckligen aktiveras.`}},"gateway%2EcontrolUi%2Eexperimental%2EchatBubbles":{label:{"v1-1i4j62s-e":`Pratbubblor`},help:{"v1-1tm7kbd-5m":`Aktivera experimentella pratbubblor i Control UI (standard: false). Hemvyn använder bubblor som standard när funktionen är aktiverad. Sessionsspecifika val som lagras lokalt i webbläsaren har företräde. Ändringar tillämpas utan att Gateway startas om.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Gränssnitt för anpassade insticksprogram`},help:{"v1-108u6ts-9e":`Tillåt användarinstallerade insticksprogram att köra JavaScript direkt i Control UI (standard: false). Medföljande insticksvyer är fortfarande tillgängliga. Anpassade gränssnitt delar den inloggade operatörens Gateway-behörigheter; aktivera endast för betrodda insticksprogram. Ändringar tillämpas utan att Gateway startas om. Läs in öppna Control UI-sidor på nytt för att rensa tidigare inläst instickskod.`}},"gateway%2EcontrolUi%2Egithub%2Ehost":{label:{"v1-19tqc36-u":`GitHub-tjänstvärd för Control UI`},help:{"v1-qaa5xb-3z":`Värd som denna autentiseringsuppgift för tjänsten får åtkomst till. Utelämna för github.com; ange gateway.github.host för projektidentifiering och kontometadata i Enterprise.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Autentiseringsuppgift för GitHub-tjänsten i Control UI`},help:{"v1-wviyvm-b8":`Autentiseringsuppgift för tjänsten via SecretRef för projektidentifiering i Control UI och GitHub-förhandsvisningar vid hovring utan en hanterad identitet. Ange gateway.controlUi.github.host för Enterprise; om värden utelämnas används github.com. Förhandsvisningar vid hovring använder i första hand den valda agentens konfigurerade GitHub-identitet. GH_TOKEN/GITHUB_TOKEN används som reserv endast för github.com. Begäranden som använder en autentiseringsuppgift som inte matchar eller inte är tillgänglig avvisas.`}},"gateway%2EcontrolUi%2EnewSessionModelDefaults":{label:{"v1-bxfhmu-q":`Standardinställningar för modell i nya sessioner`},help:{"v1-106khjb-9b":`Välj "configured" för att starta nya utkast i Control UI med den valda agentens konfigurerade standardinställningar för modell, körmiljö och resonemang i stället för sparade val. Standard: "last-used". Uttryckliga val för utkast och konversationer kan fortfarande redigeras; snabbläget och placeringsinställningarna förblir oförändrade. Tillämpas när sidan läses in på nytt i webbläsaren eller vid återanslutning.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Rotkatalog för resurser i Control UI`},help:{"v1-elck04-25":`Valfri rotkatalog i filsystemet för Control UI-resurser (standard är dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Sessionsobservatör för Control UI`},help:{"v1-1ahs80-8a":`Skapa löpande sammanfattningar av sessionsstatus för prenumererande Control UI-klienter med varje agents hjälpmodell (aktiverat som standard). Ange false för att inaktivera observatörens modellanrop i hela Gateway; om agents.defaults.utilityModel anges som en tom sträng inaktiveras observation med hjälpmodellen för agenter som inte åsidosätter inställningen.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Anpassad bindningsvärd för Gateway`},help:{"v1-lwjcyo-4d":`IPv4-adress som används för en anpassad bindning. Specifika IPv4-adresser kräver också samma Gateway-port på 127.0.0.1; undvik 0.0.0.0 om inte exponering på alla gränssnitt krävs.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`HTTP-API för Gateway`},help:{"v1-9vup6v-4y":`Konfiguration av Gateways HTTP-API som samlar inställningar för aktivering av slutpunkter och transportrelaterad API-exponering. Aktivera endast nödvändiga slutpunkter för att begränsa vad fjärrklienter kan komma åt.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`HTTP-slutpunkter för Gateway`},help:{"v1-1a0r104-55":`Funktionsinställningar för HTTP-slutpunkter i Gateways API för kompatibilitetsrutter och valfria integrationer. Aktivera slutpunkter medvetet och övervaka åtkomstmönster efter driftsättning.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Slutpunkt för OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Aktivera den OpenAI-kompatibla slutpunkten `POST /v1/chat/completions` (standard: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Bildgränser för OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Inställningar för hämtning och validering av bilder för OpenAI-kompatibla `image_url`-delar."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Tillåtna MIME-typer för bilder i OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Tillåtna MIME-typer för `image_url`-delar (listan är inte skiftlägeskänslig)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Tillåt bild-URL:er i OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Tillåt URL-hämtningar på serversidan för `image_url`-delar (standard: false; data-URI:er stöds fortfarande). Ange `false` för att inaktivera URL-hämtning helt."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Maximalt antal byte per bild i OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Maximalt antal byte per hämtad/avkodad `image_url`-bild (standard: 10 MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Maximalt antal omdirigeringar för bilder i OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Maximalt antal tillåtna HTTP-omdirigeringar vid hämtning av `image_url`-URL:er (standard: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Tidsgräns för bilder i OpenAI Chat Completions (ms)`},help:{"v1-89w2b9-1x":"Tidsgräns i millisekunder för hämtning av `image_url`-URL:er (standard: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Tillåtna bild-URL:er i OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Valfri lista över tillåtna värdnamn för hämtningar via `image_url`-URL:er; stöder exakta värdnamn och jokertecken som `*.example.com`. Tomma eller utelämnade listor innebär ingen begränsning av tillåtna värdnamn."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`HTTP-säkerhetsrubriker för Gateway`},help:{"v1-n8z1hb-44":`Valfria säkerhetsrubriker i HTTP-svar som tillämpas av själva Gateway-processen. Ange helst dessa i din omvända proxy om TLS avslutas där.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Rubrik för strikt transportsäkerhet`},help:{"v1-1buwhc3-3v":`Värde för svarsrubriken Strict-Transport-Security. Ange endast för HTTPS-ursprung som du har full kontroll över; använd false för att uttryckligen inaktivera.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Gateway-läge`},help:{"v1-nfjirv-5m":`Driftläge för Gateway: "local" kör kanaler och agentens körmiljö på den här värden, medan "remote" ansluter via fjärrtransport. Behåll "local" om du inte avsiktligt använder en uppdelad topologi med en fjärransluten Gateway.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills från Gateway-noder aktiverade`},help:{"v1-1xwu6at-3g":`Acceptera färdigheter som publiceras av parkopplade noder medan de är anslutna (standard: true). Ange false för att ignorera färdigheter som publiceras av noder.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Webbläsarläge för Gateway-noder`},help:{"v1-oeu1nc-69":`Routning till nodwebbläsare ("auto" = föredra värdens webbläsare, använd en enda ansluten webbläsarnod när lokal funktionalitet saknas; "manual" = kräv ett uttryckligt nodval eller en konfigurerad nodbindning; "off" = inaktivera nodroutning).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Fast nod för webbläsarroutning i Gateway`},help:{"v1-1cykty2-1p":`Lås webbläsarroutning till ett specifikt nod-id eller nodnamn (valfritt).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Tillåtelselista för Gateway-noder (extra kommandon)`},help:{"v1-6l4otb-5m":"Extra node.invoke-kommandon som ska tillåtas utöver standardkommandona i Gateway (array med kommandosträngar). Att aktivera farliga kommandon här är en säkerhetskänslig åsidosättning som flaggas av `openclaw security audit`."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Spärrlista för Gateway-noder`},help:{"v1-u7c8wx-53":"Namn på nodkommandon som ska blockeras även om de finns i nodens deklarerade behörigheter eller standardtillåtelselistan (endast exakt matchning av kommandonamn, t.ex. `system.run`; granskar inte skaltext inuti kommandot)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Parkoppling av Gateway-noder`},help:{"v1-gldsi2-4s":`Policyinställningar för nodparkoppling. SSH-verifierat automatiskt godkännande är aktiverat som standard; automatiskt godkännande via CIDR förblir inaktiverat om inte uttryckliga tillåtelselistor för betrodda CIDR/IP-adresser konfigureras.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDR-intervall för automatiskt godkännande av Gateway-nodparkoppling`},help:{"v1-1m6jsxj-6x":`Valfri CIDR/IP-tillåtelselista för automatiskt godkännande av förstagångsparkoppling av enheter med nodroll utan begärda behörighetsomfång. Inaktiverad om den inte anges. Parkoppling för operatör, webbläsare och Control UI samt all parkoppling som uppgraderar roll, behörighetsomfång, metadata eller publik nyckel kräver fortfarande manuellt godkännande.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Automatiskt godkännande av lokal Gateway-nodparkoppling`},help:{"v1-glzm36-41":`Godkänn automatiskt betrodd lokal parkoppling och utökad åtkomst utan avisering (standard: true); ange false för att kräva uttryckligt godkännande av varje enhet i stället.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`SSH-verifiering av nodparkoppling i Gateway`},help:{"v1-1e4da92-ct":"SSH-verifierat automatiskt godkännande vid första parkopplingen av en enhet med nodroll (standard: aktiverat). Gateway ansluter tillbaka till parkopplingsvärden via SSH (BatchMode, strikt kontroll av värdnycklar) och godkänner endast när utdata från `openclaw node identity` på fjärrvärden matchar den väntande enhetsnyckeln. Ange false för att inaktivera SSH-verifiering (oberoende av autoApproveCidrs, som förblir aktivt); för enbart manuell parkoppling måste även autoApproveCidrs tas bort. Ange ett objekt för att åsidosätta user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Pluginverktyg för Gateway-noder`},help:{"v1-1c24iq3-28":`Styr om parkopplade noder får publicera beskrivningar av pluginverktyg som är synliga för agenter.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Pluginverktyg för Gateway-noder aktiverade`},help:{"v1-14lgfu6-47":`Acceptera beskrivningar av pluginverktyg som publiceras av parkopplade noder och är synliga för agenter (standard: true). Ange false för att ignorera och ta bort alla pluginverktyg som publicerats av noder.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Gateway-port`},help:{"v1-for8t5-54":`TCP-port som Gateways lyssnare använder för API, kontrollgränssnitt och kanalernas inkommande trafik. Använd en dedikerad port och undvik konflikter med omvända proxyservrar eller lokala utvecklingstjänster.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Gateway-portaler`},help:{"v1-1v2lkw9-1c":`Inställningar för portalpublicering och privat inkommande trafik.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Privat portalingress`},help:{"v1-20w4gq-69":`Valfri operatörshanterad privat omvänd HTTPS-proxy med jokertecken. Vidarebefordra ursprunglig Host, sökvägar och WebSocket-uppgraderingar till den dedikerade loopback-lyssnaren. Bearer-autentisering för portalen krävs fortfarande. Kräver omstart av Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Jokerteckendomän för portaler`},help:{"v1-1ipbfad-53":`Enbart DNS-domän för slumpmässiga portalunderdomäner (till exempel previews.example.net). Konfigurera DNS med jokertecken och HTTPS privat; dela inte värdnamnsutrymme med Gateway eller Control UI.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Loopback-port för portalingress`},help:{"v1-1mb98cv-4g":`Dedikerad HTTP-port på loopback som tar emot trafik från den privata HTTPS-proxyn med jokertecken. Måste skilja sig från Gateway-porten. Detta är backend-porten, inte den publika HTTPS-porten.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Publikt ursprung för Gateway`},help:{"v1-6uzv6o-ah":`Externt tillgängligt HTTPS-ursprung för Gateway. Används även som standardursprung för webbläsaren när gateway.controlUi.allowedOrigins utelämnas. HTTP tillåts endast för localhost, 127.0.0.1 eller [::1]. MCP OAuth per anropare använder det för att skapa återanropsadressen på /oauth/mcp/callback; kanalsessionslänkar och visningslänkar som genereras av insticksprogram använder det för att nå Control UI och Gateway-rutter.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Push-leverans för Gateway`},help:{"v1-h23oz7-5s":`Inställningar för push-leverans som används av gatewayen när den behöver väcka eller avisera parkopplade enheter. Konfigurera reläbaserad APNs här för officiella iOS-byggen; direkt APNs-autentisering baseras fortsatt på miljövariabler för lokala/manuella byggen.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`APNs-leverans för Gateway`},help:{"v1-4bbafr-4e":`Inställningar för APNs-leverans till iOS-enheter som är parkopplade med denna gateway. Använd reläinställningar för officiella App Store-versioner som registreras via det externa pushreläet.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`APNs-relä för Gateway`},help:{"v1-7glbel-6x":`Inställningar för externt relä för APNs-sändningar via relä. Gatewayen använder som standard det driftade OpenClaw-reläet, eller detta anpassade relä för push.test, väckningssignaler och väckningar för återanslutning efter att en parkopplad officiell iOS-version har publicerat en reläbaserad registrering.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Bas-URL för APNs-relä för Gateway`},help:{"v1-1o8mgnq-69":`Valfri anpassad HTTPS-bas-URL för den externa APNs-relätjänst som används av officiella iOS-versioner från App Store. Se till att den matchar reläets URL som är inbyggd i iOS-versionen, så att registrerings- och sändningstrafik når samma driftsinstans.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Tidsgräns för APNs-relä för Gateway (ms)`},help:{"v1-a0jkb1-4z":`Tidsgräns i millisekunder för sändningsbegäranden från gatewayen till APNs-reläet (standard: 10000). Öka för långsammare reläer eller nätverk, eller minska för att avbryta misslyckade väckningsförsök snabbare.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Omläsning av konfiguration`},help:{"v1-d02mvq-4w":`Policy för omläsning av konfiguration under drift som styr hur ändringar tillämpas och när fullständiga omstarter utlöses. Behåll hybridbeteendet för säkrast möjliga uppdateringar under drift, om du inte felsöker omläsningens interna funktioner.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Läge för omläsning av konfiguration`},help:{"v1-1q1etcf-3m":`Styr hur konfigurationsändringar tillämpas: "off" ignorerar ändringar under drift och "hybrid" tillämpar ändringar som är säkra att göra under drift och startar sedan om vid behov.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Fjärransluten Gateway`},help:{"v1-6xv7gd-5a":`Anslutningsinställningar för en fjärransluten Gateway via direktanslutning eller SSH när den här instansen fungerar som proxy till en annan körningsvärd. Använd fjärrläge endast när drift på separata värdar har konfigurerats avsiktligt.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`HTTP-huvuden för kantautentisering för fjärransluten Gateway`},help:{"v1-jg9p7d-5o":`HTTP-huvuden med värden från hemligheter som skickas till en identitetsmedveten proxy framför den konfigurerade fjärranslutna Gateway. Huvudena skickas endast till exakt det ursprung som anges i gateway.remote.url via WSS och följer aldrig omdirigeringar.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Lösenord för fjärransluten Gateway`},help:{"v1-16jc0yx-7y":`Delad hemlighet som skickas i lösenordsfältet för att autentisera den här klienten mot en fjärransluten Gateway. Serverns gateway.auth.mode väljer dess konfigurerade hemlighet; både klientens tokenfält och lösenordsfält godtas. Hantera den här hemligheten externt och undvik klartextvärden i incheckad konfiguration.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Policy för SSH-värdnycklar för fjärransluten Gateway`},help:{"v1-7qoxtb-49":`Policy för verifiering av SSH-värdnycklar i macOS. "strict" kräver en redan betrodd värdnyckel; "openssh" delegerar uttryckligen till den gällande OpenSSH-konfigurationen.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`SSH-identitet för fjärransluten Gateway`},help:{"v1-hz2hsm-1f":`Valfri sökväg till SSH-identitetsfil (skickas till ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`SSH-mål för fjärransluten Gateway`},help:{"v1-85w39w-2t":`Fjärransluten Gateway via SSH (tunnlar Gateway-porten till localhost). Format: user@host eller user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`TLS-fingeravtryck för fjärransluten Gateway`},help:{"v1-1ri16lk-23":`Förväntat sha256-TLS-fingeravtryck för fjärransluten Gateway (lås fingeravtrycket för att undvika MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Token för fjärransluten Gateway`},help:{"v1-1pb9q8w-7v":`Delad hemlighet som skickas i tokenfältet för att autentisera den här klienten mot en fjärransluten Gateway. Serverns gateway.auth.mode väljer dess konfigurerade hemlighet; både klientens tokenfält och lösenordsfält godtas. Lagra via substitution av hemligheter eller miljövariabler och rotera vid ändringar av autentiseringen för fjärransluten Gateway.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Transport för fjärransluten Gateway`},help:{"v1-1acfs7m-54":`Transport för fjärranslutning: "direct" ansluter via den konfigurerade URL:en, medan "ssh" använder en SSH-tunnel. Använd SSH när du behöver en krypterad tunnel utan att exponera fjärrportar.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL för fjärransluten Gateway`},help:{"v1-va7exe-1b":`WebSocket-URL för fjärransluten Gateway (ws:// eller wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Operatörsroller för Gateway`},help:{"v1-b59sc5-6w":`Valfria profilbundna operatörsroller för teamets Gateway-instanser. Varje namngiven roll styr åtkomst till andra personers sessioner, sandlådeisolering, agenter för sessioner och körningar samt tilldelade operatörsbehörigheter; om det här avsnittet utelämnas behålls det befintliga operatörsbeteendet.`}},"gateway%2Eroles%2Eassignments":{label:{"v1-hv31t1-p":`Tilldelningar av operatörsroller`},help:{"v1-do2i61-55":`Valfria deklarativa rolltilldelningar för autentiserade profiler. En giltig explicit tilldelning som gjorts med users.setRole har företräde framför dessa mappningar, som i sin tur har företräde framför standardrollen.`}},"gateway%2Eroles%2Eassignments%2EbyGithubLogin":{label:{"v1-wujwr5-u":`Operatörsroller efter GitHub-användarnamn`},help:{"v1-bxa0be-7i":`Kopplar cachade GitHub-identiteters användarnamn till konfigurerade rollnamn, utan hänsyn till skiftläge och efter att inledande och avslutande blanksteg tagits bort. Ogiltiga användarnamn, dubbletter av normaliserade användarnamn och okända roller avvisas. Profiler utan en cachad GitHub-identitet använder sin uttryckliga tilldelning eller standardrollen.`}},"gateway%2Eroles%2Eassignments%2EbyGithubLogin%2E*":{label:{"v1-1wr68uf-q":`Operatörsroll för GitHub-användarnamn`},help:{"v1-dad5ey-5e":`Konfigurerat rollnamn för detta GitHub-användarnamn. Gäller när profilen har en matchande cachad GitHub-identitet och saknar en giltig uttrycklig rolltilldelning. Ändringar tillämpas utan omstart när omladdning av konfigurationen är aktiverad.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Standardroll för operatörer`},help:{"v1-1t2848y-5t":`Obligatorisk roll som tillämpas på autentiserade profiler utan en giltig uttrycklig tilldelning eller en matchande tilldelning via GitHub-användarnamn när operatörsroller är konfigurerade. Namnet måste matcha en konfigurerad rolldefinition.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Definitioner av operatörsroller`},help:{"v1-uv91an-53":`Icke-tomma rolldefinitioner namngivna av administratörer som samlar de slutna policyerna för sessionsdelning, sandlådeisolering, agentåtkomst och operatörsbehörigheter som tillämpas på autentiserade användarprofiler.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Definition av operatörsroll`},help:{"v1-p8tfws-6q":`En namngiven operatörsroll. Varje definition måste uttryckligen ange sin policy för sessionsdelning, tillåtna agenter för sessioner och körningar samt den övre gränsen för operatörsbehörigheter, och kan kräva sandlådeisolering för nyskapade sessioner samt en åtkomstpolicy för insticksprogram.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Plugin för operatörsrollens åtkomstpolicy`},help:{"v1-1gq4q08-9n":`Valfritt exakt plugin-ID vars åtkomstpolicy för Gateway måste godkänna denna roll. Åtkomst nekas om pluginet saknas, är inaktiverat, inte kan läsas in eller inte tillhandahåller någon aktuell behörighet. Otillgängliga plugin-ID:n förblir giltiga i konfigurationen så att oberoende personalroller och ägaren av Gateway kan återställa åtkomsten. Om fältet utelämnas tillkommer inget pluginberoende.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Tillåtna agenter för operatörsrollen`},help:{"v1-fvun18-4v":`Agenter som är tillgängliga när denna roll skapar sessioner eller startar körningar: ange "*" för att tillåta alla agenter, lista agent-ID:n för att endast tillåta dessa agenter eller använd en tom lista för att inaktivera båda funktionerna.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy":{label:{"v1-1b2q6cc-q":`Modellpolicy för operatörsrollen`},help:{"v1-r9daa-e8":`Valfri övre gräns för modelltillgång för denna rolls förfrågningar och deras underordnade förfrågningar. Ett tomt objekt tillåter endast källagentens konfigurerade primära modeller och reservmodeller. Om policyn utelämnas förblir modelltillgången oförändrad. Modellalias löses upp innan policyn tillämpas, och nekade modeller kan inte användas vid nya försök eller som reservmodeller. När omladdning av konfigurationen är aktiverad tillämpas ändringar som enbart gäller befintliga rollers modellpolicyer när de sparas, utan att tillåtet arbete startas om. Andra rolländringar tillämpas direkt och återansluter klienter med aktuella behörigheter.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2Eallow":{label:{"v1-zdw95f-s":`Tillåtna modeller för operatörsrollen`},help:{"v1-1dutf3o-8u":`Valfri ersättande tillåtelselista med modellreferenser, konfigurerade alias eller prefixmönster med avslutande jokertecken, som "provider/*" eller "provider/family-*". Om den utelämnas används källagentens primära modell och reservmodeller; en tom lista nekar alla modeller. Den första tillåtna källmodellen förblir standard, följd av uttryckligen tillåtna modeller.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2Edeny":{label:{"v1-1hx2vzz-t":`Uteslutna modeller för operatörsrollen`},help:{"v1-1kx70ze-7o":`Modellreferenser, källagentens alias eller prefixmönster med avslutande jokertecken som utesluts från den här rollen. Ett mönster som "provider/family-*" utesluter även framtida medlemmar i den familjen. Uteslutningar matchas mot upplösta modellidentiteter och har företräde framför tillåtna modeller och källagentens modeller.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2EsourceAgent":{label:{"v1-8bg4yu-w":`Källagent för operatörsrollens modeller`},help:{"v1-yf7mu-62":`Agent vars primära modell, reservmodeller och modellalias ligger till grund för den här rollens modellpolicy. Som standard används den konfigurerade system-/standardagenten eller den enda agenten. Ange detta uttryckligen när en Gateway med flera agenter saknar en ägare i den aktuella kontexten.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Sandlådeisolering för operatörsrollen`},help:{"v1-11bb0ps-6a":`Körningsisolering för nyskapade sessioner: "inherit" (standard) använder agentens policy; "required" kräver alltid en sandlåda, även när agentens sandlådeläge är avstängt, och blockerar körning om backend inte är tillgänglig.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Övre behörighetsgräns för operatörsrollen`},help:{"v1-1selr2i-4s":`Uttömmande lista över operatörsbehörigheter som anger den här rollens maximala behörighet vid anslutning. Begärda, parkopplade, identitetstilldelade och utökade behörigheter begränsas till dem som finns i den här listan.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Operatörsrollens sessionsåtkomst`},help:{"v1-hsoiop-45":`Behörigheter för sessionsdelning som tilldelas den här rollen för sessioner som skapats av andra autentiserade personer. En persons egna sessioner förblir tillgängliga för ägaren.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Operatörsrollens åtkomst till andra sessioner`},help:{"v1-vf8umx-5r":`Åtkomst till andra personers sessioner: "none" döljer dem, "view" tillåter läsning, "suggest" tillåter förslagsflödet och "write" tillåter deltagande. Uttryckligt sessionsmedlemskap kan ge ytterligare åtkomst.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale för Gateway`},help:{"v1-6ar9o-4x":`Inställningar för Tailscale-integrering för exponering via Serve/Funnel och livscykelhantering när gatewayen startas eller avslutas. Låt vara avstängt om inte din driftsättning avsiktligt använder Tailscale för inkommande trafik.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Tailscale-läge för Gateway`},help:{"v1-6l2099-5a":`Publiceringsläge för Tailscale: "off", "serve" eller "funnel" för privat eller offentlig exponering. Använd "serve" för åtkomst enbart inom tailnet och "funnel" endast när åtkomst från det offentliga internet krävs.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Migreringsskydd för extern Funnel i Gateways Tailscale-integrering`},help:{"v1-1mntkor-7q":`Utfasat migreringsskydd för mode='serve'. Om en extern Funnel fortfarande pekar på den vanliga Gateway-lyssnaren lämnar OpenClaw exponeringen oförändrad och varnar för att endast plugin-autentiserade webhooks kan användas tills lösenordsautentisering har konfigurerats och läget har migrerats till 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Operatörsterminal`},help:{"v1-18f5rgm-8b":`Operatörsterminal som tillhandahålls till Control UI och mobilklienter: ett PTY-baserat skal på Gateway-värden, begränsat till operatörssessioner med administratörsbehörighet. Det startar i målagentens arbetsyta och nekas för helt sandlådeisolerade agenter (sandbox.mode 'all') i stället för att ge åtkomst till ett obegränsat skal på värden.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Tidsgräns för frånkopplade operatörsterminalsessioner`},help:{"v1-k6qbgr-9e":`Antal sekunder som en terminalsession finns kvar efter att anslutningen bryts (viloläge på en bärbar dator, omladdning av sidan). Sessionen kan återanslutas via terminal.attach och dess senaste utdata visas då igen. Ange 0 för att avsluta sessioner så snart anslutningen bryts. Standard: 300 (5 minuter). Frånkopplade sessioner fortsätter att köra sina kommandon, så förkorta tiden på delade eller exponerade värdar.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Operatörsterminal aktiverad`},help:{"v1-1nez06v-7p":`Aktiverar operatörsterminalen för klienter med administratörsbehörighet (standard: true). Detta gör ett skal med Gateway-processens miljö tillgängligt i webbläsare och på mobila enheter. Ange false för att inaktivera det i driftsmiljöer där administratörsoperatörer inte ska få tillgång till ett skal på värden. Ändringar tillämpas utan att Gateway behöver startas om.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Skal för operatörsterminal`},help:{"v1-19mfe6t-5i":`Den körbara skalfil som operatörsterminalen startar. Lämna värdet osatt för att använda värddatorns inloggningsskal ($SHELL på Unix, %ComSpec% på Windows), eller ange en specifik tolk för en enhetlig operatörsmiljö.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS för Gateway`},help:{"v1-1dx77dq-4z":`Inställningar för TLS-certifikat och nycklar för att terminera HTTPS direkt i Gateway-processen. Använd uttryckligen angivna certifikat i produktion och undvik exponering i klartext på nätverk som inte är betrodda.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Generera TLS-certifikat automatiskt för Gateway`},help:{"v1-1ld6uiu-4w":`Genererar automatiskt ett lokalt TLS-certifikat med tillhörande nyckel när inga filer har konfigurerats uttryckligen. Använd endast i lokala miljöer eller utvecklingsmiljöer och ersätt med riktiga certifikat för produktionstrafik.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Sökväg till TLS-CA för Gateway`},help:{"v1-andqlu-52":`Valfri sökväg till en CA-samling för klientverifiering eller anpassade krav på tillitskedjan vid nätverksgränsen för Gateway. Använd detta när privat PKI eller anpassade certifikatkedjor ingår i driftsättningen.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Sökväg till TLS-certifikat för Gateway`},help:{"v1-1wznaof-4q":`Sökväg i filsystemet till TLS-certifikatfilen som Gateway använder när TLS är aktiverat. Använd hanterade certifikatsökvägar och se till att den automatiska förnyelsen använder samma plats.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS aktiverat för Gateway`},help:{"v1-ykhwp0-4o":`Aktiverar TLS-terminering i Gateway-lyssnaren så att klienter ansluter direkt via HTTPS/WSS. Behåll aktiverat vid direkt exponering mot internet eller vid nätverksgränser som inte är betrodda.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Sökväg till TLS-nyckel för Gateway`},help:{"v1-15knri0-4i":`Sökväg i filsystemet till den privata TLS-nyckelfil som används av Gateway när TLS är aktiverat. Begränsa åtkomstbehörigheterna för nyckelfilen och rotera nyckeln enligt din säkerhetspolicy.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Policy för verktygsexponering i Gateway`},help:{"v1-1ffol26-5a":`Policy på Gateway-nivå för att tillåta eller neka verktygsexponering, som kan begränsa verktygens tillgänglighet vid körning oberoende av agent- och verktygsprofiler. Använd detta för övergripande nödåtgärder och säkerhetshärdning i produktionsmiljöer.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Lista över tillåtna verktyg i Gateway`},help:{"v1-163khb1-4y":`Uttrycklig lista över tillåtna verktyg på Gateway-nivå när du vill att endast ett begränsat urval av verktyg ska vara tillgängligt vid körning. Använd detta för låsta miljöer där verktygsutbudet måste kontrolleras noggrant.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Lista över blockerade verktyg i Gateway`},help:{"v1-1lhssnf-4o":`Uttrycklig lista över blockerade verktyg på Gateway-nivå för att blockera riskfyllda verktyg även om policyer på lägre nivå tillåter dem. Använd blockeringsregler för akuta åtgärder och säkerhetshärdning med skydd i flera lager.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDR-intervall för betrodda proxyservrar i Gateway`},help:{"v1-n5zcvf-4f":`Lista över tillåtna CIDR-intervall och IP-adresser för uppströms proxyservrar som får ange vidarebefordrade HTTP-huvuden för klientidentitet. Håll listan begränsad så att obetrodda mellanled inte kan utge sig för att vara användare.`}},"gateway%2Euploads":{label:{"v1-pn01yp-m":`Fil- och bilduppladdningar`},help:{"v1-1pj2asp-3d":`Policy för klienters fil- och bilduppladdningar i Gateway och Control UI. Nedladdningar och agentgenererade medier förblir tillgängliga.`}},"gateway%2Euploads%2Eenabled":{label:{"v1-1m4q5zw-f":`Uppladdningar aktiverade`},help:{"v1-1tqoi1v-93":`Tillåter klienter att ladda upp filer och bilder (standard: true). Ange false för att avvisa bilagor, uppladdningar via arbetsyta eller terminal, avataruppladdningar och arkivimporter i Gateway, inklusive direkta API-anrop. Ändringar tillämpas utan omstart. Detta är inte en sandlåda eller en begränsning av kanalmedier, agentverktyg eller operatörers skalåtkomst.`}},hooks:{label:{"v1-j9ywl7-5":`Hookar`},help:{"v1-1mzh0ry-5v":`Gränssnitt för automatisering via inkommande webhookar som kopplar externa händelser till väcknings- eller agentåtgärder i OpenClaw. Skydda detta med uttryckliga kontroller för token, sessioner och agenter innan det exponeras utanför betrodda nätverk.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Tillåtna agent-ID:n för hookar`},help:{"v1-1imjux7-79":`Lista över tillåtna effektiva agent-ID:n som hookförfrågningar och mappningar får riktas till, inklusive routning till standardagenten när agentId utelämnas. Använd detta för att begränsa automatiseringshändelser till särskilda tjänsteagenter och begränsa skadan om en hooktoken röjs.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Tillåtna sessionsnyckelprefix för hookar`},help:{"v1-b346oh-4r":`Lista över tillåtna sessionsnyckelprefix för inkommande hookförfrågningar när nycklar från anroparen är aktiverade. Använd snävt avgränsade prefix för att förhindra injektion av godtyckliga sessionsnycklar.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Tillåt sessionsnyckel i hookförfrågningar`},help:{"v1-11n9ps-52":`Tillåter anropare att ange en sessionsnyckel i hookförfrågningar när värdet är true, vilket möjliggör anroparstyrd routning. Behåll false om inte betrodda integratörer uttryckligen behöver anpassad sessionstrådning.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Standardsessionsnyckel för hookar`},help:{"v1-bzdgkn-57":`Sessionsnyckel som används som reserv för hook-leveranser när en begäran inte anger någon via tillåtna kanaler. Använd en stabil men avgränsad nyckel för att undvika att blanda orelaterade automatiseringskonversationer.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hooks aktiverade`},help:{"v1-1mixmjf-4n":`Aktiverar hook-slutpunkten och körningsflödet för mappningar för inkommande webhook-begäranden. Låt vara inaktiverat om du inte aktivt dirigerar externa händelser till gatewayen.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Gmail-hook`},help:{"v1-4cibmt-4r":`Inställningar för Gmail-pushintegrering som används för Pub/Sub-aviseringar och valfri lokal hantering av återanrop. Begränsa detta till dedikerade Gmail-konton för automatisering när det är möjligt.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Konto för Gmail-hook`},help:{"v1-12l1h96-4v":`Google-kontoidentifierare som används för bevaknings- och prenumerationsåtgärder i Gmail i denna hook-integrering. Använd ett dedikerat e-postkonto för automatisering för att isolera driftbehörigheter.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Tillåt osäkert externt innehåll i Gmail-hook`},help:{"v1-1w3gdvs-55":`Tillåter att mindre sanerat externt Gmail-innehåll går vidare till bearbetning när detta är aktiverat. Låt vara inaktiverat för säkrare standardinställningar och aktivera endast för betrodda e-postflöden med kontrollerade omvandlingar.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`Återanrops-URL för Gmail-hook`},help:{"v1-19fhn6q-4z":`Offentlig återanrops-URL som Gmail eller mellanhänder anropar för att leverera aviseringar till detta hook-flöde. Skydda denna URL med tokenvalidering och begränsad nätverksexponering.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Inkludera meddelandetext i Gmail-hook`},help:{"v1-14cf1c3-52":`När värdet är true hämtas och inkluderas e-postmeddelandets innehåll för efterföljande mappning och agentbearbetning. Behåll false om meddelandetexten inte behövs, eftersom detta ökar datamängdens storlek och känslighet.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Etikett för Gmail-hook`},help:{"v1-9zpdg8-4g":`Valfritt Gmail-etikettfilter som begränsar vilka etiketterade meddelanden som utlöser hook-händelser. Använd snäva filter för att undvika att överösa automatiseringar med ovidkommande inkorgstrafik.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Maximal storlek på meddelandeinnehåll för Gmail-hook (byte)`},help:{"v1-2aaxx1-4b":`Maximalt antal byte i Gmail-datamängden som bearbetas per händelse när includeBody är aktiverat. Använd försiktiga gränser för att minska kostnader och risker vid bearbetning av alltför stora meddelanden.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Åsidosättning av modell för Gmail-hook`},help:{"v1-1var65t-59":`Valfri åsidosättning av modell för Gmail-utlösta körningar när automatiseringar för e-postlådan ska använda ett särskilt modellbeteende. Lämna värdet ej angivet för att ärva agentens standardinställningar, om inte uppgifter för e-postlådan kräver specialisering.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Push-token för Gmail-hook`},help:{"v1-h1vx01-4o":`Delad hemlig token som krävs vid återanrop till Gmail-push-hooken innan aviseringar bearbetas. Använd miljövariabelsubstitution och rotera token om återanropsändpunkterna exponeras externt.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Förnyelseintervall för Gmail-hook (min)`},help:{"v1-pr1z9-49":`Förnyelseintervall i minuter för Gmail-bevakningsprenumerationer för att förhindra att de löper ut. Ange ett intervall som är kortare än leverantörens giltighetstid och övervaka misslyckade förnyelser i loggarna.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Lokal server för Gmail-hook`},help:{"v1-hom4wq-54":`Inställningsblock för en lokal callback-server som tar emot Gmail-aviseringar direkt utan ett separat ingresslager. Aktivera endast när den här processen själv ska hantera inkommande webhook-trafik.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Bindningsadress för Gmail-hookserver`},help:{"v1-55bieu-4d":`Bindningsadress för den lokala HTTP-server för Gmail-callback som används när hooks hanteras direkt. Begränsa till loopback om inte extern ingress uttryckligen behövs.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Sökväg för Gmail-hookserver`},help:{"v1-1jqhcw4-4h":`HTTP-sökväg på den lokala callback-servern för Gmail där pushaviseringar tas emot. Se till att den stämmer överens med prenumerationskonfigurationen för att undvika att händelser går förlorade.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Port för Gmail-hookserver`},help:{"v1-1yku7dz-43":`Port för den lokala HTTP-servern för Gmail-callback när serverläget är aktiverat. Använd en dedikerad port för att undvika konflikter med gateway- och kontrollgränssnitt.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Gmail-hookprenumeration`},help:{"v1-127h8vg-5b":`Pub/Sub-prenumeration som används av gatewayen för att ta emot aviseringar om Gmail-ändringar från det konfigurerade ämnet. Tydliggör vem som äger prenumerationen så att flera konsumenter inte oväntat konkurrerar om samma meddelanden.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale för Gmail-hook`},help:{"v1-7jzidp-4l":`Konfigurationsblock för Tailscale-exponering som publicerar Gmail-callbacks via Serve/Funnel-rutter. Använd privata tailnet-lägen innan du aktiverar någon offentlig ingressväg.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Tailscale-läge för Gmail-hook`},help:{"v1-vhm395-4u":`Exponeringsläge i Tailscale för Gmail-återanrop: "off", "serve" eller "funnel". Använd "serve" för privat leverans inom tailnet och "funnel" endast när inkommande trafik från det publika internet krävs.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Tailscale-sökväg för Gmail-hook`},help:{"v1-fr8qi-4m":`Sökväg som publiceras av Tailscale Serve/Funnel för vidarebefordran av Gmail-återanrop när funktionen är aktiverad. Håll den i linje med Gmails webhook-konfiguration så att anrop når den avsedda hanteraren.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Tailscale-mål för Gmail-hook`},help:{"v1-1twwxge-47":`Lokalt tjänstemål som Tailscale Serve/Funnel vidarebefordrar till (till exempel http://127.0.0.1:8787). Använd uttryckliga loopback-mål för att undvika tvetydig routning.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Åsidosättning av resonemangsnivå för Gmail-hook`},help:{"v1-17owk9q-4z":`Åsidosättning av resonemangsnivå för Gmail-drivna agentkörningar: "off", "minimal", "low", "medium" eller "high". Använd måttliga standardnivåer för rutinmässig automatisering av inkorgen för att hålla kostnader och svarstider nere.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Pub/Sub-ämne för Gmail-hook`},help:{"v1-fdm0kn-4t":`Namn på det Google Pub/Sub-ämne som Gmail-bevakningen använder för att publicera ändringsaviseringar för det här kontot. Kontrollera att ämnets IAM-behörigheter ger Gmail rätt att publicera innan du aktiverar bevakningar.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Interna hooks`},help:{"v1-piq9k-4v":`Körtidsinställningar för interna hooks med medföljande eller anpassade händelsehanterare som läses in från modulsökvägar. Använd detta för betrodd automatisering inom processen och begränsa noga vilka hanterare som läses in.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Interna hooks aktiverade`},help:{"v1-1wv0289-4c":`Aktiverar bearbetning av interna hookar och konfigurerade poster i körmiljön för interna hookar. Låt vara inaktiverat om interna hookar inte har konfigurerats avsiktligt.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Poster för interna hookar`},help:{"v1-1ovi38l-4o":`Konfigurerade poster för interna hookar som används för att registrera konkreta körningshanterare och metadata. Håll posterna explicita och versionshanterade så att beteendet i produktion kan granskas.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Inläsare för interna hookar`},help:{"v1-11re5ph-4p":`Inställningar för inläsaren för interna hookar som styr var hanterarmoduler hittas vid start. Begränsa rotkatalogerna för inläsning för att minska risken för oavsiktliga modulkonflikter eller att moduler skuggar varandra.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Extra kataloger för interna hookar`},help:{"v1-1xfdqxg-4c":`Ytterligare kataloger där interna hookmoduler söks, utöver standardsökvägarna för inläsning. Håll antalet minimalt och katalogerna under kontroll för att minska risken för att moduler oavsiktligt skuggar varandra.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Hookmappningar`},help:{"v1-frhp3v-5i":`Ordnade mappningsregler som matchar inkommande hookanrop och väljer väcknings- eller agentåtgärder med valfri leveransroutning. Placera specifika mappningar först för att undvika att breda mönsterregler fångar upp allt.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Åtgärd för hookmappning`},help:{"v1-1r5zt5f-5f":`Åtgärdstyp för mappningen: "wake" utlöser agentens väckningsflöde, medan "agent" skickar direkt till agenthantering. Använd "agent" för omedelbar körning och "wake" när bearbetning som styrs av hjärtslag föredras.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`Agent-ID för hookmappning`},help:{"v1-l0uioz-4y":`ID för den agent som ska köra mappningen när åtgärdsroutningen inte ska använda standardinställningarna. Använd dedikerade automationsagenter för att isolera webhook-beteendet från interaktiva operatörssessioner.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Tillåt osäkert externt innehåll i hook-mappning`},help:{"v1-1np9426-57":`När värdet är true kan mappningens innehåll inkludera mindre noggrant sanerade externa nyttolastdata i genererade meddelanden. Behåll false som standard och aktivera endast för betrodda källor med granskad transformeringslogik.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Leveranskanal för hook-mappning`},help:{"v1-oz7pu5-5s":`Åsidosätter leveranskanalen för mappningens utdata (till exempel "last", "telegram", "discord", "slack", "signal", "imessage" eller "msteams"). Ange kanalåsidosättningar uttryckligen för att undvika oavsiktliga utskick till andra kanaler.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Leverera svar från hook-mappning`},help:{"v1-12tbbam-5o":`Styr om resultaten från mappningskörningen levereras tillbaka till en kanaldestination eller bearbetas utan utskick. Inaktivera leverans för bakgrundsautomationer som inte ska publicera utdata för användare.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Förgreningsnyckel för hook-mappning`},help:{"v1-1d593op-7e":`Nyckel för en array på nyttolastens översta nivå som mappningen förgrenas över: varje element utlöser en egen åtgärd, och mallar eller transformeringar ser en nyttolast vars array endast innehåller det aktuella elementet. Gmail-förinställningen använder forEach: messages så att pushar i batch utlöser en körning per e-postmeddelande.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`ID för hook-mappning`},help:{"v1-q1t4zw-57":`Valfri stabil identifierare för en hook-mappningspost som används för granskning, felsökning och riktade uppdateringar. Använd unika ID:n så att loggar och konfigurationsdifferenser kan hänvisa till mappningar entydigt.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Matchning för hook-mappning`},help:{"v1-6u73k2-5a":`Grupperingsobjekt för mappningens matchningsvillkor, till exempel sökväg och källa, innan åtgärdsdirigering tillämpas. Håll matchningsvillkoren specifika så att orelaterad webhook-trafik inte utlöser automatiseringar.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Matchningssökväg för hook-mappning`},help:{"v1-1d7dc5j-4k":`Villkor för sökvägsmatchning i en hook-mappning, som vanligtvis jämförs med sökvägen i den inkommande begäran. Använd detta för att dela upp automatiseringsbeteendet efter grupper av sökvägar till webhook-slutpunkter.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Matchningskälla för hook-mappning`},help:{"v1-1nw7um7-4v":`Villkor för källmatchning i en hook-mappning, som vanligtvis anges av betrodda metadata från uppströmskällor eller av adapterlogik. Använd stabila källidentifierare så att dirigeringen förblir densamma vid återförsök.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Meddelandemall för hook-mappning`},help:{"v1-m0lqv5-5t":`Mall för att omvandla strukturerade indata för mappningen till det slutliga meddelandeinnehållet som skickas till målets åtgärdssökväg. Se till att samma indata ger samma meddelande så att efterföljande parsning och beteende förblir stabila.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Åsidosättning av modell för hook-mappning`},help:{"v1-10qyo4j-5e":`Valfri åsidosättning av modell för körningar som utlöses av mappningar när automatiseringen ska använda en annan modell än agentens standardmodell. Använd detta sparsamt så att beteendet förblir förutsägbart mellan mappningskörningar.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Namn på hook-mappning`},help:{"v1-zrd9tn-4v":`Läsbart visningsnamn för mappningen som används i diagnostik och operatörsinriktade konfigurationsgränssnitt. Håll namnen korta och beskrivande så att syftet med routningen är tydligt vid incidentgranskning.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Sessionsnyckel för hook-mappning`},help:{"v1-lfnt1n-58":`Explicit åsidosättning av sessionsnyckel för meddelanden som levereras via mappningar, för att styra trådkontinuiteten. Använd stabila nycklar med avgränsad räckvidd så att återkommande händelser kopplas samman utan att läcka över till orelaterade konversationer.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Sessionsläge för hook-mappning`},help:{"v1-1ggtdze-5k":`Styr mappningens sessionskontinuitet: "isolated" startar en ny körsession, medan "persistent" återanvänder den fastställda sessionKey. Behåll isolated om inte integrationen uttryckligen behöver varaktig kontext.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Textmall för hook-mappning`},help:{"v1-1rg732b-4y":`Reservmall med enbart text som används när avancerad rendering av nyttolasten inte önskas eller inte stöds. Använd detta för att tillhandahålla en kort, konsekvent sammanfattning för leverans i chattgränssnitt.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Åsidosättning av resonemang för hook-mappning`},help:{"v1-17hq8me-57":`Valfri åsidosättning av resonemangsnivån för körningar som utlöses av mappningar, för att balansera svarstid mot resonemangsdjup. Använd låg eller minimal nivå för hooks med stora volymer om inte djupare resonemang tydligt krävs.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Tidsgräns för hook-mappning (sek)`},help:{"v1-1r44ox2-4i":`Maximal tillåten körtid för mappningsåtgärder innan hantering av överskriden tidsgräns tillämpas. Använd snävare gränser för webhook-källor med stora volymer för att undvika att köer byggs upp.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Leveransdestination för hook-mappning`},help:{"v1-1p7928e-55":`Destinationsidentifierare inom den valda kanalen när svar från mappningen ska skickas till ett fast mål. Kontrollera leverantörsspecifika destinationsformat innan du aktiverar mappningar i produktion.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Transformering för hook-mappning`},help:{"v1-118nw83-5j":`Konfigurationsblock för transformering som definierar förbehandling via modul/export innan mappningsåtgärden hanteras. Använd endast transformeringar från granskade kodvägar och håll beteendet reproducerbart för reproducerbar automatisering.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Export för hook-transformering`},help:{"v1-atn8v-4b":`Namngiven export som ska anropas från transformeringsmodulen. Om den utelämnas används modulens standardexport. Ange detta när en fil innehåller flera transformeringshanterare.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Modul för hook-transformering`},help:{"v1-56futq-4v":`Relativ sökväg till en transformeringsmodul som läses in från hooks.transformsDir för att skriva om inkommande nyttolaster före leverans. Håll modulerna lokala, granskade och fria från mönster för katalogtraversering.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Väckningsläge för hook-mappning`},help:{"v1-1dzqfnw-59":`Schemaläggningsläge för väckning: "now" väcker omedelbart, medan "next-heartbeat" skjuter upp väckningen till nästa hjärtslagscykel. Använd uppskjutet läge för automatiseringar med lägre prioritet som tål en liten fördröjning.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Sökväg till hook-slutpunkt`},help:{"v1-1l9ijzv-4u":"HTTP-sökväg som används av hook-slutpunkten (till exempel `/hooks`) på gatewayens kontrollserver. Använd en svårgissad sökväg och kombinera den med tokenvalidering för skydd i flera lager."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Förinställningar för hooks`},help:{"v1-dp8m0l-4v":`Namngivna paket med hook-förinställningar som tillämpas vid inläsning för att ange standardmappningar och standardbeteenden. Ange användningen av förinställningar uttryckligen så att operatörer kan granska vilka automatiseringar som är aktiva.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Autentiseringstoken för hooks`},help:{"v1-1ihf6mv-82":`Delad bearer-token som kontrolleras vid inkommande hook-anrop för att autentisera begäranden innan mappningar körs. Behandla innehavare som fullt betrodda anropare för hook-ingången, inte som en separat roll utan ägarbehörighet. Använd miljövariabelsubstitution och rotera regelbundet när webhook-slutpunkter är tillgängliga via internet.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Katalog för hook-transformeringar`},help:{"v1-1ayj9p0-4t":`Baskatalog för hook-transformeringsmoduler som refereras av sökvägarna i mappningarnas transform.module. Använd en kontrollerad katalog i kodarkivet så att dynamiska importer förblir granskningsbara och förutsägbara.`}},logging:{label:{"v1-rq08xq-7":`Loggning`},help:{"v1-11an9pb-5e":`Inställningar för loggningens allvarlighetsgrad, utdatamål, formatering och maskering av känsliga uppgifter. Använd tillräckligt strikta nivåer och maskeringsregler för produktionsmiljöer, samtidigt som användbar diagnostikinformation bevaras.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Granskningslogg`},help:{"v1-1lauvy2-6w":`Begränsad granskningshistorik med enbart metadata för operatörsgranskning. Poster för körningar och verktyg är aktiverade som standard. Livscykelmetadata för meddelanden är ett separat, integritetskänsligt tillval. Bakgrundsskrivningen sker efter bästa förmåga och utgör inte ett förlustfritt arkiv för regelefterlevnad.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Granskningslogg aktiverad`},help:{"v1-snknxb-4v":`Registrerar nya granskningshändelser för körningar, verktyg och meddelanden där granskning är aktiverad. Standard: true. Ändringar träder i kraft omedelbart. Accepterade skrivningar slutförs och sparade rader förblir sökbara tills deras lagringstid löper ut.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Granskning av körningsidentitet`},help:{"v1-1ucirwv-5b":`Sparar begränsad information om kopplingen till körningsidentiteten för granskning av specifika körningar. Standard: false. Kräver logging.audit.enabled och gäller för körningar som tas emot efter aktiveringen. Befintliga kontexter förblir oförändrade.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Omfattning för meddelandegranskning`},help:{"v1-1yg4lc3-76":`Styr innehållsfria poster om meddelandens livscykel: "off" (standard), "direct" för enbart kända direktkonversationer eller "all" för direkt-, grupp- och kanalkonversationer samt okända konversationstyper. Kräver logging.audit.enabled. Ändringar gäller för efterföljande livscykelhändelser.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Loggnivå för konsolen`},help:{"v1-16badbd-5u":`Konsolspecifik loggtröskel: "silent", "fatal", "error", "warn", "info", "debug" eller "trace" för att styra terminalutdata. Använd detta för att minska mängden loggar i den lokala konsolen och samtidigt behålla mer detaljerad filloggning vid behov.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Konsolloggformat`},help:{"v1-d7u0iq-3q":`Format för konsolutdata: "pretty" eller "json". Använd json för maskinell bearbetning i pipelines och pretty för terminalarbetsflöden med fokus på läsbarhet.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Sökväg till loggfil`},help:{"v1-16gaitv-4w":`Valfri filsökväg för att spara loggutdata utöver eller i stället för konsolloggning. Använd en hanterad, skrivbar sökväg och anpassa lagringstid och rotation efter er driftpolicy.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Loggnivå`},help:{"v1-1r5yku0-5o":`Primär loggnivåtröskel för loggutdata under körning: "silent", "fatal", "error", "warn", "info", "debug" eller "trace". Behåll "info" eller "warn" i produktion och använd debug/trace endast vid felsökning.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Anpassade maskeringsmönster`},help:{"v1-12oyc60-8j":`Anpassade regex-strängar ersätter standardlistan med strängar för loggar och diagnostik. Inbyggda skydd för formulärdata, strukturerade autentiseringsuppgifter och fristående AWS-nycklar gäller alltid. Verktygsargument, resultat och sessionstranskript maskeras inte. Använd detta för att maskera distributionsspecifika token och identifierare i diagnostikutdata.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Globala MCP-serverdefinitioner som hanteras av OpenClaw. Inbäddad OpenClaw och andra körmiljöadaptrar kan använda dessa servrar utan att lagra dem i körmiljöns egna projektinställningar.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`MCP-appar`},help:{"v1-amyd91-38":`Stöd för MCP Apps-gränssnitt. När detta är aktiverat kan konfigurerade MCP-servrar tillhandahålla interaktiva HTML-vyer för sina verktygsresultat.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps aktiverat`},help:{"v1-ghqy98-3w":`Valfri aktivering av MCP Apps-rendering och en brygga mellan app och server. Låt detta vara inaktiverat om du inte litar på de konfigurerade MCP-servrar som tillhandahåller resurser för appgränssnitt.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Ursprung för MCP Apps-sandlådan`},help:{"v1-1sxv3mf-6v":`Valfritt dedikerat offentligt HTTP(S)-ursprung för MCP Apps. Använd detta bakom en omvänd proxy eller TLS-terminator och vidarebefordra trafiken endast till den konfigurerade porten för MCP Apps-sandlådan. Det måste skilja sig från ursprunget för Control UI och får inte leverera innehåll som kräver autentisering.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Port för MCP Apps-sandlådan`},help:{"v1-1b8n71l-4p":`Dedikerad lyssningsport för MCP Apps-sandlådan. Standardvärdet är Gateway-porten plus ett. Ange en ledig port om en annan lokal tjänst eller Gateway-profil redan använder porten.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`MCP-servrar`},help:{"v1-157ozoz-42":`Namngivna MCP-serverdefinitioner. OpenClaw lagrar dem i sin egen konfiguration och körningsadaptrar avgör vilka transporter som stöds vid körning.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Autentisering för MCP-server`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`MCP-klientcertifikat`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`MCP-klientnyckel`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`MCP-klientcertifikat`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`MCP-klientnyckel`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Codex MCP-projektion`},help:{"v1-slcmq1-6x":`OpenClaw-projektionsmetadata endast för Codex app-server-trådar. Detta påverkar inte ACP-sessioner eller generell konfiguration av Codex-harness. Utelämna detta block för att hålla servern tillgänglig för alla Codex app-server-agenter med Codex standardbeteende för MCP-godkännande.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Codex MCP-agenter`},help:{"v1-1i6v0fm-6a":`Valfria, icke-tomma OpenClaw-agent-ID:n som ska få denna MCP-server i trådkonfigurationen för Codex app-server. Listor utan giltiga agent-ID:n ger ingen åtkomst. Om listan utelämnas projiceras servern för alla Codex app-server-agenter.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Godkännande av Codex MCP-verktyg`},help:{"v1-1xql0qr-3d":`Codex egen stavning för samma serverspecifika godkännandeläge för MCP-verktyg. Använd helst defaultToolsApprovalMode i OpenClaw-konfigurationen.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Godkännande av Codex MCP-verktyg`},help:{"v1-y5vsqq-3s":`Valfritt godkännandeläge för Codex MCP-verktyg på denna server: "auto", "prompt" eller "approve". Använd endast för MCP-servrar som du medvetet litar på.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Tidsgräns för MCP-anslutning (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`MCP-server aktiverad`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`MCP OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Autentiseringsprofil för MCP OAuth`},help:{"v1-fcrb4u-5z":`ID för en autentiseringsprofil med stöd för förnyelse som används för att infoga den aktuella bearer-token i denna fjärranslutna MCP-server. När detta anges hämtar och förnyar OpenClaw profilen vid körning utan att skicka vidare förnyelseuppgifter.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL för MCP OAuth-klientmetadata`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`MCP OAuth-identitet`},help:{"v1-1ie6ys7-59":`Ägarskap för OAuth-autentiseringsuppgifter för denna server. Utelämna detta fält eller använd "shared" för operatörshanterade autentiseringsuppgifter; använd "per-requester" för att låta varje autentiserad avsändare ansluta sitt eget konto.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`Omdirigerings-URL för MCP OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Behörighetsomfång för MCP OAuth`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Tidsgräns för MCP-förfrågningar (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`TLS-verifiering för MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`TLS-verifiering för MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Parallella MCP-verktygsanrop`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Parallella MCP-verktygsanrop`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Val av MCP-verktyg`},help:{"v1-10poyzb-4v":`Val av MCP-verktyg per server. Använd include för att endast göra utvalda MCP-verktygsnamn tillgängliga, eller exclude för att dölja utvalda MCP-verktygsnamn. Posterna accepterar exakta namn och enkla jokerteckenmönster med '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Undantagna MCP-verktyg`},help:{"v1-ijrc5y-1u":`Exakta MCP-verktygsnamn eller enkla jokerteckenmönster med '*' som ska döljas från den här servern.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Inkluderade MCP-verktyg`},help:{"v1-89fdfq-3o":`Exakta MCP-verktygsnamn eller enkla jokerteckenmönster med '*' som ska exponeras från den här servern. Om detta utelämnas förblir alla serververktyg tillgängliga om de inte uttryckligen exkluderas.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL vid inaktivitet för MCP-sessioner (ms)`},help:{"v1-j9si74-87":`Valfri tidsgräns i millisekunder för avveckling av inaktiva MCP-körmiljöer i OpenClaw-sessioner. Om värdet inte anges eller är 0 hålls körmiljöerna aktiva tills sessionen rensas eller Gateway stängs av. Positiva värden avrundas nedåt; aktiva nyttjanderätter och väntande förvärv förhindrar avveckling. Körmiljöer som ägs av en körning avvecklas fortfarande när deras engångskörning avslutas.`}},memory:{label:{"v1-oopaku-6":`Minne`},help:{"v1-1wlx40m-13":`Konfiguration för det inbyggda minnet (global).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Läge för källhänvisningar från minnet`},help:{"v1-1q6dxr5-4u":`Styr om källhänvisningar visas i svar: "auto" visar dem när de är användbara, "on" visar dem alltid och "off" döljer dem. Behåll "auto" som standard för en bra balans mellan relevant information och brus.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Minnessökning`},help:{"v1-1ukbud1-25":`Vektorsökning i MEMORY.md och memory/*.md (åsidosättningar per agent stöds).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Cache för inbäddningar vid minnessökning`},help:{"v1-d8h2e4-5b":`Cachelagrar beräknade inbäddningar för textsegment i SQLite så att omindexering och inkrementella uppdateringar går snabbare (standard: true). Låt detta vara aktiverat om du inte undersöker cachens korrekthet eller vill minimera diskanvändningen.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Indatatyp för dokument vid minnessökning`},help:{"v1-1ui33sv-5f":"Valfritt leverantörsspecifikt `input_type`-värde för minnesinbäddningar vid dokumenthantering och indexering. Använd detta med OpenAI-kompatibla asymmetriska inbäddningsändpunkter som kräver en etikett för textavsnitt eller dokument."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Aktivera minnessökning`},help:{"v1-14f11b9-4t":`Huvudreglage för indexering och hämtning vid minnessökning i den här agentprofilen. Låt det vara aktiverat för semantisk återkallning och inaktivera det när du vill ha helt tillståndslösa svar.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Sessionsindex för minnessökning (experimentellt)`},help:{"v1-qvhv8z-3i":`Indexerar sessionstranskriptioner för minnessökning. Behåll denna avancerade åsidosättning när arvet för återkallning skiljer sig mellan rotnivån och enskilda agenter.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Extra minnessökvägar`},help:{"v1-ojqokq-7i":`Lägger till extra kataloger eller .md-filer i minnesindexet utöver standardminnesfilerna. Poster kan vara sökvägssträngar eller objekt med ett globmönster relativt roten. När multimodalt minne är aktiverat kan även matchande bild- och ljudfiler under dessa sökvägar indexeras.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Extra minnessökväg`},help:{"v1-b9mbq8-3m":`Anger den extra minneskatalogen eller minnesfilen. Relativa sökvägar utgår från agentens arbetsyta; direkt angivna filer indexeras exakt som angivet.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Mönster för extra minnessökväg`},help:{"v1-j8br1v-4e":`Begränsar en katalogpost till filer som stöds och matchar detta globmönster relativt roten, till exempel "runbooks/**/*.md". Utelämna det för att söka igenom alla filer som stöds rekursivt.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Reservleverantör för minnessökning`},help:{"v1-1r6368w-6p":`Reservleverantör som används när den primära inbäddningen misslyckas: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" eller "none". Ange en faktisk reservleverantör för tillförlitlig drift i produktion. Använd "none" endast om du föredrar uttryckliga fel.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Indatatyp för minnessökning`},help:{"v1-26vbwe-5u":"Använd detta valfria leverantörsspecifika `input_type`-värde endast när samma etikett ska gälla för inbäddningsförfrågningar för både sökfrågor och dokument. För asymmetriska leverantörer bör du i stället använda queryInputType och documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Sökväg till lokal inbäddningsmodell`},help:{"v1-13ymbnt-5q":"Anger källan till den lokala inbäddningsmodellen för lokal minnessökning, till exempel en sökväg till en GGUF-fil eller en `hf:`-URI. Använd detta endast när provider är `local`, och kontrollera modellens kompatibilitet innan stora index byggs om."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Modell för minnessökning`},help:{"v1-11pohrl-59":`Åsidosättning av inbäddningsmodell som används av den valda minnesleverantören när en annan modell än standardmodellen krävs. Ange detta endast när du behöver finjustera sökningens återfinningsgrad eller kostnad utöver leverantörens standardinställningar.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Multimodal minnessökning`},help:{"v1-1jn02s-9e":'Valfria inställningar för multimodalt minne för indexering av bild- och ljudfiler från konfigurerade extra sökvägar. Låt detta vara avstängt om inte din inbäddningsmodell uttryckligen stöder inbäddningar över modalitetsgränser, och ange "none" för `memory.search.fallback` när det är aktiverat. Matchande filer laddas upp till den konfigurerade fjärrleverantören för inbäddningar under indexeringen.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Aktivera multimodal minnessökning`},help:{"v1-1dk5d7o-7e":`Aktiverar indexering av bilder och ljud från extraPaths i minnet. Detta kräver för närvarande Gemini embedding-2, begränsar standardrotkatalogerna för minnet till Markdown, inaktiverar reservleverantörer för minnessökning och laddar upp matchande binärt innehåll till den konfigurerade fjärrleverantören för inbäddningar.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Maximal filstorlek i byte för multimodal minnessökning`},help:{"v1-1mmdrvk-5d":`Anger det maximala antalet byte som tillåts per multimodal fil innan den hoppas över vid minnesindexering. Använd detta för att begränsa uppladdningskostnaden och indexeringstiden, eller höj gränsen för korta ljudklipp av hög kvalitet.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modaliteter för multimodal minnessökning`},help:{"v1-alp4vh-4l":`Väljer vilka multimodala filtyper som indexeras från extraPaths: "image", "audio" eller "all". Begränsa urvalet för att undvika oavsiktlig indexering av stora binära datamängder.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Antal utdatadimensioner för minnessökning`},help:{"v1-1f7zu53-93":`Leverantörsspecifik åsidosättning av utdatavektorns storlek för minnesinbäddningar. Gemini-modeller stöder 128–3072 dimensioner och rekommenderar 768, 1536 eller 3072. Bedrock-familjer som Titan V2, Cohere V4 och Nova har egna tillåtna storlekar. Räkna med en fullständig omindexering när du ändrar värdet, eftersom lagrade vektordimensioner måste vara konsekventa.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Leverantör för minnessökning`},help:{"v1-5evseb-71":`Väljer den inbäddningsbackend som används för att skapa och söka i minnesvektorer. Standardvärdet är "openai"; ange "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" eller "local" om du vill använda en annan backend.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Maximalt antal resultat vid minnessökning`},help:{"v1-13ekath-4x":`Maximalt antal minnesträffar som returneras från sökningen före efterföljande omrangordning och infogning i prompten. Höj värdet för bredare återhämtning av minnen, eller sänk det för mer koncentrerade prompter och snabbare svar.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Lägsta poäng vid minnessökning`},help:{"v1-1ww231l-4v":`Lägsta relevanspoäng som krävs för att inkludera minnesresultat i det slutliga återhämtningsresultatet. Höj värdet för att minska antalet svaga eller brusiga träffar, eller sänk det när du behöver en mindre restriktiv hämtning.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Indatatyp för minnessökfrågor`},help:{"v1-831yrv-4q":"Valfritt leverantörsspecifikt `input_type`-värde för minnesinbäddningar vid sökning. Använd detta med OpenAI-kompatibla asymmetriska inbäddningsändpunkter som kräver en frågeetikett."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Kom ihåg mellan konversationer`},help:{"v1-k1itm8-7y":`Använd relevant kontext från den här agentens andra privata konversationer genom skyddad återhämtning av konversationshistorik. Aktiveras som standard endast när globala session.dmScope inte är angiven eller är "main" och ingen bindning åsidosätter DM-omfånget; om någon DM-isolering är konfigurerad är funktionen avstängd som standard. Ett uttryckligt true eller false har alltid företräde.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`API-nyckel för fjärrinbäddning`},help:{"v1-nfuuu-62":`Anger en separat API-nyckel för fjärranrop som skapar inbäddningar vid minnesindexering och sökning. Använd detta när minnesinbäddningar ska använda andra autentiseringsuppgifter än de globala standardvärdena eller miljövariablerna.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`Bas-URL för fjärrinbäddningar`},help:{"v1-1ugvqgt-5p":`Åsidosätter API-slutpunkten för inbäddningar, till exempel en OpenAI-kompatibel proxy eller en anpassad bas-URL för Gemini. Använd detta endast vid routning via din egen gateway eller leverantörsslutpunkt. Behåll annars leverantörens standardvärden.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Fjärrinbäddningar i batch aktiverade`},help:{"v1-1fehqi-5x":`Aktiverar leverantörens batch-API:er för inbäddningsjobb när stöd finns (OpenAI/Gemini), vilket ökar genomströmningen vid större indexeringskörningar. Låt detta vara aktiverat om du inte felsöker fel i leverantörens batchbearbetning eller kör mycket små arbetsbelastningar.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`HTTP-huvuden för fjärrinbäddningar`},help:{"v1-1uic0kd-5i":`Lägger till anpassade HTTP-huvuden i begäranden om fjärrinbäddningar och slår samman dem med leverantörens standardvärden. Använd detta för proxyautentisering och klientbaserad routning, och begränsa värdena till det nödvändigaste för att undvika att känsliga metadata läcker ut.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Källor för minnessökning`},help:{"v1-btxtzg-57":`Väljer vilka källor som indexeras: "memory" läser MEMORY.md + minnesfiler, och "sessions" inkluderar konversationshistorik. Behåll ["memory"] om du inte behöver hämta information från tidigare chattkonversationer.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Vektorindex för minnessökning`},help:{"v1-fbybkj-37":`Styr det semantiska indexet i sqlite-vec. Behåll denna avancerade åsidosättning när vektorpolicyerna på rotnivå och för enskilda agenter skiljer sig åt.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Sökväg till vektortillägg för minnessökning`},help:{"v1-1hysv5q-58":"Åsidosätter den automatiskt identifierade sökvägen till tilläggsbiblioteket sqlite-vec (`.dylib`, `.so` eller `.dll`). Använd detta när din körmiljö inte kan hitta sqlite-vec automatiskt eller när du låser till en byggversion som du vet fungerar."}},messages:{label:{"v1-1wwzqad-8":`Meddelanden`},help:{"v1-i5k0iw-5k":`Meddelandeinfrastruktur och standardinställningar som är gemensamma för agenter. Poster på rotnivå ansvarar för infrastrukturen och de gemensamma standardinställningarna; agents.defaults ansvarar för agentloopens beteende; agentposter kan åsidosätta båda där det stöds.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji för bekräftelsereaktion`},help:{"v1-1iip0zs-1x":`Emojireaktion som används för att bekräfta inkommande meddelanden (tomt värde inaktiverar).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Omfattning för bekräftelsereaktioner`},help:{"v1-1jvdg5n-7s":`När bekräftelsereaktioner ska skickas ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" bekräftar gruppmeddelanden som nämner agenten, oavsett om gruppen kräver omnämnanden eller inte; "group-all" bekräftar alla gruppmeddelanden. "off"/"none" inaktiverar bekräftelsereaktioner helt.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Regler för gruppchattar`},help:{"v1-chqsvh-4l":`Inställningar för hantering av gruppmeddelanden, inklusive utlösare för omnämnanden och historikfönstrets storlek. Använd snäva mönster för omnämnanden så att inte varje meddelande i gruppkanaler utlöser en reaktion.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Gräns för grupphistorik`},help:{"v1-1mkbpw-9k":`Maximalt antal tidigare gruppmeddelanden som läses in som kontext per tur för gruppsessioner. Använd högre värden för bättre kontinuitet eller lägre värden för snabbare och billigare svar. Automatisk prompthistorik är begränsad till 200 meddelanden. Det maximala heltalsvärdet i JSON väljer kanalens standardfönster (50 för delad grupphistorik), inte ett obegränsat fönster.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Mönster för omnämnanden i grupper`},help:{"v1-i7h7qc-6f":`Säkra regex-mönster som inte skiljer på versaler och gemener och används för att upptäcka uttryckliga omnämnanden eller utlösande fraser i gruppchattar. Använd precisa mönster för att minska antalet falska träffar i kanaler med många meddelanden. Ogiltiga eller osäkra mönster med nästlade upprepningar ignoreras.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Inkommande gruppmeddelanden utan omnämnande`},help:{"v1-17wef8h-5f":`Styr hur gruppmeddelanden utan omnämnande skickas in när gruppbevakning alltid är aktiv. "user_request" behandlar dem som en användarförfrågan; "room_event" skickar in dem som tyst kontext där synlig utdata kräver meddelandeverktyget.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Synliga svar i grupper`},help:{"v1-qa4z1s-aa":`Åsidosätter modellgenererade svar till ursprungskonversationen i grupp- och kanalkonversationer. Standardvärdet är "automatic" när ingen global policy för synliga svar har angetts. "message_tool" kräver message(action=send) för normal assistentutdata och generella medier från verktyg; körningsutdata som uttryckligen ägs av värdsystemet kan fortfarande levereras, förutom vid bakgrundshändelser i rummet. "automatic" publicerar vanliga svar som tidigare.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Fördröjd sammanslagning av inkommande meddelanden`},help:{"v1-ebyu5x-4a":`Inställningar för fördröjd sammanslagning av inkommande meddelanden innan kö- eller turbearbetningen börjar. Konfigurera detta för leverantörsspecifika skurar av snabba meddelanden från samma avsändare.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Sammanslagningsfördröjning per kanal (ms)`},help:{"v1-wbz54j-4g":`Kanalspecifika åsidosättningar av sammanslagningsfördröjningen för inkommande meddelanden, i millisekunder, med leverantörs-id som nyckel. Använd detta när vissa leverantörer skickar meddelandefragment tätare än andra.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Sammanslagningsfördröjning för inkommande meddelanden (ms)`},help:{"v1-1616yo2-7w":`Väntetid utan nya meddelanden (ms) för att gruppera snabba inkommande meddelanden från samma avsändare. Telegram använder 300 ms som standard när varken en global eller kanalspecifik åsidosättning har angetts. Övriga kanaler använder 0 som standard. Noll inaktiverar vanlig gruppering av meddelandeskurar, men Telegram sammanfogar fortfarande delar av långa meddelanden som ligger nära längdgränsen.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Kö för inkommande meddelanden`},help:{"v1-hm2o31-48":`Köstrategi för inkommande meddelanden som anländer medan en sessionskörning är aktiv. Använd detta för att anpassa styrning, uppskjutna uppföljningar, gruppering eller avbrott.`}},"messages%2Equeue%2EallowCollaborativeSteering":{label:{"v1-1lzdhxt-m":`Tillåt gemensam styrning`},help:{"v1-j2909o-es":`Tillåt godkänd mänsklig inmatning i samma konversation att styra under den aktiva turens oförändrade identitet och förberedda behörigheter, även när avsändaren har färre behörigheter (standard: true). När värdet är false väljer collaborativeSteeringFallback antingen en köad tur som tillhör den som skickade begäran och körs utan statusmeddelande (queue), eller ett strikt avslag (reject). Vanlig vägledning från samma person som skickade begäran behåller den aktiva körningens förberedda behörigheter. Aktuell åtkomst, befogenheter för pågående körning, kontroller av körningsinställningar, kölägen och behörighet för styrning över sessionsgränser gäller fortfarande.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Köläge per kanal`},help:{"v1-1vbyy4u-5q":`Kanalspecifika åsidosättningar av köläget med kanal-id som nyckel, inklusive instickskanaler (till exempel discord, telegram, x). Använd detta när en kanals trafikmönster kräver ett annat beteende än de globala standardinställningarna.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Kökapacitet`},help:{"v1-16ql8c7-4j":`Maximalt antal inkommande poster som behålls i kön innan borttagningspolicyn tillämpas. Standardvärdet är 20. Begränsa kapaciteten i kanaler med mycket trafik så att minnesanvändningen förblir förutsägbar.`}},"messages%2Equeue%2EcollaborativeSteeringFallback":{label:{"v1-3k0wft-v":`Reservåtgärd för gemensam styrning`},help:{"v1-peu9fu-8i":`Vad som händer när en annan person inte kan styra eftersom samarbetsstyrning är inaktiverad: "queue" (standard) kör personens inmatning som en separat tur utan statusmeddelande; "reject" behåller strikt avslag och kräver en ny /followup-begäran. Aktiverar inte samarbetsstyrning och kringgår inte åtkomstkontroller.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Reservvärde för köns fördröjning per kanal (ms)`},help:{"v1-1w7gk9b-54":`Kanalspecifika åsidosättningar av köns fördröjning, med kanal-ID som nyckel, inklusive plugin-kanaler. Använd detta för att anpassa hanteringen av meddelandeanhopningar separat för chattytor med olika tempo.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Strategi för att kasta köposter`},help:{"v1-ydb2rw-6m":`Strategi för att kasta poster när kögränsen överskrids. "summarize" kastar de äldsta posterna men bevarar korta sammanfattningar; "old" kastar de äldsta utan sammanfattningar; "new" avvisar den senaste posten. Använd "summarize" för långvariga chattar där sammanhanget är viktigt.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Köläge`},help:{"v1-19k7gy1-67":`Köläge för aktiva körningar. Använd "steer" för att infoga promptar i den aktiva körningen, "followup" för att köra senare, "collect" för att samla kompatibla meddelanden för senare körning eller "interrupt" för att avbryta den aktiva körningen innan den senaste prompten startas.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Prefix för utgående svar`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Standardläge för användningsinformation i sidfoten`},help:{"v1-l3shsx-dv":`Standardläge för användningsinformation i varje svars sidfot ("off"|"tokens"|"full") som tilldelas sessioner som inte har valt ett läge via /usage. Godtar även "on" som ett äldre alias för "tokens". Godtar ett enskilt läge eller en mappning per kanal med "default" som reservvärde. Prioritetsordning: sessionsvärde -> kanalpost -> default -> off; ett uttryckligt val via /usage (inklusive off) sparas och åsidosätter standardvärdet. Använd /usage reset (alias: inherit, clear, default) för att ta bort en sessions åsidosättning och åter ärva detta konfigurerade standardvärde.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Statusreaktioner`},help:{"v1-193764l-3s":`Statusreaktioner under livscykeln som uppdaterar emojin på det utlösande meddelandet allteftersom agenten arbetar (köad → tänker → verktyg → klar/fel).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Aktivera statusreaktioner`},help:{"v1-1qnmmnc-7x":`Aktivera statusreaktioner under livscykeln på kanaler som stöds. Discord tolkar ett ej angivet värde som aktiverat när bekräftelsereaktioner är aktiva; Slack, Signal, Telegram och WhatsApp kräver att detta är true innan livscykelreaktioner används. Slack använder som standard sin inbyggda trådstatus för assistenter för att visa förloppet.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Mall för användningssidfot`},help:{"v1-1xibc23-47":`Anpassad sidfotsmall för /usage full, antingen som ett inbäddat objekt eller en sökväg till en JSON-fil. Om mallen är ogiltig eller inte tillgänglig används den inbyggda användningsraden.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Synliga svar`},help:{"v1-7yfwc2-8t":`Styr modellgenererade källsvar i direkt-, grupp- och kanalkonversationer. "message_tool" kräver message(action=send) för vanlig assistentutdata och generiska verktygsmedier; körningsutdata som uttryckligen ägs av värden kan fortfarande levereras, med undantag för bakgrundshändelser i rummet. "automatic" publicerar vanliga svar som tidigare.`}},meta:{label:{"v1-1xpfxac-m":`Kompatibilitetsmetadata`},help:{"v1-1owqhgn-2w":`Kompatibilitetsmetadata som kan läsas av äldre versioner och behålls så att äldre binärfiler kan avvisa osäkra nedgraderingar av konfigurationen.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Version som senast ändrade konfigurationen`},help:{"v1-qykpv1-1i":`Den OpenClaw-version som senast skrev den här konfigurationen.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Markörer för konfigurationsmigrering`},help:{"v1-burt8q-1q":`Avgränsade kompatibilitetsmarkörer för slutförda konfigurationsmigreringar.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migrering av tillåtelselista för modellpolicy`},help:{"v1-5psop1-1z":`Registrerar att äldre begränsningar i modellmappningen har bevarats eller utvärderats.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migrering för separation av hjälpmodeller`},help:{"v1-vzdfqx-2t":`Registrerar att äldre implicita primärmodeller har bevarats innan valet av hjälpmodell separerades.`}},models:{label:{"v1-hzmwb-6":`Modeller`},help:{"v1-1h1niol-5q":`Modellkatalogens rot för leverantörsdefinitioner, beteende vid sammanslagning eller ersättning samt valfri integration med Bedrock för identifiering av modeller. Håll leverantörsdefinitionerna explicita och validerade innan du förlitar dig på reservvägar vid fel i produktion.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Uppdatering av modellkatalog`},help:{"v1-1hess4t-40":`Styr bakgrundsuppdateringar av den medföljande modellkatalogen. Fjärrposter kan uppdatera modellmetadata men kan inte ändra leverantörernas ändpunkter eller HTTP-huvuden.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Uppdatering av modellkatalog aktiverad`},help:{"v1-1fogpjj-3j":`Hämta uppdateringar av den fjärrlagrade modellkatalogen i bakgrunden (standard: true). Ange false för att inaktivera all fjärrtrafik för modellkatalogen.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL för uppdatering av modellkatalog`},help:{"v1-ai1thy-6o":`Åsidosätt URL:en för den fjärrlagrade modellkatalogen med en egen HTTPS-spegel (HTTP på localhost tillåts för testning). En Gateway som körs slutar använda katalogen från den tidigare källan och börjar använda spegelns vid nästa katalogkontroll, utan omstart.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Läge för modellkatalog`},help:{"v1-1ofrnsp-es":`Styr leverantörskatalogens beteende: "merge" behåller inbyggda leverantörer och lägger dina anpassade leverantörer ovanpå, medan "replace" endast använder dina konfigurerade leverantörer. I "merge" bevaras icke-tomma baseUrl-värden i agentens models.json för matchande leverantörs-ID:n, medan apiKey-värden endast bevaras när leverantören inte hanteras via SecretRef i den aktuella konfigurations-/autentiseringsprofilkontexten. Leverantörer som hanteras via SecretRef uppdaterar apiKey från aktuella källmarkörer, och för matchande modeller används det högre värdet av explicita och implicita poster för contextWindow/maxTokens.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Modellleverantörer`},help:{"v1-1y5jg0v-8p":`Leverantörstabell med leverantörs-ID som nyckel, som innehåller anslutnings-/autentiseringsinställningar och konkreta modelldefinitioner. Inbyggda leverantörer kan anpassas med överlagringar på leverantörsnivå. Anpassade leverantörer måste innehålla baseUrl och models. Använd stabila leverantörsnycklar så att referenser från agenter och verktyg förblir portabla mellan miljöer.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Körmiljö för modellleverantör`},help:{"v1-1luy4fb-5o":`Valfri lågnivåpolicy för agentens körmiljö hos den här leverantören. Använd en körmiljöpolicy per leverantör/modell i stället för att låsa körmiljön för hela agenten. Om inställningen utelämnas eller lämnas som standard väljer OpenClaw körmiljö för den valda leverantören.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`Körmiljö-ID för modellleverantör`},help:{"v1-1gusd9s-69":`ID för leverantörens agentkörmiljö: "openclaw", "auto", ett registrerat ID för ett plugin-körramverk som "codex", eller ett CLI-backendalias som stöds, exempelvis "claude-cli". För OpenAI på den officiella slutpunkten används Codex-körramverket som standard om inställningen utelämnas.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`API-adapter för modellleverantör`},help:{"v1-16c28rb-57":`Val av API-adapter för leverantören som styr kompatibilitetshanteringen för förfrågningar och svar vid modellanrop. Använd adaptern som matchar protokollet hos din uppströmsleverantör för att undvika inkompatibla funktioner.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Modellleverantörens API-nyckel`},help:{"v1-1p84k96-54":`Leverantörens autentiseringsuppgift som används för API-nyckelbaserad autentisering när leverantören kräver direkt nyckelautentisering. Använd substitution med hemligheter eller miljövariabler och undvik att lagra riktiga nycklar i konfigurationsfiler som checkas in i versionshanteringen.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Modellleverantörens autentiseringsläge`},help:{"v1-1l1lwxr-5p":`Väljer leverantörens autentiseringsmetod: "api-key" för autentisering med API-nyckel, "token" för autentisering med bearer-token, "oauth" för OAuth-autentiseringsuppgifter och "aws-sdk" för hämtning av AWS-autentiseringsuppgifter. Anpassa detta efter leverantörens krav.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Modellleverantörens Authorization-header`},help:{"v1-1gn3lt3-59":`När värdet är true skickas autentiseringsuppgifter via HTTP-headern Authorization även om andra autentiseringsmetoder är möjliga. Använd detta endast när leverantören eller proxyn uttryckligen kräver vidarebefordran av Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`Modellleverantörens bas-URL`},help:{"v1-1ku88v8-53":`Bas-URL för leverantörens slutpunkt som hanterar modellförfrågningar för den leverantörsposten. Använd HTTPS-slutpunkter och håll URL:er miljöspecifika med hjälp av konfigurationsmallar vid behov.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Modellleverantörens headers`},help:{"v1-chg59u-4x":`Statiska HTTP-huvuden som läggs till i leverantörsanrop för klientroutning, proxyautentisering eller anpassade krav för Gateway. Använd detta sparsamt och lagra känsliga huvudvärden som hemligheter.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Infoga num_ctx för modellleverantör (OpenAI-kompatibilitet)`},help:{"v1-53rmcr-6n":"Styr om OpenClaw infogar `options.num_ctx` för Ollama-leverantörer som konfigurerats med den OpenAI-kompatibla adaptern (`openai-completions`). Standardvärdet är true. Ange false endast om din proxy eller uppströmstjänst avvisar okända `options`-fält i nyttolasten."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Lokal tjänst för modellleverantör`},help:{"v1-9r1lm6-4y":`Valfri lokal modellserverprocess som startas vid behov för den här leverantören. OpenClaw kontrollerar healthUrl, startar kommandot vid behov, väntar tills servern är redo och skickar sedan modellanropet.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Argument för modellleverantörens lokala tjänst`},help:{"v1-t12wib-27":`Argumentlista som skickas till kommandot för den lokala modellservern utan skalexpansion.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Kommando för modellleverantörens lokala tjänst`},help:{"v1-64k3ef-4h":`Absolut sökväg till den körbara filen för den lokala modellserverprocessen. Ange sökvägen uttryckligen så att leverantörens start är förutsägbar och inte beror på skalets sökning i PATH.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Arbetskatalog för modellleverantörens lokala tjänst`},help:{"v1-fi3xlx-1h":`Arbetskatalog för den lokala modellserverprocessen.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Miljö för modellleverantörens lokala tjänst`},help:{"v1-1lwb9k1-3k":`Ytterligare miljövariabler för den lokala modellserverprocessen. Värden som verkar vara hemliga maskeras i ögonblicksbilder av konfigurationen.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL för hälsokontroll av modellleverantörens lokala tjänst`},help:{"v1-12nvqxl-36":`URL som kontrolleras före modellförfrågningar för att säkerställa att servern är redo. Om den utelämnas använder OpenClaw leverantörens baseUrl med /models tillagt.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Stopp vid inaktivitet för modellleverantörens lokala tjänst`},help:{"v1-1efg054-3z":`Antal millisekunder som en lokal modellserver som startats av OpenClaw ska hållas igång efter att den senaste förfrågan har slutförts. Ange 0 för att hålla den igång tills OpenClaw avslutas.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Tidsgräns för modellleverantörens lokala tjänst att bli redo`},help:{"v1-bwmfqa-2r":`Maximalt antal millisekunder att vänta på kontrollen av att den lokala modellservern är redo efter att processen har startats.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Maximalt antal token för modellleverantören`},help:{"v1-fnj50y-38":`Standardgräns för maximalt antal utdatatoken som används för modeller hos den här leverantören när en modellpost inte anger maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Modellleverantörens modellista`},help:{"v1-1vbm0gt-63":`Deklarerad modellista för en leverantör med identifierare, metadata, leverantörsspecifika parametrar och valfria uppgifter om kompatibilitet och kostnader. Se till att ID:n exakt motsvarar värdena i leverantörens katalog så att val och reservlösningar fungerar korrekt.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Modellens körmiljö`},help:{"v1-1k70g2n-3g":`Valfri lågnivåpolicy för agentens körmiljö för just denna modell. Modellens körmiljöpolicy åsidosätter leverantörens körmiljöpolicy.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`ID för modellens körmiljö`},help:{"v1-1llzv33-42":`ID för modellagentens körmiljö: "openclaw", "auto", ett registrerat ID för ett insticksprograms körningsramverk, exempelvis "codex", eller ett CLI-backendalias som stöds, exempelvis "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Modellens medieindata`},help:{"v1-wxtj8e-2x":`Valfria metadata om modellens mediefunktioner som verktyg använder för att välja försiktiga standardinställningar för bildkomprimering.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Modellens bildindata`},help:{"v1-1nviirq-3c":`Valfria begränsningar för modellens bildindata, såsom maximal sidlängd, maximalt antal pixlar och önskad sidlängd vid komprimering.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Maximalt antal byte för modellens bilder`},help:{"v1-c2469j-23":`Maximal storlek på kodade bilddata som leverantören accepterar för denna modell.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Maximalt antal bildpixlar för modellen`},help:{"v1-9d6yqp-1u":`Det maximala antal bildpixlar som leverantören accepterar för den här modellen.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Maximal bildsida för modellen`},help:{"v1-1gbci08-1y":`Den maximala bildbredd eller bildhöjd som leverantören accepterar för den här modellen.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Önskad bildsida för modellen`},help:{"v1-1u1mpcg-2x":`Önskad sidlängd vid storleksändring av bilder för balanserad komprimering. Lämna värdet oangivet för att använda OpenClaws försiktigt valda standardvärde.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Läge för bildtokenberäkning för modellen`},help:{"v1-1oy6z7v-1z":`Leverantörens metod för beräkning av bildtoken: "tile", "detail" eller "provider".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EresponseModelEquivalent":{help:{"v1-1hociw2-d7":`Ange true på en användarskapad rad för en anpassad leverantör när en router eller förmedlare själv hanterar detta modell-id. Alla svars-id:n som slutpunkten rapporterar betraktas då som likvärdiga, även vid interna ersättningar i slutpunkten. Det id som faktiskt används och användningen registreras fortfarande; OpenClaws meddelanden om reservval och åsidosättningar finns kvar. Medföljande eller officiell policy kan inte åsidosättas. Rader från insticksprogram eller kataloger, agentens models.json-rader och models-add-rader kan inte ge likvärdighet. Om värdet utelämnas eller anges som false behålls normal identifiering av routning.`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Körningsparametrar för modellleverantören`},help:{"v1-464sgu-4t":`Leverantörsspecifika körningsparametrar som tolkas av leverantörens insticksprogram. Använd endast nycklar som dokumenteras av leverantören och prioritera uttrycklig leverantörsdokumentation framför tillfälliga gemensamma antaganden.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Modellleverantörens region`},help:{"v1-yq7rxk-5h":`Valfri distributions-/API-region för leverantören som tolkas av leverantörer med regionala slutpunkter. Se leverantörens dokumentation för värden som stöds; åsidosättningar av baseUrl har vanligtvis företräde när båda är angivna.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Åsidosättningar för förfrågningar till modellleverantören`},help:{"v1-1lkxryk-87":`Valfria åsidosättningar för förfrågningar till modellleverantören, inklusive extra HTTP-huvuden, åsidosättningar av autentisering, proxyroutning, TLS-klientinställningar och valfri allowPrivateNetwork för betrodda slutpunkter med egen drift. Använd dessa endast när den överordnade tjänsten eller nätverksvägen i företaget kräver anpassning av transporten.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Tillåt privat nätverk för förfrågningar till modellleverantören`},help:{"v1-1nbtcjk-fo":`När värdet är true tillåts HTTP-förfrågningar till modellleverantören inom privata adressintervall, CGNAT-intervall eller liknande intervall genom leverantörens skydd för HTTP-hämtning (fetchWithSsrFGuard). Anpassade/lokala bas-URL:er för leverantörer litar redan på exakt det konfigurerade ursprunget, med undantag för ursprung för metadata, länklokala adresser och NAT64 för lokalt bruk (64:ff9b:1::/48); ange false för att avstå från detta förtroende. OpenAI Responses WebSocket återanvänder request för HTTP-huvuden/TLS men använder inte denna SSRF-skyddade hämtningsväg. Använd true endast för operatörskontrollerade slutpunkter med egen drift som måste nå privata ursprung utanför det konfigurerade baseUrl-ursprunget.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Åsidosättning av autentisering för förfrågningar till modellleverantören`},help:{"v1-ucdgnf-1w":`Åsidosätt autentiseringsbeteendet för förfrågningar till den här leverantören.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Namn på autentiseringsheader för förfrågningar till modellleverantören`},help:{"v1-1881nqr-1i":`Anpassat namn på autentiseringsheadern som används när autentiseringsläget är header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Autentiseringsläge för förfrågningar till modellleverantören`},help:{"v1-1lhv8hs-24":`Läge för åsidosättning av autentisering: "provider-default", "authorization-bearer" eller "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Prefix för autentiseringsheader för förfrågningar till modellleverantören`},help:{"v1-1rbm9lz-21":`Valfritt prefix som läggs före request.auth.value när autentiseringsläget är header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Bearer-token för förfrågningar till modellleverantören`},help:{"v1-6rcasw-1l":`Bearer-token som används när autentiseringsläget är authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Värde för autentiseringsheader för förfrågningar till modellleverantören`},help:{"v1-1v69ej-1j":`Anpassat värde för autentiseringsheadern som används när autentiseringsläget är header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Headers för förfrågningar till modellleverantören`},help:{"v1-zj3orj-2i":`Extra headers som slås samman med leverantörsförfrågningar efter att standardattribuering och autentisering har fastställts.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Proxy för förfrågningar till modellleverantören`},help:{"v1-md5uj8-4j":`Valfri åsidosättning av proxyinställningar för förfrågningar till modellleverantörer. Använd "env-proxy" för att följa miljöns proxyinställningar eller "explicit-proxy" för att skicka förfrågningar via en specifik proxy-URL.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Proxyläge för förfrågningar till modellleverantörer`},help:{"v1-1dx0ozg-29":`Läge för åsidosättning av proxyinställningar för förfrågningar till modellleverantörer: "env-proxy" eller "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS för proxy för förfrågningar till modellleverantörer`},help:{"v1-rdx62w-1v":`Valfria TLS-inställningar som används vid anslutning till den konfigurerade proxyn.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`TLS-CA för proxy för förfrågningar till modellleverantörer`},help:{"v1-11pg2fd-1s":`Anpassad CA-certifikatsamling som används för att verifiera proxyns TLS-certifikatkedja.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`TLS-certifikat för proxy för förfrågningar till modellleverantörer`},help:{"v1-x8nk2q-22":`TLS-klientcertifikat som presenteras för proxyn när ömsesidig TLS krävs.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Hoppa över TLS-verifiering för proxy för förfrågningar till modellleverantörer`},help:{"v1-12vjdm9-2j":`Hoppar över verifiering av proxyns TLS-certifikat. Använd endast i kontrollerade utvecklingsmiljöer.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`TLS-nyckel för proxy för förfrågningar till modellleverantörer`},help:{"v1-1skyr56-1w":`Privat nyckel som hör till request.proxy.tls.cert för ömsesidig TLS med proxyn.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`TLS-lösenfras för modellleverantörens förfrågningsproxy`},help:{"v1-wjvoxd-1m":`Valfri lösenfras som används för att dekryptera request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`TLS-servernamn för modellleverantörens förfrågningsproxy`},help:{"v1-b4oabu-22":`Valfritt alternativt SNI/servernamn som används när en TLS-anslutning till proxyn upprättas.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`Proxy-URL för modellleverantörens förfrågningar`},help:{"v1-kvbgou-48":`Explicit proxy-URL som används när request.proxy.mode är explicit-proxy. Autentiseringsuppgifter som är inbäddade i URL:en behandlas som känsliga och maskeras i ögonblicksbilder.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS för modellleverantörens förfrågningar`},help:{"v1-16u7v7h-2b":`Valfria TLS-inställningar som används vid direktanslutning till den överordnade modellens slutpunkt.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`TLS-CA för modellleverantörens förfrågningar`},help:{"v1-ny8y3e-1v":`Anpassad CA-samling som används för att verifiera den överordnade serverns TLS-certifikatkedja.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`TLS-certifikat för modellleverantörens förfrågningar`},help:{"v1-1lltmhw-2e":`TLS-klientcertifikat som presenteras för den överordnade slutpunkten när ömsesidig TLS krävs.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Hoppa över TLS-verifiering för modellleverantörens förfrågningar`},help:{"v1-1006cuy-2m":`Hoppar över verifiering av uppströmsserverns TLS-certifikat. Använd endast i kontrollerade utvecklingsmiljöer.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`TLS-nyckel för förfrågningar till modellleverantören`},help:{"v1-w2agir-1t":`Privat nyckel som hör ihop med request.tls.cert för ömsesidig TLS-autentisering mot uppströmsservern.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`TLS-lösenfras för förfrågningar till modellleverantören`},help:{"v1-10ds42f-1g":`Valfri lösenfras som används för att dekryptera request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`TLS-servernamn för förfrågningar till modellleverantören`},help:{"v1-18yt7x9-1y":`Valfri åsidosättning av SNI/servernamn som används när TLS-anslutningen till uppströmsservern upprättas.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Tidsgräns för förfrågningar till modellleverantören`},help:{"v1-t3yn8l-ih":`Valfri leverantörsspecifik tidsgräns i sekunder för modellförfrågningar. Förfrågningsinställningar på leverantörsnivå påverkar uttryckligen angivna modellposter som tillhör leverantören; de skapar inte implicita modeller. För anpassade leverantörer anger du detta tillsammans med leverantörens baseUrl och models. Gäller leverantörens HTTP-hämtningar, inklusive anslutning, svarshuvuden, svarskropp och hantering av avbrott för hela förfrågan. Höjer även den övre tidsgränsen för övervakning av LLM-inaktivitet och strömning för den här leverantören över det implicita standardvärdet på cirka 120 sekunder. Använd detta för långsamma modellservrar som körs lokalt eller i egen drift, eller för molnleverantörer som buffrar resonemangstoken utan att skicka data över anslutningen (Gemini preview, Claude/Opus med stora verktygsdatamängder), i stället för att ändra globala tidsgränser för agenter.`}},nodeHost:{label:{"v1-nb8lk1-9":`Nodvärd`},help:{"v1-8recuz-4z":`Inställningar för nodvärden som styr vilka funktioner denna gateway-nod exponerar för andra noder eller klienter. Behåll standardvärdena om du inte avsiktligt vill förmedla lokala funktioner via proxy i ditt nodnätverk.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Agentkörningar på noden`},help:{"v1-4uz5ur-2k":`Aktivera inbyggda agentturer som kräver godkännande på denna nodvärd utan grafiskt gränssnitt. Inaktiverat som standard.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Claude-agentkörningar på noden`},help:{"v1-g8az5y-2l":`Styr om denna nodvärd utan grafiskt gränssnitt får annonsera stöd för Claude CLI-agentturer till gatewayen.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Claude-agentkörningar på noden aktiverade`},help:{"v1-1ke804l-44":`Annonsera stöd för att fortsätta Claude-sessioner på en parkopplad nod när den lokala claude-binärfilen är tillgänglig (standard: false). Körningar kräver fortfarande godkännande för kommandokörning på noden.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Automatiska noduppdateringar`},help:{"v1-16xjk4e-5n":`Styr automatiska uppdateringar av den separata körmiljön för paketerade nodvärdar utan grafiskt gränssnitt. Söker efter uppdateringar varje timme och väntar tills allt arbete på noden är klart före omstart. Automatiska omstarter sker med minst 12 timmars mellanrum.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Automatiska noduppdateringar aktiverade`},help:{"v1-1sa0yeg-7w":`Aktivera automatiska uppdateringar till stabila versioner eller betaversioner för paketerade noder som körs under lång tid utan grafiskt gränssnitt (standard: true). Ange false för att avstå. Inaktiveras även av update.checkOnStart=false eller OPENCLAW_NO_AUTO_UPDATE=1. Utcheckad källkod, inbyggda appar, privata arbetare, dev och extended-stable uppdateras inte automatiskt.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Webbläsarproxy på noden`},help:{"v1-2xrew7-4f":`Samlar inställningar för webbläsarproxy som exponerar lokal webbläsarstyrning via nodroutning. Aktivera endast när arbetsflöden på fjärrnoder behöver dina lokala webbläsarprofiler.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Tillåtna profiler för nodens webbläsarproxy`},help:{"v1-1ew5dkm-8b":`Valfri lista över tillåtna webbläsarprofilnamn som exponeras via nodens proxyroutning. Lämna tomt för att behålla standardåtkomsten till alla profilfunktioner, inklusive routning för att skapa och ta bort profiler. När listan anges begränsar OpenClaw profilåtkomsten enligt principen om minsta behörighet och blockerar skapande och borttagning av beständiga profiler via proxyn.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Nodens webbläsarproxy aktiverad`},help:{"v1-pa04pd-5b":`Exponera den lokala servern för webbläsarstyrning via nodens proxyroutning så att fjärrklienter kan använda den här värdens webbläsarfunktioner. Låt vara inaktiverat om inte fjärrautomatisering uttryckligen kräver det.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`Nodvärdens MCP`},help:{"v1-1mdhrwl-48":`Använd MCP-servrar som startas av nodvärden utan grafiskt gränssnitt och publiceras till dess parkopplade gateway som agentverktyg. Starta om nodvärden när du har ändrat det här avsnittet.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Nodvärdens MCP-servrar`},help:{"v1-19m002f-3x":`Namngivna MCP-serverdefinitioner som är lokala för den här noden. Använder samma serverstruktur som mcp.servers; OAuth-servrar stöds inte av nodvärden.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Nodvärdens Skills`},help:{"v1-v8txza-41":`Använd det här avsnittet för att publicera färdigheter installerade i ~/.openclaw/skills från nodvärden utan grafiskt gränssnitt. Starta om nodvärden när du har ändrat färdighetsfiler.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Nodvärdens Skills aktiverade`},help:{"v1-1ggpkqb-36":`Sök efter och publicera färdigheter som finns på noden efter anslutning (standard: true). Ange false för att inaktivera publicering av nodens färdigheter.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Arbetskörningar på noden`},help:{"v1-1w83rox-2p":`Aktivera fullständig drift av OpenClaw-arbetssessioner från paket som hanteras av Gateway. Inaktiverat som standard.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Kapacitet för arbetskörningar på noden`},help:{"v1-10nvk8f-3w":`Maximalt antal samtidiga arbetssessioner som körs på den här noden (standard: antalet tillgängliga CPU-kärnor). Måste vara ett heltal från 1 till 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Containeravbildning för arbetskörningar på noden`},help:{"v1-1tmr1le-5y":`Valfri Node 24.22.1+- eller 26.12.1+-avbildning för containerisolerade arbetare (standard: "node:24.22.1-slim"). Använd vid behov en avbildning som är låst till en digest, finns i ett privat register eller är förinläst; saknade avbildningar hämtas vid första användningen.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Arbetskörningar på noden aktiverade`},help:{"v1-b3t0xp-2t":`Tillåt att den här parkopplade noden kör sessioner från exakt de paket som installerats av dess Gateway (standard: false).`}},"nodeHost%2EworkerRuns%2Efolders":{label:{"v1-1waimc-r":`Mappar för arbetssessioner på noden`},help:{"v1-ald547-9v":`Valfria rotkataloger som begränsar sessioner på plats till dessa kataloger och deras underkataloger. Om värdet inte anges tillåts alla befintliga kataloger utom filsystemets rotkataloger och privat lagring för arbetsprocesser; [] inaktiverar sessioner i enhetens mappar. Använd absoluta sökvägar eller sökvägar med ~/. Befintliga filer stannar på enheten; dessa mappar tas aldrig bort när en session raderas. Kräver workerRuns.enabled.`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Isolering av arbetskörningar på noden`},help:{"v1-19i6swo-58":`Välj processgräns för arbetarsessioner: "none" körs direkt på nodvärden (standard); "container" kräver en fungerande Docker-kompatibel motor och faller aldrig tillbaka på körning på värden.`}},plugins:{label:{"v1-10renyj-7":`Insticksprogram`},help:{"v1-1qbev2k-5c":`Inställningar för insticksprogramsystemet som aktiverar tillägg, begränsar inläsningens omfattning, konfigurerar poster och spårar installationer. Håll policyn för insticksprogram explicit och följ principen om minsta behörighet i produktionsmiljöer.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Tillåtelselista för insticksprogram`},help:{"v1-pupwbe-7z":`Valfri tillåtelselista med insticksprogram-ID:n. När den är angiven kan endast listade insticksprogram läsas in. Konfigurerade medföljande chattkanaler kan fortfarande aktivera sina medföljande insticksprogram när kanalen uttryckligen är aktiverad i konfigurationen. Använd detta för att säkerställa att endast godkända tillägg används i kontrollerade miljöer.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Blockeringslista för insticksprogram`},help:{"v1-4gyt4z-4i":`Valfri blockeringslista med insticksprogram-ID:n som blockeras även om de ingår i tillåtelselistor eller sökvägar. Använd blockeringsregler för akut återställning och ovillkorlig blockering av riskfyllda insticksprogram.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Aktivera insticksprogram`},help:{"v1-pnygd7-50":`Aktivera eller inaktivera inläsning av insticksprogram och tillägg globalt vid start och omläsning av konfigurationen (standard: true). Låt detta vara aktiverat endast när din driftsättning kräver tilläggsfunktioner.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Insticksprogramposter`},help:{"v1-cn74rf-54":`Inställningar per insticksprogram med insticksprogram-ID som nyckel, inklusive aktivering och insticksprogramspecifika konfigurationsdata för körning. Använd detta för att finjustera enskilda insticksprogram utan att ändra den globala inläsningspolicyn.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`API-nyckel för insticksprogram`},help:{"v1-ctytg2-53":`Valfritt API-nyckelfält som används av insticksprogram som stöder direkt nyckelkonfiguration i postens inställningar. Använd substitution med hemligheter eller miljövariabler och undvik att checka in riktiga autentiseringsuppgifter i konfigurationsfiler.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Insticksprogrammets konfiguration`},help:{"v1-1he672p-51":`Konfigurationsdata definierade av insticksprogrammet som tolkas enligt dess eget schema och valideringsregler. Använd endast fält som dokumenteras av insticksprogrammet för att undvika att inställningar ignoreras eller blir ogiltiga.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Insticksprogram aktiverat`},help:{"v1-12soc0h-9a":`Åsidosättning av aktivering för ett enskilt insticksprogram i en specifik post, som tillämpas utöver den globala policyn för insticksprogram. Med standardläget för hybridomladdning laddas insticksprogrammets körmiljö om vid ändringar för nya agentturer utan att Gateway startas om, såvida inte insticksprogrammet kräver en omstart för denna sökväg. Använd detta för att gradvis införa insticksprogram i olika miljöer.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Insticksprogrammets miljövariabler`},help:{"v1-p39pu4-52":`Mappning av miljövariabler per insticksprogram som endast injiceras i det insticksprogrammets körkontext. Använd detta för att begränsa leverantörens autentiseringsuppgifter till ett insticksprogram i stället för att dela processens globala miljö.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Insticksprogrammets hook-policy`},help:{"v1-1oslnrf-4c":`Typade hook-policykontroller per insticksprogram för säkerhetsspärrar som upprätthålls av kärnan. Använd detta för att begränsa hook-kategorier med stor påverkan utan att inaktivera hela insticksprogrammet.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Tillåt hookar med konversationsåtkomst`},help:{"v1-xqz31z-7e":"Styr om detta plugin får läsa rått konversationsinnehåll från typade hookar som `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` och `agent_end`. För plugin som inte ingår måste detta aktiveras uttryckligen."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Tillåt hookar för promptinjektion`},help:{"v1-7y6cny-32":"Styr om detta plugin får ändra promptar via typade hookar. Ange false för att blockera `before_prompt_build`."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Tidsgräns för plugin-hookar (ms)`},help:{"v1-4ra6b7-74":`Standardtidsgräns i millisekunder för detta plugins typade hookar, begränsad till 600000. Om inget anges använder varje hook pluginets deklarerade tidsgräns eller policyn per hook i Gateway; det finns inget gemensamt fast standardvärde. Värden per hook i hooks.timeouts har företräde.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Åsidosättningar av tidsgränser för plugin-hookar`},help:{"v1-yphl9b-5s":`Åsidosättningar av tidsgränser per hook i millisekunder med den typade hookens namn som nyckel, begränsade till 600000. Använd riktade åsidosättningar för hookar som är kända för att vara långsamma, till exempel before_prompt_build eller agent_end, i stället för att höja tidsgränsen för alla hookar.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`LLM-policy för plugin`},help:{"v1-dlca6c-4j":`Inställningar per plugin för api.runtime.llm.complete som styr behörigheten att åsidosätta modell och agent. Lämna detta utan värde om inte ett plugin uttryckligen måste styra värdens kompletteringsanrop.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Tillåt plugin att åsidosätta LLM-agent`},help:{"v1-k8c08b-4n":`Tillåter uttryckligen att detta tillägg anropar api.runtime.llm.complete med ett annat agent-id än standardvärdet. Behåll false om inte tillägget är betrott för modellåtkomst över agentgränser.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Tillåt åsidosättning av autentiseringsprofil för tilläggets LLM`},help:{"v1-9ityw9-4x":`Tillåter att detta tillägg väljer en annan autentiseringsprofil än standardprofilen för textgenerering i en isolerad agentkörningsmiljö. Behåll false om inte tillägget är betrott för uttrycklig, isolerad routning av autentiseringsuppgifter.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Tillåtna modeller för tilläggets LLM-textgenerering`},help:{"v1-1kgxs8j-55":`Tillåtna mål för all LLM-textgenerering från tillägg, som fullständiga "provider/model"-referenser, inklusive standardvärden som värden fastställer och åsidosättningar. Använd "*" endast om du avsiktligt tillåter alla modeller.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Tillåtna modeller för tilläggets LLM`},help:{"v1-h9m5ew-48":`Tillåtna mål för åsidosättning vid betrodda LLM-anrop från tillägg, som fullständiga "provider/model"-referenser. Använd "*" endast om du avsiktligt tillåter åsidosättning med valfri modell.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Tillåt åsidosättning av modell för tilläggets LLM`},help:{"v1-uw4jmc-47":`Tillåter uttryckligen att detta tillägg begär modellåsidosättningar i api.runtime.llm.complete. Behåll false om inte tillägget är betrott för att styra modellvalet.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Policy för tilläggets underagenter`},help:{"v1-wbf4m1-4d":`Körningsinställningar för subagenter per insticksprogram, med behörigheter och tillåtelselistor för modellåsidosättningar. Lämna detta oinställt om inte ett insticksprogram uttryckligen måste styra subagentens modellval.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Tillåtna modeller för insticksprogrammets subagenter`},help:{"v1-hdzz51-43":`Tillåtna modeller vid åsidosättning för betrodda subagentkörningar från insticksprogram, angivna som fullständiga "provider/model"-referenser. Använd "*" endast när du avsiktligt tillåter alla modeller.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Tillåt modellåsidosättning för insticksprogrammets subagenter`},help:{"v1-1r5tzm1-4g":`Tillåter uttryckligen att detta insticksprogram begär åsidosättning av leverantör/modell vid subagentkörningar i bakgrunden. Behåll false om inte insticksprogrammet är betrott att styra modellvalet.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Insticksprograminläsare`},help:{"v1-1myjwbi-52":`Konfigurationsgrupp för insticksprograminläsaren där du anger de sökvägar i filsystemet som genomsöks efter insticksprogram. Använd uttryckligen angivna och granskade inläsningssökvägar för att undvika att obetrodda tillägg läses in av misstag.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Inläsningssökvägar för insticksprogram`},help:{"v1-o689p1-4z":`Ytterligare insticksprogramfiler eller kataloger som inläsaren genomsöker utöver de inbyggda standardplatserna. Använd särskilda tilläggskataloger och undvik breda sökvägar med orelaterat körbart innehåll.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Insticksprogramplatser`},help:{"v1-zx6crl-5f":`Väljer vilka insticksprogram som har exklusiva körningsplatser, till exempel för minne, så att endast ett insticksprogram tillhandahåller den funktionen. Ange uttryckligen vilket insticksprogram som ansvarar för varje plats för att undvika överlappande leverantörer med motstridiga beteenden.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Insticksprogram för kontextmotor`},help:{"v1-4v13iw-2t":`Väljer det aktiva insticksprogrammet för kontextmotorn efter id så att ett insticksprogram sköter kontextorkestreringen.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Minnesinsticksprogram`},help:{"v1-80ngcl-23":`Välj det aktiva minnesinsticksprogrammet efter id, eller "none" för att inaktivera minnesinsticksprogram.`}},presence:{label:{"v1-10fdwo4-8":`Närvaro`}},proxy:{label:{"v1-ji57pa-d":`Hanterad proxy`},help:{"v1-vui6bx-58":`Operatörshanterad routning via framåtproxy för HTTP, HTTPS, WebSocket och stödda vägar för utgående råtrafik i OpenClaws körmiljö. Använd detta när central kontroll av utgående trafik ingår i driftsättningens avgränsning.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Hanterad proxy aktiverad`},help:{"v1-1456xdw-49":`Uttrycklig åsidosättning för hanterad proxy. Om en URL finns aktiveras routning som standard; ange false för att ignorera proxy-URL:er från konfigurationen eller miljön utan att ta bort dem.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Loopback-läge för hanterad proxy`},help:{"v1-1kaiuh0-3c":`Styr routning av Gateway-kontrollplanet via loopback när läget för hanterad proxy är aktivt: "gateway-only", "proxy" eller "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL för hanterad proxy`},help:{"v1-p36b5l-3v":`URL för hanterad framåtproxy. Använd http:// för en vanlig CONNECT-proxy eller https:// när anslutningen till själva proxyslutpunkten måste använda TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS för hanterad proxy`},help:{"v1-6i0vu-3q":`TLS-inställningar som används vid anslutning till den hanterade proxyslutpunkten. Dessa inställningar gäller proxyns TLS, inte destinationens TLS efter CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`CA-fil för hanterad proxys TLS`},help:{"v1-1ntzjia-2p":`Sökväg i filsystemet till ett anpassat CA-paket som används för att verifiera certifikatet för en hanterad HTTPS-proxyslutpunkt.`}},secrets:{label:{"v1-1sihgpy-7":`Hemligheter`},help:{"v1-jgn0o9-2l":`Leverantörer av hemlighetsreferenser, beteende för delad lagring och valfritt skydd för utgående trafik från underprocesser.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Utgående proxy för hemligheter`},help:{"v1-1qfgid-4n":`Loopback-proxy som ägs av Gateway och ersätter markörer för hemligheter i delad lagring först när en utgående begäran skickas. Starta om Gateway efter att du har ändrat det här avsnittet, som läses in vid start.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Tillåtna värdar för utgående proxy för hemligheter`},help:{"v1-9ypodl-6t":`Valfri lista över tillåtna destinationer för begäranden och CONNECT-tunnlar. När den finns måste destinationer finnas i den här listan, i en värdbindning för en enskild hemlighet eller i bypassHosts. En tom lista tillåter endast bundna eller undantagna värdar. Starta om Gateway efter att du har ändrat den.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Undantagna värdar för utgående proxy för hemligheter`},help:{"v1-1oiiomv-57":`Exakta värdnamn som använder autentiserade blinda CONNECT-tunnlar för klienter med certifikatlåsning. Markörerna förblir krypterad text och kommer att nekas vid leverantörens autentisering i stället för att exponera klartext.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Utgående proxy för hemligheter aktiverad`},help:{"v1-u99b1i-2h":`Aktiverar ersättning av hemligheter i utgående trafik för agentunderprocesser som körs i Gateway. Standard: false.`}},session:{label:{"v1-8yh9jr-7":`Session`},help:{"v1-j86s32-5d":`Globala inställningar för sessionsroutning, återställning, leveranspolicy och underhåll som styr hur konversationshistoriken hanteras. Behåll standardinställningarna om du inte behöver striktare isolering, lagringsregler eller leveransbegränsningar.`}},"session%2Ecommunication":{label:{"v1-133tjjf-u":`Standardinställningar för sessionskommunikation`},help:{"v1-1y4eege-63":`Standardinställningar för nya meddelanden mellan sessioner. Varje riktning accepterar always, ask eller never och har always som standard. Sessioner ärver dessa värden tills en människa väljer att åsidosätta dem; befintliga åtkomstbegränsningar gäller fortfarande.`}},"session%2Ecommunication%2Ereceive":{label:{"v1-efg2gh-10":`Ta emot meddelanden från andra sessioner`},help:{"v1-t6w901-5q":`Standardinställning för att ta emot nya meddelanden från andra sessioner: always tillåter, ask kräver godkännande av en människa före inmatning till modellen eller nytt arbete, och never blockerar. Detta ändrar inte historikens synlighet eller människors åtkomst.`}},"session%2Ecommunication%2Esend":{label:{"v1-1chq2bl-v":`Skicka meddelanden till andra sessioner`},help:{"v1-92cfz7-65":`Standardinställning för att initiera meddelanden till andra sessioner: always tillåter, ask kräver godkännande av en människa före sändning, och never blockerar. Begärda svar och godkänd kommunikation om delegerade uppgifter behåller sina befintliga behörigheter.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Sessionsomfång för direktmeddelanden`},help:{"v1-ql362c-5l":`Avgränsning av sessioner för direktmeddelanden: "main" bevarar kontinuiteten, medan "per-peer", "per-channel-peer" och "per-account-channel-peer" ökar isoleringen. Använd isolerade lägen för delade inkorgar eller driftsättningar med flera konton.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Sessionsomfång för grupper`},help:{"v1-1fdezx2-6i":`Avgränsning av grupp- och kanalsessioner: "per-group" håller rum åtskilda medan agentens huvudsession bevakar dem i bakgrunden, oberoende av dmScope; "main" sammanför rumskontexten med huvudsessionen och kräver ingen bevakning. Använd "main" endast för betrodda rum.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Identitetskopplingar för sessioner`},help:{"v1-4mwmyr-5k":`Kopplar gemensamma identiteter till motparts-ID:n med leverantörsprefix så att samma användare samlas i en enda DM-tråd (exempel: telegram:123456). Använd detta när samma person förekommer i flera kanaler eller konton.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Huvudnyckel för session`},help:{"v1-18p638h-3q":`Accepteras men ignoreras: suffixet för varje agents huvudsession är alltid "main". Utelämna detta fält; global sessionsomfattning använder "global" i stället.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Sessionsunderhåll`},help:{"v1-imr441-66":`Inställningar för automatiskt underhåll av sessionslagret: arkivering av panelsessioner, åldersgräns för rensning, högsta antal poster, lagringstid för återställningsarkiv och rensning utifrån diskutrymmesbudget. Börja i läget warn för att se effekten och växla sedan till enforce när tröskelvärdena har justerats.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Arkivera inaktiva panelsessioner efter`},help:{"v1-1frdtub-5n":"Arkiverar inaktiva panelsessioner efter denna tidsperiod (till exempel `7d`) så att de förblir tillgängliga utan att fylla listan över aktiva sessioner. Ange `false` eller `0` för att inaktivera automatisk arkivering av panelsessioner."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Kallagring av transkript`},help:{"v1-1kp9s9h-5s":`Flyttar inaktiva transkript till komprimerade JSONL-arkiv och behåller sessionernas metadata. Arkivfilerna blir en nödvändig del av historiken och måste ingå i säkerhetskopior. Ändringar tillämpas utan att Gateway startas om.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Arkivera efter antal inaktiva dagar`},help:{"v1-zay1q3-5b":`Arkivera transkriptioner efter så här många inaktiva dagar (positivt heltal, standardvärde 30). Aktivt arbete skyddas; en ändrad tidsgräns börjar gälla vid nästa bakgrundskörning utan att Gateway behöver startas om.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Arkivera gamla transkriptioner automatiskt`},help:{"v1-6p6vmb-5a":`Aktiverar arkivering av transkriptioner i bakgrunden (standardvärde false). En bakgrundsprocess söker varje minut efter transkriptioner som kan arkiveras. Denna uttryckliga arkiveringspolicy är separat från radering och rensning för att hålla diskbudgeten.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Övre målnivå för sessioners diskanvändning`},help:{"v1-143vh09-7z":`Målstorlek efter rensning för att hålla diskbudgeten (övre målnivå). Standardvärdet är 80 % av maxDiskBytes; ange ett explicit värde för mer omfattande frigöring av utrymme på diskar med begränsad kapacitet. Ett värde som beräknas till noll återgår till standardvärdet; negativa värden är ogiltiga. Inaktivera budgeten med maxDiskBytes i stället.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Maximal diskbudget för sessioner`},help:{"v1-147lxk3-cj":'Fysisk diskbudget per agent som omfattar SQLite-huvuddatabasen/WAL och medräknade artefakter i sessionskatalogen (till exempel `500mb`). Standardvärdet är `10gb`; skyddade data kan hålla användningen över målnivån. När budgeten överskrids rapporterar läget warn utrymmesbrist, medan läget enforce tar bort gamla artefakter från återställning/radering, historik utan referenser och därefter arkiv som skapats på grund av storleksgränsen. Manuella arkiv, arkiv från åldersbaserad lagring, kontrollpanelen och återställning samt äldre arkiv förblir skyddade. Ange `false`, `0` eller `"0"` för att inaktivera.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Maximalt antal sessionsposter`},help:{"v1-1w2egrh-7u":`Begränsar antalet oarkiverade sessionsposter (standard 5000). Varaktiga konversationer som överskrider gränsen och får arkiveras arkiveras med sin historik; tillfälliga automatiseringsposter tas bort. Befintliga arkiv räknas inte mot gränsen. Skyddade aktiva poster räknas fortfarande och kan hålla lagringen över gränsen.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Läge för sessionsunderhåll`},help:{"v1-bq39hk-6v":`Avgör om policyer för rensning och diskutrymmesbudget endast rapporteras ("warn") eller tillämpas aktivt ("enforce"). Behåll "warn" under utrullningen och byt till "enforce" efter att säkra tröskelvärden har validerats. Kallagring har en egen uttrycklig inställning för aktivering.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Bevara nyligen aktiva sessioner`},help:{"v1-138q5wx-89":"Skyddar interaktiva sessioner som varit aktiva under denna tidsperiod (till exempel `7d`) från automatisk borttagning av historik baserat på ålder, antal och diskutrymmesbudget. Om värdet inte anges eller är `false` behålls den vanliga policyn där de äldsta tas bort först. Syntetiska rader för modellkörningar, cron, hook, heartbeat, ACP och underagenter kan fortfarande omfattas av begränsad rensning."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Rensa sessioner efter`},help:{"v1-1xn50w7-76":"Arkiverar varaktiga konversationer som får arkiveras och tar bort tillfälliga automatiseringsposter som är äldre än denna tidsperiod (standard `30d`; till exempel `12h`). Arkiverade konversationer behåller sin historik och kan återställas; skyddade eller routningsbara konversationer förblir aktiva."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Bevarandetid för arkiv vid sessionsåterställning`},help:{"v1-16amrs1-7r":"Åldersbaserad lagring av arkiverade konversationsloggar (`*.reset.<timestamp>` och `*.deleted.<timestamp>`). Som standard behålls arkiven tills diskutrymmesgränsen gör att de äldsta tas bort först. Ange en tidsperiod (till exempel `30d`) för att aktivera tidsbaserad radering, eller `false` för att uttryckligen inaktivera den."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Meddela Home när en session skapas`},help:{"v1-c4prn5-8b":`Köa ett systemmeddelande i den ansvariga agentens Home-session när en session skapas (standard: true). Meddelandena innehåller tillgänglig titel och metadata om skaparen och läses vid nästa Home-tur eller livstecken. Ange false för att inaktivera. Utkast, inkognitosessioner, interna sessioner och schemalagda cron-körningar undantas.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Policy för sessionsåterställning`},help:{"v1-1hmt7n3-6r":`Definierar standardobjektet för återställningspolicyn som används när ingen typ- eller kanalspecifik inställning åsidosätter den. Som standard återställs sessioner inte automatiskt. Aktivera detta med dagliga eller inaktivitetsbaserade scheman. /new och /reset är alltid tillgängliga.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Timme för daglig sessionsåterställning`},help:{"v1-wry8cv-59":`Anger timmen i lokal tid (0–23) för daglig återställning så att sessioner förnyas vid förutsägbara tidpunkter. Använd med mode=daily och anpassa till operatörens förväntade tidszon för ett lättbegripligt beteende.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Minuter av inaktivitet före sessionsåterställning`},help:{"v1-1kzj0id-5e":`Anger hur länge en session får vara inaktiv före återställning i inaktivitetsläget och kan även fungera som ett extra villkor i det dagliga läget. Använd högre värden för att bevara kontinuiteten eller lägre värden för nyare, kortlivade trådar.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Läge för sessionsåterställning`},help:{"v1-e5ie4w-5b":`Väljer återställningsstrategi: "none" inaktiverar automatisk återställning (standard), "daily" återställer vid en konfigurerad tidpunkt och "idle" återställer efter inaktivitet. /new och /reset är tillgängliga i alla lägen.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Sessionsåterställning per kanal`},help:{"v1-1uxsulx-5h":`Anger kanalspecifika åsidosättningar av återställningsinställningar med leverantörs-/kanal-id som nyckel för detaljerad styrning av beteendet. Använd detta endast när en kanal behöver ett särskilt återställningsbeteende utöver policyerna på typnivå.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Sessionsåterställning per chattyp`},help:{"v1-ypdr7u-52":`Åsidosätter återställningsbeteendet per chattyp (direkt, grupp, tråd) när standardinställningarna inte räcker till. Använd detta när grupp- eller trådtrafik behöver en annan återställningsfrekvens än direktmeddelanden.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Sessionsåterställning (direkt)`},help:{"v1-22e702-54":`Definierar återställningspolicyn för direktchattar och åsidosätter grundkonfigurationen session.reset för den typen. Använd detta som den aktuella åsidosättningen för direktmeddelanden i stället för det äldre aliaset dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Sessionsåterställning (grupp)`},help:{"v1-hl1200-4u":`Definierar återställningspolicyn för gruppchattsessioner där kontinuitet och brusmönster skiljer sig från direktmeddelanden. Använd kortare inaktivitetsperioder för aktiva grupper om kontextförskjutning blir ett problem.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Sessionsåterställning (tråd)`},help:{"v1-1hgpeke-4w":`Definierar återställningspolicyn för trådavgränsade sessioner, inklusive fokuserade arbetsflöden i kanaltrådar. Använd detta när trådsessioner ska löpa ut snabbare eller långsammare än andra chattyper.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Utlösare för sessionsåterställning`},help:{"v1-rcabsw-5a":`Listar meddelandeutlösare som tvingar fram en sessionsåterställning när de matchas i inkommande innehåll. Använd sparsamt för uttryckliga återställningsfraser så att kontext inte förloras oväntat under vanliga samtal.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Sessionsomfattning`},help:{"v1-axt4ds-5z":`Anger grundstrategin för sessionsgruppering: "per-sender" separerar efter avsändare och "global" delar en session per kanalkontext. Behåll "per-sender" för säkrare beteende med flera användare, om inte delad kontext uttryckligen krävs.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Sändningspolicy för sessioner`},help:{"v1-17zdvww-61":`Styr sessionsleverans med regler för att tillåta eller neka som utvärderas mot channel, chatType och nyckelprefix. Detta är separat från tillåtelse för inkommande och utgående meddelanden mellan parter; använd session.communication för dessa standardinställningar.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Standardåtgärd för sessioners sändningspolicy`},help:{"v1-15plhut-53":`Anger reservåtgärden när ingen sendPolicy-regel matchar: "allow" eller "deny". Behåll "allow" för enklare konfigurationer, eller välj "deny" när du kräver uttryckliga tillåtelseregler för varje destination.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Regler för sessioners sändningspolicy`},help:{"v1-o217za-5h":'Ordnade regler för att tillåta eller neka som utvärderas före standardåtgärden, till exempel `{ action: "deny", match: { channel: "discord" } }`. Placera de mest specifika reglerna först så att breda regler inte åsidosätter undantag.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Åtgärd för sessionens sändningsregel`},help:{"v1-178vm80-54":`Anger regelns beslut som "allow" eller "deny" när motsvarande matchningsvillkor är uppfyllda. Placera nekande regler först när strikta gränser ska upprätthållas med uttryckliga undantag som tillåter sändning.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Matchning för sessionens sändningsregel`},help:{"v1-18qh5qg-5d":`Anger valfria matchningsvillkor för regeln som kan kombinera begränsningar för channel, chatType och nyckelprefix. Håll matchningarna snäva så att policyns syfte förblir tydligt och felsökningen enkel.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Kanal för sessionens sändningsregel`},help:{"v1-u5erwx-50":`Begränsar regelns tillämpning till ett specifikt kanal- eller leverantörs-id (till exempel discord, telegram, slack). Använd detta när en kanal ska tillåta eller neka leverans oberoende av andra.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Chattyp för sessionens sändningsregel`},help:{"v1-7cv4f9-4z":`Begränsar regelns tillämpning efter chattyp (direct, group, thread) så att beteendet varierar med samtalsformen. Använd detta när direktmeddelanden och gruppdestinationer kräver olika säkerhetsgränser.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Nyckelprefix för sessionens sändningsregel`},help:{"v1-ac4dee-5n":`Matchar ett normaliserat sessionsnyckelprefix efter interna nyckelnormaliseringssteg i komponenter som tillämpar policyn. Använd detta för allmänna prefixbegränsningar och välj hellre rawKeyPrefix när exakt matchning mot hela nyckeln krävs.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Rått nyckelprefix för sessionens sändningsregel`},help:{"v1-1g9w044-5e":`Matchar det råa, onormaliserade sessionsnyckelprefixet för exakt policystyrning utifrån hela nyckeln. Använd detta när normaliserat keyPrefix är för brett och du behöver precision med agentprefix eller för en specifik transport.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Lägen för sessionsdelning`},help:{"v1-xbh52d-5a":`Styr vilka samarbetslägen sessionsägare och administratörer får välja. Utelämnade booleska värden är aktiverade som standard. Sätt ett läge till false för att ta bort det från väljaren och avvisa nya val.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Tillåt utkastsessioner`},help:{"v1-1lzap27-2p":`Tillåter synlighetsläget utkast, som döljer sessioner för operatörer som varken är ägare eller administratörer. Standard: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Tillåt skrivskyddade sessioner`},help:{"v1-upl3nu-21":`Tillåter att sessioner görs skrivskyddade för personer som inte deltar. Standard: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Tillåt sessioner med förslagsläge`},help:{"v1-4i8owu-4g":`Tillåter synlighetsläget förslag. I denna fas tillämpas samma åtkomstpolicy som för skrivskyddade sessioner. Förslagsköer konfigureras via en senare funktion. Standard: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Sökväg för sessionslagring`},help:{"v1-hreznz-56":`Anger sökvägen till sessionslagringsfilen som används för att bevara sessionsposter mellan omstarter. Använd en explicit sökväg endast när du behöver en anpassad diskstruktur, styrning av säkerhetskopiering eller lagring på en monterad volym.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Trådbindningar för sessioner`},help:{"v1-zbzihu-4s":`Gemensamma standardinställningar för att skapa och dirigera trådbundna sessioner i kanaler som stöds. Konfigurera globala standardinställningar här och åsidosätt dem per kanal endast när beteendet skiljer sig åt.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Kontext vid skapande i tråd`},help:{"v1-1set6nw-4c":`Standardkontext för inbyggda underagenter vid trådbundet skapande. Använd "fork" för att utgå från begärarens konversationshistorik eller "isolated" för en underagent utan tidigare kontext. Standard: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Trådbindning aktiverad`},help:{"v1-foomtc-3f":`Global huvudinställning för att skapa och dirigera trådbundna sessioner samt leverera till dem. Inaktivera för att stänga av trådbindning globalt.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Inaktivitetstidsgräns för trådbindning (timmar)`},help:{"v1-gffnx3-3h":`Standardtidsgräns för inaktivitet i timmar för trådbundna sessioner hos leverantörer och i kanaler (0 inaktiverar utgång vid inaktivitet). Standard: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Maximal ålder för trådbindning (timmar)`},help:{"v1-1xfcyhw-39":`Valfri absolut maxålder i timmar för trådbundna sessioner hos leverantörer och i kanaler (0 inaktiverar den absoluta gränsen). Standard: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Skapande av trådbundna sessioner`},help:{"v1-1lqwbdl-46":`Global standardinställning som styr om trådbundna arbetssessioner får skapas via sessions_spawn och ACP-trådskapande. Standard: true när trådbindningar är aktiverade.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Tillåtna mål för symboliska länkar för färdigheter`},help:{"v1-xzybiq-4t":`Betrodda faktiska målrotkataloger som symboliska länkar för färdigheter får peka på när målen ligger utanför den konfigurerade källrotkatalogen. Begränsa detta till exempelvis en katalog för färdigheter i ett närliggande repo.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Extra kataloger för färdigheter`},help:{"v1-11o7opu-53":`Ytterligare delade rotkataloger för färdigheter som ska genomsökas med lägst prioritet. Använd detta för närliggande repon eller delade färdighetspaket som ska vara tillgängliga utan att kopieras till OpenClaw-arbetsytan.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Bevaka Skills`},help:{"v1-ga69fo-7s":`Aktivera passiva omsökningar efter färdigheter i en enda bakgrundsprocess ungefär en gång per minut. Även om detta inaktiveras uppdateras färdigheter omedelbart vid uttryckliga ändringar av färdigheter i OpenClaw, relevanta konfigurationsändringar och när Gateway startas. Befintliga sessioner använder ändrade ögonblicksbilder vid nästa agenttur.`}},"skills%2Eworkshop%2Eautonomous%2EchannelNotices":{label:{"v1-eykx91-u":`Kanalaviseringar för Skill Workshop`},help:{"v1-ge0p9d-7f":`Publicera aviseringar om bakgrundsgranskning i kanalkonversationer, utom i Slack, med en Ångra-knapp (standard: false); Control UI visar meddelandet som vanlig text. När detta är inaktiverat visas aviseringar endast på raden Inlärt i chatten i Control UI. Att säga "undo" fungerar i båda fallen.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Autonomt läge för Skill Workshop`},help:{"v1-1ofyff7-6s":`Styr bakgrundsinlärning: "auto" låter agenter spara och uppdatera Workshop-färdigheter efter omfattande arbete och arkiverar inlärda färdigheter som inte har använts på 30 dagar. Varje ändring registreras och kan ångras. "off" inaktiverar bakgrundsinlärning. Standard: "auto".`}},storage:{label:{"v1-eop0jq-7":`Lagring`},help:{"v1-j0mwbg-4w":`Återanvändbara lagringsplatser för OpenClaw-artefakter. Kärnlagringen ansvarar för platsidentitet, kryptering och hälsostatus; leverantörer transporterar objekt och konsumenter avgör vad som ska behållas.`}},"storage%2Elocations":{label:{"v1-uok3ae-h":`Lagringsplatser`},help:{"v1-1ipmwky-5k":`Namngivna lagringsmål. Namn innehåller 1–63 gemener, siffror eller bindestreck och börjar med en bokstav eller siffra. Varje mål har en initieringsmarkör som aldrig skapas av skrivningar under körning.`}},"storage%2Elocations%2E*":{label:{"v1-1pbn8xd-g":`Lagringsplats`},help:{"v1-7yhxyl-4n":`Ett namngivet lagringsmål med leverantörsinställningar och ett uttryckligt krypteringsval. Initiera ett nytt mål med openclaw storage init innan du skriver objekt.`}},"storage%2Elocations%2E*%2Eencryption":{label:{"v1-1qp46kf-i":`Lagringskryptering`},help:{"v1-19oj6cx-6d":`Obligatoriskt krypteringsval: ett lösenfrasobjekt krypterar objekt före uppladdning; "none" inaktiverar uttryckligen kryptering. Säkerhetskopior kan innehålla inloggningsuppgifter, så använd "none" endast när målet redan ger lämpligt skydd.`}},"storage%2Elocations%2E*%2Eencryption%2Epassphrase":{label:{"v1-1x3jq0t-t":`Lösenfras för lagringskryptering`},help:{"v1-1o63v7d-4o":`Lösenfras som används för att kryptera denna plats. Använd helst en SecretRef och behåll en kopia som går att återställa: om lösenfrasen förloras eller ändras blir befintliga krypterade objekt oläsbara.`}},"storage%2Elocations%2E*%2Eprovider":{label:{"v1-1dujppr-g":`Lagringsleverantör`},help:{"v1-16srbor-3w":`Lagringsleverantörens id, till exempel "filesystem". Om du refererar till en medföljande leverantör aktiveras dess insticksmodul automatiskt, såvida inte policyn för insticksmoduler inaktiverar den.`}},"storage%2Elocations%2E*%2Esettings":{label:{"v1-268wio-p":`Inställningar för lagringsleverantör`},help:{"v1-drbso5-5t":`Avgränsade JSON-inställningar som hanteras av leverantören. Värden som innehåller hemligheter måste använda SecretRef-objekt, som leverantören löser upp endast vid behov. Filsystemsleverantören kräver en absolut sökväg till en befintlig katalog.`}},surfaces:{label:{"v1-exl2ye-g":`Policyer för ytor`},help:{"v1-vgtjbs-50":`Åsidosättningar av meddelandepolicy per yta, med den identifierade leveransytans id som nyckel. Använd detta endast när en driftsatt yta behöver striktare hantering av tysta svar än agentens standard.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Policy för tysta svar på ytan`},help:{"v1-1un880p-4z":`Åsidosätter gruppens policy för tysta svar för en identifierad leveransyta. Fält som inte har angetts ärver agents.defaults.silentReply. Direktchattar och interna sessioner kräver alltid ett svar.`}},talk:{label:{"v1-15ukbjj-4":`Talk`},help:{"v1-1gx10xa-5g":`Inställningar för talsyntes i Talk-läget för röstidentitet, modellval, utdataformat och avbrottsbeteende. Använd det här avsnittet för att anpassa användarnas röstupplevelse samtidigt som du håller svarstider och kostnader under kontroll.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Talk-agent`},help:{"v1-iee5l9-2b":`Agent som äger Talk-sessioner som skapats utan en uttrycklig agentspecifik sessionsnyckel.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Snabbläge för Talk-konsultationer`},help:{"v1-syf3xk-2o":`Använd detta för att ange true eller false för snabbläget i den vanliga agentkörningen bakom Talk-konsultationer i realtid.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Resonemangsnivå för Talk-konsultationer`},help:{"v1-1ft5njw-2o":`Använd detta för att åsidosätta resonemangsnivån för den vanliga agentkörningen bakom Talk-konsultationer i realtid.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Avbryt vid tal i Talk`},help:{"v1-8n9q4o-3l":`Om true (standardvärde) stoppas assistentens tal när användaren börjar prata i Talk-läge. Behåll aktiverat för naturlig turtagning i samtal.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Aktiv leverantör för Talk`},help:{"v1-wgnxhg-1g":`ID för den aktiva Talk-leverantören (till exempel "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Leverantörsinställningar för Talk`},help:{"v1-oh0yuv-30":`Leverantörsspecifika Talk-inställningar med leverantörs-ID som nyckel. Använd helst dessa i stället för äldre talk.*-nycklar vid migrering.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Leverantörskonfiguration för Talk`},help:{"v1-36pblg-1r":`Leverantörens egna konfigurationsfält för Talk för motsvarande leverantörs-ID.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Leverantörens API-nyckel för Talk`},help:{"v1-1a1p9wp-v":`Leverantörens API-nyckel för Talk-läge.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk i realtid`},help:{"v1-c2re7j-3z":`Leverantör, modell, röst, läge, transport och resonemangsstrategi för Talk i realtid. Behåll leverantörskonfigurationen för tal/TTS i talk.provider och talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Resonemangsstrategi för Talk i realtid`},help:{"v1-opsatw-37":`Resonemangsstrategi för Talk: agent-consult för agenthjälp via Gateway, direct-tools för lokala verktygsanrop eller none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Konsultationsroutning för Talk i realtid`},help:{"v1-10qjcvk-5f":`Reservlösning för vidarebefordran via Gateway av slutliga transkriptioner av användarens tal när realtidsleverantören hoppar över openclaw_agent_consult. provider-direct bevarar leverantörens svar; force-agent-consult dirigerar via OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Realtidsinstruktioner för Talk`},help:{"v1-1jaaj84-5p":`Ytterligare systeminstruktioner som läggs till i OpenClaws inbyggda realtidsprompt för Talk. Använd detta för röststil, ton och annat leverantörsinriktat realtidsbeteende utan att ändra vägledningen för agentkonsultation.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Realtidsläge för Talk`},help:{"v1-1u2xui1-1l":`Körläge för Talk: realtime, stt-tts eller transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Realtidsmodell för Talk`},help:{"v1-amou5a-27":`Åsidosättning av realtidsleverantörens modell-id för Talk-sessioner i webbläsaren eller som ägs av Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Inledande ljudmarginal för Talk i realtid (ms)`},help:{"v1-1cwg07n-22":`Antal millisekunder ljud som behålls före detekterad röstaktivitet i realtid.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Realtidsleverantör för Talk`},help:{"v1-wwsmpt-1o":`Id för den aktiva leverantören av röst i realtid, till exempel openai eller google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Inställningar för realtidsleverantörer för Talk`},help:{"v1-ruagcu-1r":`Leverantörsspecifika inställningar för röst i realtid med leverantörs-id som nyckel.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Konfiguration av realtidsleverantör för Talk`},help:{"v1-edfpxm-1u":`Leverantörsägd konfiguration för röst i realtid för motsvarande leverantörs-id.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`API-nyckel för realtidsleverantör för Talk`},help:{"v1-1fbmgpx-z":`Leverantörens API-nyckel för Talk i realtid.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Resonemangsnivå för Talk i realtid`},help:{"v1-157xd3e-2t":`Leverantörsspecifik resonemangsnivå för Talk-sessioner i realtid, till exempel minimal, låg, medel eller hög.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Tystnadsvaraktighet för Talk i realtid (ms)`},help:{"v1-1grnu06-1y":`Antal millisekunder av tystnad innan användarens taltur i Talk i realtid slutförs.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Talarröst för Talk i realtid`},help:{"v1-1kgb166-2h":`Åsidosätter namnet på realtidsleverantörens talarröst för Talk-sessioner i webbläsaren eller som ägs av Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Talarröst-ID för Talk i realtid`},help:{"v1-1k8w6vk-2f":`Åsidosätter ID:t för realtidsleverantörens talarröst för Talk-sessioner i webbläsaren eller som ägs av Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Transport för Talk i realtid`},help:{"v1-2otjgn-2g":`Byte-/sessionstransport för Talk: webrtc, provider-websocket, gateway-relay eller managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`VAD-tröskel för Talk i realtid`},help:{"v1-nf5l2t-2j":`Tröskel för detektering av röstaktivitet i realtid, från 0 (mest känslig) till 1 (minst känslig).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Tidsgräns för tystnad i Talk (ms)`},help:{"v1-1kim32f-59":`Antal millisekunder som användaren är tyst innan Talk-läget slutför och skickar den aktuella transkriptionen. Lämna värdet oangivet för att behålla plattformens standardlängd för pauser (700 ms på macOS och Android, 900 ms på iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Språk- och regioninställning för tal i Talk`},help:{"v1-1un3x4l-4c":`Språk- och regionkod enligt BCP 47 för taligenkänning i Talk på enhetsnoder och iOS-systemrösten som reservalternativ, till exempel "ru-RU". Lämna utan värde för att använda varje enhets standardinställning.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetri`},help:{"v1-1o5tru3-55":`Uttryckligt samtycke till anonym funktionsstatistik som skickas med den dagliga uppdateringskontrollen. Funktionsstatistik är inaktiverad som standard och innehåller aldrig meddelanden, autentiseringsuppgifter eller identifierare.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Tidsstämpel för samtycke till funktionsstatistik`},help:{"v1-1t051az-3t":`ISO-tidsstämpel som anger när operatören godkände eller avböjde anonym funktionsstatistik. Förhindrar att installationsguiden frågar igen.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Anonym funktionsstatistik`},help:{"v1-1ptrwuq-4r":`Delar namn på aktiverade kanaler och leverantörer, antal insticksprogram och antal senaste sessioner vid den dagliga uppdateringskontrollen. Inaktiverad som standard och alltid inaktiverad när DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Verktyg`},help:{"v1-1el54kl-5h":`Verktygsinfrastruktur och standardinställningar som gäller över agentgränser. Syskon på rotnivå ansvarar för infrastruktur och standardinställningar över agentgränser; agents.defaults ansvarar för agentloopens beteende; agentposter kan åsidosätta båda där det stöds.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Verktygsåtkomst mellan agenter`},help:{"v1-1ynpa5f-cf":`Policy för sessionsverktygsanrop över agentgränser: sändning, listning, historik, sökning och statusavläsning (standard: aktiverad). Använd allow för att begränsa agentpar; enabled=false blockerar vanlig åtkomst över agentgränser. Inbyggda underagentsessioner och ACP-barnsessioner som ägs av den anropande agenten förblir åtkomliga med synligheten tree eller all. För strikt åtskillnad, ställ in tools.sessions.visibility på agent eller self (tree tillåter fortfarande inbyggda underagenter och ACP-barn som ägs av den anropande agenten), eller använd separata gateways.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Lista över tillåtna målagenter för anrop mellan agenter`},help:{"v1-1jt2ari-76":`Agent-id:n eller *-mönster som får delta i anrop mellan agenter; både den begärande agenten och målagenten måste matcha. Åtkomst mellan agenter är aktiverad som standard, och om allow utelämnas eller är tom tillåts alla par. Ange en uttrycklig lista för att begränsa åtkomsten; tomma poster nekar åtkomst.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Aktivera verktyget för anrop mellan agenter`},help:{"v1-w950oq-ba":`Aktiverar åtkomst till sessionsverktyg mellan agenter (standard: true); om allow utelämnas eller är tom tillåts alla agentpar. Ange false för att blockera vanlig åtkomst mellan agenter; inbyggda underagentsessioner och underordnade ACP-sessioner som ägs av den begärande agenten förblir åtkomliga med synligheten tree eller all. För strikt separation anger du agent eller self för tools.sessions.visibility (tree tillåter fortfarande inbyggda underagentsessioner och underordnade ACP-sessioner som ägs av den begärande agenten), eller använder separata gateways.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Lista över tillåtna verktyg`},help:{"v1-1is3eaq-4v":`Absolut lista över tillåtna verktyg som ersätter profilbaserade standardinställningar för strikta miljöer. Använd endast detta när du avsiktligt använder en noggrant utvald delmängd av verktygsfunktionerna.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Tillägg till listan över tillåtna verktyg`},help:{"v1-1xw9zp8-57":`Extra poster i listan över tillåtna verktyg som läggs till utöver den valda verktygsprofilen och standardpolicyn. Håll listan kort och tydlig så att avsiktliga undantag från policyn snabbt kan identifieras vid granskning.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Verktygspolicy per leverantör`},help:{"v1-1ecljob-4y":`Leverantörsspecifika undantag som tillåter eller nekar verktyg, med kanal-/leverantörs-id som nyckel, för att anpassa funktioner per gränssnitt. Använd detta när en leverantör behöver striktare kontroller än den globala verktygspolicyn.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Kodläge`},help:{"v1-1ecc39k-6k":'Generellt kodläge i OpenClaw. Om inställningen utelämnas globalt används `"auto"` som standard; ett angivet objekt utan `enabled` förblir avstängt. Agentkörningar med kodläget aktiverat exponerar endast `exec` och `wait` för modellen och får åtkomst till vanliga verktyg via katalogbryggan.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Aktivera kodläge`},help:{"v1-c7oqjw-ah":'Global aktivering av kodläge i OpenClaw. Om den globala inställningen saknas helt används `"auto"` som standard; ett angivet objekt utan `enabled` förblir avstängt. `"auto"` aktiverar läget för modeller som föredrar katalogen, medan `true` aktiverar det för körningar med verktygsstöd. Åsidosättningar av aktiveringen på agent- och modellnivå har företräde. En körning med läget aktiverat blockeras om körmiljön inte är tillgänglig, i stället för att hela verktygslistan exponeras.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Exekverare för kodläge`},help:{"v1-4tbmdg-7h":`JavaScript-exekverare: "node" (standard) använder Node vm för betrodd kod och är inte en säkerhetssandlåda; "quickjs" använder det medföljande QuickJS WASM-tillägget för härdad gästexekvering. Verktygsbehörigheter gäller för båda. Kodläget kan inte köras om den valda exekveraren inte är tillgänglig.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Utdatagräns för kodläge`},help:{"v1-1hmij9q-1n":`Maximalt antal serialiserade byte som returneras via kodlägets utdata.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Gräns för väntande verktygsanrop i kodläge`},help:{"v1-3b5tyd-2i":`Maximalt antal samtidiga nästlade verktygsanrop som en virtuell maskin i kodläge kan starta innan den måste återuppta körningen senare.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Maximalt antal sökresultat i kodläge`},help:{"v1-1gpue5r-28":`Maximalt antal dolda katalogsökresultat som ett program i kodläge kan begära.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Gräns för ögonblicksbilder i kodläge`},help:{"v1-1mmgkqy-1x":`Maximalt antal serialiserade byte som sparas för en pausad QuickJS-ögonblicksbild.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Minnesgräns för kodläge`},help:{"v1-xetora-6n":`Gräns för QuickJS-gästens heap eller eftersträvad V8-heapbudget för Node-arbetstråden i byte. Overhead i Node-körmiljön och motorns minsta allokeringar påverkar den faktiska budgeten; externa buffertar och processens RSS ingår inte. Detta är ingen säkerhetsgaranti.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Gränssnitt för kodläge`},help:{"v1-dsp2b9-2x":'Gränssnitt mot modellen. Endast "only" stöds: exponera kodlägets `exec` och `wait` och dölj vanliga verktyg.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Standardantal sökresultat i kodläge`},help:{"v1-1io42lu-2m":"Standardantal sökresultat från den dolda katalogen som returneras av `catalog.search` i kodläge."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`TTL för ögonblicksbilder i kodläge`},help:{"v1-1nxfczz-28":"Hur länge pausade körningar i kodläge kan återupptas med `wait` innan de upphör att gälla."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Tidsgräns för kodläge`},help:{"v1-8csycm-1p":"Maximalt antal millisekunder för ett `exec`- eller `wait`-anrop i kodläge."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Spärrlista för verktyg`},help:{"v1-wilr1b-4p":`Global spärrlista för verktyg som blockerar angivna verktyg även när profil- eller leverantörsregler skulle tillåta dem. Använd spärrregler för akuta avstängningar och långsiktigt skydd i flera lager.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Verktygsåtkomst med förhöjda behörigheter`},help:{"v1-ehcm0r-5a":`Åtkomstkontroller för verktyg med utökade behörigheter för privilegierade kommandogränssnitt som endast ska vara tillgängliga för betrodda avsändare. Låt vara inaktiverat om inte operatörens arbetsflöden uttryckligen kräver åtgärder med utökade behörigheter.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Tillåtelseregler för verktyg med utökade behörigheter`},help:{"v1-1u9bhih-54":`Regler för vilka avsändare som tillåts använda verktyg med utökade behörigheter, vanligtvis med nycklar enligt kanalens eller leverantörens identitetsformat. Använd snävt avgränsade, uttryckliga identiteter så att kommandon med utökade behörigheter inte kan utlösas av obehöriga användare.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Aktivera verktygsåtkomst med utökade behörigheter`},help:{"v1-1n8oyal-4l":`Aktiverar verktygskörning med utökade behörigheter när avsändar- och policykontroller godkänns. Låt vara inaktiverat i offentliga eller delade kanaler och aktivera endast i betrodda miljöer som drivs av ägaren.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Exec-verktyg`},help:{"v1-p5piic-56":`Policygrupp för Exec-verktygets värd för skalkörning, säkerhetsläge, godkännandebeteende och bindningar vid körning. Behåll restriktiva standardinställningar i produktion och begränsa körningsvägar med utökade behörigheter.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Tillåtelselista för modeller för apply_patch`},help:{"v1-4q5ovf-1x":`Valfri tillåtelselista med modell-id:n (t.ex. "gpt-5.4" eller "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Aktivera apply_patch`},help:{"v1-1erkir4-31":`Aktivera eller inaktivera apply_patch för OpenAI- och OpenAI Codex-modeller när verktygspolicyn tillåter det (standard: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`Begränsa apply_patch till arbetsytan`},help:{"v1-x2z207-3o":`Begränsa sökvägar för apply_patch till arbetsytans katalog (standard: true). Ange false för att tillåta skrivning utanför arbetsytan (farligt).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Meddelande om pågående körning efter godkännande (ms)`},help:{"v1-1gwwann-4z":`Fördröjning i millisekunder innan ett meddelande om pågående körning visas efter att en körning har godkänts. Öka värdet för att minska flimmer vid snabba kommandon, eller sänk det för att ge operatören snabbare återkoppling.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Fråga före körning`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Kommandofärgning vid körning`},help:{"v1-kyxd4o-4n":`Visa parserbaserad kommandofärgning i förfrågningar om körningsgodkännande (standard: false). Aktivera detta för att visa färgmarkerad kommandotext utan att ändra policyn för körningsgodkännande.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Giltighetstid för varaktiga tillstånd (dagar)`},help:{"v1-5uxe2j-6r":`Standardgiltighetstid i dagar (1–3650) för varaktiga tillstånd som skapas via allow-always vid godkännande av automatiseringar. Om värdet inte anges förblir tillstånden giltiga tills de återkallas eller den tillhörande automatiseringen ändras. Villkoren låses när tillståndet skapas, så ändringar påverkar endast framtida tillstånd.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Körningsmål`},help:{"v1-rno1mf-5q":`Väljer strategi för körningsmål för skalkommandon. Använd "auto" för ett beteende som anpassas till körmiljön (sandbox när det är tillgängligt, annars gateway), eller ange sandbox/gateway/node uttryckligen när du behöver en fast körmiljö.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Körningsläge`},help:{"v1-1qscgnt-5q":`Normaliserad väljare för exec-policy. Använd "auto" för klassificerargranskning när godkännande saknas, "ask" för mänsklig granskning när godkännande saknas, "allowlist" för kommandon som godkänns av fasta regler eller "full" för betrodd lokal drift.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Nodbindning för exec`},help:{"v1-rfnz54-4s":`Konfiguration av nodbindning för exec-verktyg när kommandokörning delegeras via anslutna noder. Använd explicit nodbindning endast när routning mellan flera noder krävs.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Avisera när exec avslutas`},help:{"v1-1ounlvx-3q":`När värdet är true (standard) köas en systemhändelse och en livssignal begärs när exec-sessioner i bakgrunden avslutas och vid livscykelhändelser för exec på noder.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Avisera vid lyckad exec-körning utan utdata`},help:{"v1-1wx4xxd-3d":`När värdet är true köas en systemhändelse om slutförande även när exec-körningar i bakgrunden avslutas utan fel och utan utdata (standard: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Tillägg i början av PATH för exec`},help:{"v1-s1aimc-1r":`Kataloger som ska läggas till i början av PATH för exec-körningar (gateway/sandlåda).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Exec-granskare`},help:{"v1-12y548k-4x":`Modellbaserad exec-granskare som används i läget auto innan mänskligt godkännande begärs som reservlösning. Ange en separat modell här om du vill isolera exec-granskningen från huvudagentens modell.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Snabbläge för exec-granskare`},help:{"v1-175bx14-8u":`Valfritt snabbläge för OpenClaws godkännandegranskningar: true begär prioriterad bearbetning på de OpenAI Responses- och ChatGPT/OAuth-rutter som stöds; false begär standardbearbetning. Utelämna för att behålla leverantörens standardinställningar. Snabbläget kan kosta mer och beror på leverantörens tillgänglighet. Konfigurerar inte den inbyggda Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Modell för exec-granskaren`},help:{"v1-1lltiy5-3i":`Valfri åsidosättning av leverantör/modell för exec-granskningsagenten. Utelämna för att återanvända den konfigurerade primära modellen för målagenten.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Resonemang för exec-granskaren`},help:{"v1-yg2gby-6u":`Valfri resonemangsnivå för OpenClaws modellbaserade godkännandegranskningar: minimal, low, medium, high, xhigh eller max. Utelämna för att behålla leverantörens standardinställningar. Nivåerna som stöds normaliseras för den valda modellen. Konfigurerar inte den inbyggda Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Tidsgräns för exec-granskaren (ms)`},help:{"v1-1o30chi-3w":`Tidsgräns per steg för exec-granskaren i millisekunder för modellförberedelse och slutförande innan mänskligt godkännande begärs i stället (standard: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Profiler för säkra binärfiler i exec`},help:{"v1-4cdcwe-29":`Valfria säkerhetsprofiler per binärfil (gränser för positionsargument + tillåtna/nekade flaggor).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Säkra binärfiler i exec`},help:{"v1-1of1m2s-21":`Tillåt att säkra binärfiler som endast använder stdin körs utan uttryckliga poster i tillåtelselistan.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Betrodda kataloger för säkra binärfiler i exec`},help:{"v1-zljbcn-2v":`Ytterligare uttryckligen betrodda kataloger för sökvägskontroller av säkra binärfiler (poster i PATH betraktas aldrig automatiskt som betrodda).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Körningssäkerhet`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Kräv godkännande för inline-evaluering`},help:{"v1-jkmgo7-5z":"Kräv uttryckligt godkännande för inline-evaluering i tolkar, till exempel `python -c`, `node -e`, `ruby -e` eller `osascript -e`. Förhindrar att tillåtelselistan återanvänds utan avisering och ändrar ”tillåt alltid” till ”fråga varje gång” för dessa former."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Tidsgräns för körning (sekunder)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Filsystemsverktyg endast för arbetsytan`},help:{"v1-1mhuvka-2s":`Begränsa filsystemsverktyg (read/write/edit/apply_patch) till arbetsytans katalog (standard: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`GitHub CLI-identitet och Git-författare`},help:{"v1-1fl77im-5s":`Hanterad lokal GitHub CLI-profil och valfri Git-författare för agentverktyg. Utelämna detta objekt för att behålla det ordinarie kontot och författaren för användaren som kör Gateway. Autentiseringsuppgifter för fjärrarkiv åsidosätts aldrig.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Git-författarens e-postadress`},help:{"v1-kol5g6-1i":`Valfri processlokal e-postadress för Git-författare och den som gör incheckningen.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Git-författarens namn`},help:{"v1-z5bl1f-1h":`Valfritt processlokalt namn för Git-författare och den som gör incheckningen.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Typ av autentiseringsuppgifter för GitHub`},help:{"v1-qi3qun-3q":`Markerar en hanterad OAuth-profil vars roterande autentiseringsuppgift för förnyelse ägs av Gateway. Profiler där detta utelämnas använder en personlig åtkomsttoken.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`GitHub-profilversion`},help:{"v1-4lzl0-27":`Opak, genererad profilversion som används för att byta hanterade autentiseringsuppgifter atomärt.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Aktivera länkförståelse`},help:{"v1-23t2io-59":`Aktivera automatisk förbearbetning för länkförståelse så att URL:er kan sammanfattas innan agenten resonerar. Låt detta vara aktiverat för rikare kontext och inaktivera det när strikt minimal bearbetning krävs.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Maximalt antal länkar för länkförståelse`},help:{"v1-ksxmcv-52":`Maximalt antal länkar som expanderas per tur vid länkförståelse. Använd lägre värden för att begränsa svarstid och kostnad i trådar med många meddelanden, och högre värden när kontext från flera länkar är avgörande.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Modeller för länkförståelse`},help:{"v1-6j3mnw-5a":`Lista över föredragna modeller för länkförståelse, som prövas i ordning som reservalternativ när detta stöds. Använd lättviktiga modeller först för rutinmässig sammanfattning och tyngre modeller endast vid behov.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Omfattning för länkförståelse`},help:{"v1-183cwpa-55":`Styr när länkförståelse körs utifrån samtalskontext och meddelandetyp. Begränsa omfattningen för att undvika onödiga hämtningar för meddelanden där länkarna inte är relevanta att bearbeta.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Tidsgräns för länkförståelse (sek)`},help:{"v1-61v30o-4p":`Tidsgräns i sekunder för tolkning av varje länk innan länkar som inte kunnat tolkas hoppas över. Håll gränsen låg för att undvika långa väntetider när externa webbplatser är långsamma eller inte kan nås.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Detektering av verktygsloopar`},help:{"v1-1e3rls8-5g":`Styr detektering av verktygsloopar i löpande historik och skyddet efter komprimering. Utelämna för att hålla löpande detektering avstängd och skyddet efter komprimering aktiverat. Ange true för att aktivera båda eller false för att inaktivera båda.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Policy för bilagor vid ljudtolkning`},help:{"v1-1s3t9s5-3o":`Välj vilka matchande ljudbilagor som ska bearbetas. Bearbeta endast den första om inte transkribering av flera bilagor är avsiktlig.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Format för återgivning av transkription`},help:{"v1-glpdzh-3i":`Formatera den återgivna transkriptionen med platshållaren {transcript}. Låt platshållaren vara oförändrad så att transkriptionen ingår i det som skickas.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Återge transkription i chatten`},help:{"v1-1dedp8c-3r":`Återge ljudtranskriptionen i den ursprungliga chatten innan agenten bearbetar den. Aktivera detta när användare behöver kontrollera vad systemet hörde.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Aktivera ljudtolkning`},help:{"v1-1v0x7te-2m":`Aktivera ljudtolkning så att röstmeddelanden eller ljudklipp kan transkriberas och användas som kontext för agenten.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Språk för ljudtolkning`},help:{"v1-1ruqt97-3z":`Standardtips om språk för leverantörer av ljudtranskribering. Ange det när det huvudsakliga talade språket är känt och leverantörens språkidentifiering är opålitlig.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Maximalt antal byte för ljudförståelse`},help:{"v1-1mcckc8-43":`Standardgräns för ljudindatans storlek för konfigurerade och automatiskt identifierade modeller. Ange storleken på den största inspelning som dina leverantörer och ditt nätverk ska acceptera.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Maximalt antal tecken för ljudförståelse`},help:{"v1-eo1dp-43":`Standardgräns för transkriptionens längd för konfigurerade och automatiskt identifierade modeller. Använd ett lägre värde för att förhindra att långa röstanteckningar utökar agentens kontext.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Föredragen modell för ljudförståelse`},help:{"v1-1n5zya1-3c":`Prioritera en funktionsmärkt post i tools.media.models för ljudtranskribering framför övriga kompatibla reservalternativ.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Prompt för ljudförståelse`},help:{"v1-1v5jtay-4b":`Standardprompt för ljudtranskribering när en modellpost inte åsidosätter den. Håll instruktionen oförändrad när efterföljande arbetsflöden är beroende av transkriptionens stil.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Omfattning för ljudförståelse`},help:{"v1-1pptfg0-3w":`Begränsa ljudförståelse efter kanal, chattyp eller källnyckel. Håll omfattningen snäv där automatisk transkribering är känslig eller kostsam.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Tidsgräns för ljudförståelse (sek)`},help:{"v1-n8wc6c-3b":`Standardtidsgräns för förfrågningar om ljudförståelse. Öka den för långa inspelningar eller långsammare lokala transkriptionsmodeller.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Samtidighet för medieförståelse`},help:{"v1-13kr9np-58":`Maximalt antal samtidiga medieförståelseoperationer per tur för bild-, ljud- och videouppgifter totalt. Sänk detta i resursbegränsade driftsmiljöer för att undvika överbelastning av processor och nätverk.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Policy för bilagor vid bildförståelse`},help:{"v1-11hofbw-3e":`Välj vilka matchande bildbilagor som ska bearbetas. Bearbeta endast den första om inte analys av flera bilder är avsikten.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Aktivera bildförståelse`},help:{"v1-1b2zw34-50":`Aktivera bildförståelse så att bifogade eller refererade bilder kan tolkas till textbaserad kontext. Inaktivera om du behöver arbeta med enbart text eller vill undvika kostnader för bildbearbetning.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Maximalt antal byte för bildförståelse`},help:{"v1-jwwpd1-3v":`Standardgräns för storleken på indatabilder för konfigurerade och automatiskt identifierade modeller. Anpassa detta till leverantörens gränser för datamängd och driftsmiljöns bandbredd.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Maximalt antal tecken för bildförståelse`},help:{"v1-ebnxhk-3q":`Maximal längd på bildbeskrivningar som standard. Använd ett lägre värde för kompakt kontext eller ett högre värde för detaljerad OCR och scenanalys.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Föredragen modell för bildförståelse`},help:{"v1-1o2uwo6-3c":`Prioritera en post i tools.media.models med kapacitetstagg för bildförståelse framför övriga kompatibla reservalternativ.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Prompt för bildförståelse`},help:{"v1-3a7piy-3p":`Standardprompt för bildförståelse när en post inte åsidosätter den. Använd en fast prompt när mottagande system är beroende av stabila beskrivningar.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Omfattning för bildförståelse`},help:{"v1-tievo1-3s":`Begränsa bildförståelse efter kanal, chattyp eller källnyckel. Håll omfattningen snäv i aktiva eller icke betrodda kanaler för att styra bearbetningen.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Tidsgräns för bildförståelse (sek)`},help:{"v1-1wcm84x-31":`Standardtidsgräns för förfrågningar om bildförståelse. Öka den för stora bilder eller långsammare lokala bildmodeller.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Gemensamma modeller för medieförståelse`},help:{"v1-1bbsp4f-3x":`Modellista för medieförståelse. Använd kapacitetstaggarna image, audio eller video på varje post så att varje bearbetningsflöde endast väljer kompatibla reservalternativ.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Bilagepolicy för videoförståelse`},help:{"v1-1qm1qrc-3e":`Välj vilka matchande videobilagor som ska bearbetas. Bearbeta endast den första om inte analys av flera videor är avsikten.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Aktivera videoförståelse`},help:{"v1-1ltx5gl-58":`Aktivera videoförståelse så att klipp kan sammanfattas till text för efterföljande resonemang och svar. Inaktivera när videobearbetning strider mot policy eller är för dyr för din driftsmiljö.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Maximalt antal byte för videoförståelse`},help:{"v1-2mp77v-3v":`Standardgräns för storleken på videoindata för konfigurerade och automatiskt identifierade modeller. Anpassa värdet efter leverantörens gränser för datamängd och driftsmiljöns bandbredd.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Maximalt antal tecken för videoförståelse`},help:{"v1-1j0x40b-3j":`Standardvärde för maximal längd på videobeskrivningar. Använd ett lägre värde för kompakt kontext eller ett högre värde för detaljerade scensammanfattningar.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Föredragen modell för videoförståelse`},help:{"v1-1cygq5k-3c":`Prioritera en funktionsmärkt post i tools.media.models för videoförståelse framför övriga kompatibla reservalternativ.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Prompt för videoförståelse`},help:{"v1-692dhv-3m":`Standardprompt för videoförståelse när en post inte åsidosätter den. Använd en fast prompt när mottagande system är beroende av konsekventa sammanfattningar.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Omfattning för videoförståelse`},help:{"v1-7gfrx3-3s":`Begränsa videoförståelse efter kanal, chattyp eller källnyckel. Håll omfattningen snäv i vältrafikerade eller obetrodda kanaler för att kontrollera bearbetningen.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Tidsgräns för videoförståelse (sek)`},help:{"v1-e8rzsy-33":`Standardtidsgräns för begäranden om videotolkning. Öka den för längre klipp eller långsammare lokala analysmodeller.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Lista över tillåtna meddelandeåtgärder`},help:{"v1-1iceqwa-5c":`Global lista över tillåtna meddelandeåtgärder för meddelandeverktyget. Använd endast när hela körmiljön ska tillgängliggöra och acceptera en begränsad uppsättning åtgärder; använd i första hand agentspecifika listor över tillåtna åtgärder för offentliga agenter eller agenter i sandlådor.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Aktivera massutskick av meddelanden`},help:{"v1-1ms74z7-14":`Aktivera åtgärden för massutskick (standard: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Tillåt kontextöverskridande utskick (mellan leverantörer)`},help:{"v1-276qxo-2s":`Tillåt utskick mellan olika leverantörer (standard: true). Ange false för att blockera meddelanden mellan leverantörer.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Tillåt kontextöverskridande utskick (samma leverantör)`},help:{"v1-1sg4x49-1z":`Tillåt utskick till andra kanaler hos samma leverantör (standard: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Markör för kontextöverskridande utskick`},help:{"v1-1fg6jrp-1z":`Lägg till en synlig ursprungsmarkör vid kontextöverskridande utskick (standard: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Prefix för markör för kontextöverskridande utskick`},help:{"v1-eblsru-1p":`Textprefix för markörer för kontextöverskridande utskick (stöder "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Suffix för markör för kontextöverskridande utskick`},help:{"v1-1nk0jub-1p":`Textsuffix för markörer mellan kontexter (stöder "{channel}").`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Verktygsprofil`},help:{"v1-h6k98q-5k":`Namn på global verktygsprofil som används för att välja en fördefinierad grundpolicy för verktyg innan undantag för tillåtelse och nekande tillämpas. Använd detta för enhetliga miljöinställningar för alla agenter och håll profilnamnen oförändrade.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Verktygspolicy för sandlåda`},help:{"v1-ea7awo-4k":`Omslutande verktygspolicy för agentkörningar i sandlåda, så att dessa körningar kan ha separata gränser för sina befogenheter. Använd detta för att upprätthålla högre säkerhet i sandlådemiljöer.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Policy för tillåtna och nekade verktyg i sandlåda`},help:{"v1-ub701o-4t":`Policy för tillåtna och nekade verktyg som tillämpas när agenter körs i sandlådemiljöer. Håll policyerna minimala så att sandlådeuppgifter inte kan eskalera till onödiga externa åtgärder.`}},"tools%2Esessions%2EallowThreadTargets":{label:{"v1-1o1dl7e-p":`Tillåt trådar som sändningsmål`},help:{"v1-1ppcmoz-6v":`Tillåt sessions_send att rikta sig till tråd- eller ämnesspecifika chattsessioner, till exempel forumämnen i Telegram eller trådar i Slack/Discord (standard: false). Målet körs i den sessionen; allt det skickar med meddelandeverktyget hamnar i den användarsynliga tråden.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Synlighet för sessionsverktyg`},help:{"v1-1p13n9k-fm":`Styr vilka sessioner som kan nås via sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all" är standard = alla sessioner på Gateway, inklusive andra agenters och användares; "agent" = alla sessioner med det aktuella agent-id:t; "self" = endast den aktuella; "tree" = den aktuella sessionen + startade underagentsessioner). Åtkomst mellan agenter är aktiverad som standard och avgränsas av tools.agentToAgent; använd snävare synlighet för att begränsa läsningar och vanliga sändningar. Uttryckliga destinationer i agents.entries.<id>.tools.agentToAgent.send kan tillåta sändningar utan att utöka läsåtkomsten.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Verktygspolicy för underagenter`},help:{"v1-1xoug01-4z":`Verktygspolicy för startade underagenter som begränsar eller utökar verktygstillgången jämfört med den överordnade agentens standardinställningar. Använd detta för att avgränsa delegerade agenters funktioner till uppgiftens syfte.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Policy för tillåtna och nekade verktyg för underagenter`},help:{"v1-7vxsbf-5d":`Policy för tillåtna och nekade verktyg som tillämpas på startade underagenters körmiljöer. Håll denna snävare än den överordnade agentens behörigheter. Verktyg som ägs av den överordnade agenten, till exempel progress_card, nekas alltid, även via allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Svärm`},help:{"v1-1q96vvs-45":`Samordning av underagenter i insamlingsläge. Aktiverat som standard; ange false för att inaktivera. Verktygsbehörigheter gäller fortfarande för agents_wait och alternativ för att starta svärmar.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Standardagent för svärmar`},help:{"v1-p4alpg-2m":`Standardmålagent för svärmstarter där agentId utelämnas. Listan över tillåtna underagenter gäller fortfarande.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Aktivera svärm`},help:{"v1-1nnnrq9-2e":`Aktiverar underagenter i insamlingsläge och agents_wait. Aktiverat som standard; ange false för att välja bort detta.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Aktiva underagenter per svärm grupp`},help:{"v1-kfx6qp-1c":`Maximalt antal aktiva insamlingsunderagenter per svärmgrupp.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1a16wrf-z":`Samtidiga underagenter per svärmgrupp`},help:{"v1-1ednj37-70":`Maximalt antal insamlingsunderagenter som körs i varje svärmgrupps separata exekveringskö (standard: 32), oberoende av den vanliga samtidighetsgränsen för underagenter. Varje underagent som körs använder en modellström och en isolerad arbetsmiljö för Code Mode. Gruppens antagningsgränser gäller fortfarande.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Totalt antal underagenter per svärmgrupp`},help:{"v1-1gc9vl1-1e":`Maximalt antal insamlingsunderagenter som får skapas under en svärmgrupps livstid.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Maximal väntetid för svärm`},help:{"v1-bog18y-1g":`Maximal tidsgräns som accepteras av agents_wait, i sekunder.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Verktygssökning`},help:{"v1-g2rpl8-80":`Komprimera stora verktygskataloger för OpenClaw, MCP och klienter. OpenClaws körmiljöer använder automatiskt strukturerad verktygssökning när inget värde har angetts; aktiverat Code Mode har företräde och Codex använder sin inbyggda sökning. Ange false för att inaktivera funktionen, true för strukturerad sökning eller använd objektformen för att välja ett läge.`}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Aktivera verktygssökning`},help:{"v1-1naa8jz-3v":`Aktiverar verktygssökning. När funktionen är aktiverad döljer OpenClaw stora verktygskataloger bakom strukturerade verktyg för sökning, beskrivning och anrop vid körningar i den inbäddade körmiljön.`}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Maximalt antal resultat för verktygssökning`},help:{"v1-7du4kh-32":`Maximalt antal resultat från verktygssökning som en modell kan begära. Vid körning begränsas värdena till det stödda intervallet 1..50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Gränssnitt för verktygssökning`},help:{"v1-1uvcg7i-6z":`Välj gränssnittet som modellen ser: "tools" (standard) tillhandahåller strukturerade verktyg för sökning, beskrivning och anrop; "directory" håller en begränsad verktygskatalog synlig, tillhandahåller en begränsad uppsättning scheman som sannolikt behövs eller är obligatoriska och gör resten tillgängliga via sökning, beskrivning och anrop.`}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Standardantal resultat för verktygssökning`},help:{"v1-1uchq7t-39":"Standardantal resultat från verktygssökning som returneras när modellen inte anger någon gräns. Vid körning begränsas detta till `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Aktivera verktyg för strukturerade planer`},help:{"v1-1xgegme-4o":"Enhetligt statusverktyg, `progress_card`, för beständiga planer och beskrivande anteckningar i överordnade sessioner. Aktiverat som standard; ange false för att inaktivera. Alltid otillgängligt för underagenter."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Webbverktyg`},help:{"v1-fpsy5-4y":`Grupp av policyinställningar för webbverktygens sök- och hämtningsleverantörer, gränser och reservbeteende. Se till att aktiverade inställningar stämmer överens med tillgången till API-nycklar och policyn för utgående nätverkstrafik.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`TTL för webbhämtningscache (min)`},help:{"v1-1hk89qp-17":`Cachens TTL i minuter för resultat från web_fetch.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Aktivera verktyg för webbhämtning`},help:{"v1-yrswld-1f":`Aktivera verktyget web_fetch (resurssnål HTTP-hämtning).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Begärandehuvuden för webbhämtning`},help:{"v1-16bjkv5-me":"Extra begärandehuvuden som skickas med direkta web_fetch-begäranden, till exempel för Gateway-routning eller autentisering. Varje konfigurerat värde behandlas som känsligt och maskeras i exponerad konfiguration och insamlad felsökningsdata. Värden är vanliga strängar, stöder ${VAR}-substitution och den globala escape-sekvensen $${VAR} för bokstavlig återgivning, och skickas till URL:er som modellen väljer. Poster valideras när begäran byggs i stället för när konfigurationen läses in, så ett ogiltigt namn eller ett värde som inte kan skickas tas bort och loggas i stället för att funktionen inaktiveras; Accept, Accept-Language, User-Agent och inramningshuvuden som Transfer-Encoding tas också bort. Använd tools.web.fetch.userAgent för att ändra användaragenten. Omdirigeringar mellan ursprung behåller endast de säkra huvuden som tillåts av guarded-fetch, och ändringar av de huvuden som faktiskt skickas delar upp hämtningscachen."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Maximalt antal tecken vid webbhämtning`},help:{"v1-12d1fw7-1d":`Maximalt antal tecken som returneras av web_fetch (trunkeras).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Absolut gräns för antal tecken vid webbhämtning`},help:{"v1-cl2mf1-1v":`Absolut övre gräns för maxChars i web_fetch (gäller konfiguration och verktygsanrop).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Maximalt antal omdirigeringar vid webbhämtning`},help:{"v1-t6eak9-1h":`Maximalt antal tillåtna omdirigeringar för web_fetch (standard: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Maximal nedladdningsstorlek vid webbhämtning (byte)`},help:{"v1-q6ld9c-10":`Maximal nedladdningsstorlek före trunkering.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Leverantör för webbhämtning`},help:{"v1-6pb3nv-v":`ID för reservleverantören för webbhämtning.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Extrahering med Readability vid webbhämtning`},help:{"v1-19exqzx-2c":`Använd Readability för att extrahera huvudinnehållet från HTML (använder enkel HTML-rensning som reservlösning).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`SSRF-policy för webbhämtning`},help:{"v1-qtn7zx-3c":`Avgränsade åsidosättningar av SSRF-policyn för web_fetch. Begränsa omfattningen och aktivera endast för kända proxymiljöer i lokala nätverk.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Tillåtna värdnamn för webbhämtning`},help:{"v1-1j9ctya-35":`Exakta värdnamn eller bokstavliga IP-adresser som tillåts för web_fetch, inklusive mål som annars blockeras. Håll listan så kort som möjligt.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Tillåt unikt lokalt IPv6-intervall för webbhämtning`},help:{"v1-1eyz55i-3b":`Tillåt unikt lokala IPv6-adresser (fc00::/7) för kompatibilitet med betrodda proxyservrar som använder syntetiska IP-adresser, såsom sing-box, Clash eller Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Tillåt RFC 2544-testintervall för webbhämtning`},help:{"v1-u5asdb-2y":`Tillåt IP-adresser i RFC 2544-intervallet för prestandatester (198.18.0.0/15) för kompatibilitet med proxyservrar som använder syntetiska IP-adresser, såsom Clash eller Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Blockerade värdnamn för webbhämtning`},help:{"v1-1164vvk-66":`Värdnamnsmönster som blockeras före DNS och tillåtelseregler vid varje omdirigering i web_fetch. Stöder exakta värdnamn och "*.example.com" enbart för underdomäner; lägg till "example.com" separat för att blockera rotdomänen. Om värdet är tomt eller inte anges läggs inga blockeringar till.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Tillåt privata nätverk för webbhämtning (riskabelt)`},help:{"v1-2s6mv7-3t":`Tillåter web_fetch att komma åt mål i privata och interna nätverk. Låt vara inaktiverat om inte URL:er som modellen väljer är betrodda i den här driftsmiljön.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Tidsgräns för webbhämtning (sek)`},help:{"v1-1c3yfr4-16":`Tidsgräns i sekunder för web_fetch-förfrågningar.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent för webbhämtning`},help:{"v1-s7pe8j-1e":`Åsidosätt User-Agent-headern för web_fetch-förfrågningar.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Betrodd miljöproxy för webbhämtning`},help:{"v1-1ypkqj7-54":`Dirigera web_fetch via en betrodd HTTP(S)-proxy som anges i miljövariabler och låt proxyn hantera DNS-uppslagning. Aktivera endast om proxyn kontrolleras av operatören och tillämpar policyn för utgående trafik efter DNS-uppslagning.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`TTL för webbsökningscache (min)`},help:{"v1-6trzlf-18":`Cachens TTL i minuter för web_search-resultat.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Aktivera webbsökningsverktyget`},help:{"v1-n1cm4y-27":`Aktivera hanterad web_search och valfri inbyggd sökning i Codex för modeller som stöds.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Maximalt antal webbsökresultat`},help:{"v1-mrw7mi-z":`Antal resultat som ska returneras (1–10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Tillåtna domäner för Codex`},help:{"v1-1cv4y44-43":`Lista över tillåtna domäner för inbyggd web_search i Codex. Under turer med inbyggd värdbaserad sökning begränsar den även hanterad web_fetch; turer med hanterade leverantörer påverkas inte.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Storlek på sökkontext för Codex`},help:{"v1-antack-1u":`Önskad kontextstorlek för inbyggd sökning i Codex: "low", "medium" eller "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Aktivera inbyggd webbsökning i Codex`},help:{"v1-ek2jzd-1k":`Aktivera inbyggd webbsökning i Codex för modeller med stöd för Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Webbsökningsläge för Codex`},help:{"v1-1ahyq9f-32":`Önskat läge för inbyggd webbsökning i Codex: "cached" (standard; obegränsade Codex-turer använder då live) eller "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Användarens stad för Codex`},help:{"v1-1y95orp-1d":`Ungefärlig stad som skickas till den inbyggda webbsökningen i Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Användarens land för Codex`},help:{"v1-1xkm5ms-1g":`Ungefärligt land som skickas till den inbyggda webbsökningen i Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Användarens region för Codex`},help:{"v1-lhar02-1l":`Ungefärlig region/delstat som skickas till den inbyggda webbsökningen i Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Tidszon för Codex-användare`},help:{"v1-fgv9fh-1h":`Ungefärlig tidszon som skickas till den inbyggda webbsökningen i Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Webbsökleverantör`},help:{"v1-10omglr-1x":`Sökleverantörens ID. Identifieras automatiskt utifrån tillgängliga API-nycklar om det utelämnas.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Tidsgräns för webbsökning (sek)`},help:{"v1-i0egvw-17":`Tidsgräns i sekunder för web_search-förfrågningar.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transkriptioner`},help:{"v1-1i0sc09-66":`Grundläggande inställningar för insamling av transkriptioner för mötesanteckningar, agentverktyg med inspelningsfunktion och konfigurerade källor för automatisk start vid livemöten. Mötesinsticksprogram sparar anteckningar beständigt som standard; sätt enabled till false för att inaktivera detta globalt.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Källor för automatisk start av transkriptioner`},help:{"v1-1mzsl79-5s":`Källor för livetranskriptioner som hanteras automatiskt från starten av Gateway. Varje post aktiveras genom att finnas med; ta bort en post för att inaktivera den källan. Källorna samlar in kontinuerligt om inte whenOccupied är aktiverat.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`Konto-ID för transkriptioner`},help:{"v1-6g2kjj-4b":`Valfri identifierare för leverantörskonto eller arbetsyta för transkriptionskällor som behöver skilja mellan konton. Använd leverantörens dokumenterade format för konto-ID.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`Kanal-ID för transkriptioner`},help:{"v1-1lk9d5o-4u":`Leverantörens kanal-id för källan till direkttranskriberingen, till exempel en röstkanal i Discord eller en huddle-kanal i Slack. Kontrollera hur leverantören definierar id:n innan du aktiverar automatisk start.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Discord-server-id`},help:{"v1-fyfgnk-4l":`Valfritt Discord-server-id för transkriberingskällor i Discord-röstkanaler. Ange detta tillsammans med motsvarande channelId när leverantören behöver söka efter röstkanaler inom en viss server.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`Mötes-URL för transkribering`},help:{"v1-1xtt9ci-4f":`Valfri mötes-URL för leverantörer som ansluter via URL i stället för kanal-id. Använd endast betrodda möteslänkar eftersom automatisk start kan ansluta till och spela in mötet.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`Leverantörs-id för transkriberingskälla`},help:{"v1-1uur06p-3s":`Leverantörs-id för transkriberingskällan, till exempel en leverantör för Discord-röstkanaler eller en framtida leverantör för Slack-huddles. Använd exakt det id som leverantörens insticksprogram tillhandahåller.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`Sessions-id för transkribering`},help:{"v1-xyo4x5-5o":`Valfritt fast sessions-id för transkribering från denna källa med automatisk start. Ignoreras när whenOccupied är true. Lämna detta oangivet för att generera id:n, om du inte behöver en stabil daglig väljare och kan undvika kollisioner samma dag.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Transkriberingens titel`},help:{"v1-ycjnmp-5y":`Valfri titel för framtida transkriberingar. Om bara titlar ändras fortsätter pågående transkriberingar utan att deras ursprungliga titel eller sparade anteckningar byter namn. Andra källändringar hanteras med omstart som vanligt.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Transkribering vid närvaro`},help:{"v1-34jid4-78":`Starta en ny transkriberingssession varje gång människor finns i källan och stoppa den (och generera anteckningar) när den sista människan lämnar. Kräver en leverantör som rapporterar närvaro, till exempel discord-voice. Standard: false (transkribera kontinuerligt från start av Gateway).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transkribering aktiverad`},help:{"v1-fyqqr0-6d":`Aktiverar automatiska mötesanteckningar som sparas beständigt, agentverktyget transcripts och konfigurerade källor med automatisk start. Standard: true. Ange false för att inaktivera beständig lagring och verktyget. Uttryckligt transkriberingsläge för möten behåller sin begränsade vy över det senaste liveinnehållet.`}},tts:{label:{"v1-bmxkk9-e":`Text till tal`},help:{"v1-1o27tk2-4n":`Policy för text till tal som läser upp agentsvar i röst- eller ljudgränssnitt som stöds. Låt vara inaktiverat om inte röstuppspelning ingår i operatörens eller användarens arbetsflöde.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`TTS-persona`},help:{"v1-1r0opcb-29":`ID för standardpersona för TTS. Lokala inställningar för TTS-persona kan åsidosätta detta per värd.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`TTS-personor`},help:{"v1-19aybhl-2l":`Namngivna TTS-personor som definierar en konsekvent röstidentitet och leverantörsspecifika talkopplingar.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`TTS-persona`},help:{"v1-10s52ah-2l":`En TTS-persona. Använd leverantörsspecifika kopplingar för exakta röster/modeller och promptmallar.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Leverantörskopplingar för TTS-persona`},help:{"v1-993jop-3e":`Leverantörsspecifika kopplingar för TTS-persona med talleverantörens id som nyckel. Dessa slås samman med och åsidosätter tts.providers för den aktiva personan.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Inställningar för TTS-leverantörer`},help:{"v1-1k80nl4-4y":`Leverantörsspecifika TTS-inställningar med talleverantörens id som nyckel. Använd detta i stället för medföljande leverantörsspecifika nycklar på toppnivå så att talinsticksprogram förblir frikopplade från kärnans konfigurationsschema.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Konfiguration för TTS-leverantör`},help:{"v1-dwapva-3d":`Leverantörsspecifik TTS-konfiguration för ett talleverantörs-id. Begränsa fälten till det insticksprogram som äger leverantören.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`API-nyckel för TTS-leverantör`},help:{"v1-1m2fj0i-2o":`Leverantörens API-nyckel som används av talleverantören när dess insticksprogram kräver autentiserad TTS-åtkomst.`}},tui:{label:{"v1-c8hus1-b":`Terminalgränssnitt`},help:{"v1-1fg9vw2-3s":`Visningsinställningar för terminalgränssnittet. Använd det här avsnittet för presentationsinställningar som endast gäller terminalen, utan att ändra beteendet för Gateway eller andra gränssnitt.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Sidfot i terminalgränssnittet`},help:{"v1-6e12l3-3k":`Visningsinställningar för terminalgränssnittets sidfot. Håll valfri kontext kompakt så att information om session, modell, mål och token förblir läsbar.`}},ui:{label:{"v1-ye4dff-2":`Användargränssnitt`},help:{"v1-dt1924-42":`Presentationsinställningar för gränssnittets accenter och operatörens visningspreferenser. Använd detta för att anpassa läsbarheten utan att ändra beteendet vid körning.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Användarens accentfärg`},help:{"v1-a7a2z8-51":`Accent i Control UI: #RRGGBB för en anpassad färg, eller 'theme' för det valda temats palett. Åsidosätter ui.seamColor; rensa värdet för att ärva den konfigurerade accentfärgen eller temats standardfärg.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Accentfärg`},help:{"v1-14q3r4h-4g":`Primär accentfärg som används i gränssnittet för framhävning, märken och visuella identitetsmarkörer. Använd värden med hög kontrast som förblir läsbara i både ljusa och mörka teman.`}},update:{label:{"v1-k12u1x-7":`Uppdateringar`},help:{"v1-11c5k8v-5c":`Inställningar för uppdateringskanal och kontroll vid start som håller OpenClaws körmiljö uppdaterad. Använd konservativa kanaler i produktion och mer experimentella kanaler endast i kontrollerade miljöer.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Automatisk uppdatering aktiverad`},help:{"v1-49xs2h-3c":`Aktivera automatisk uppdatering i bakgrunden för paketinstallationer från stable och beta; extended-stable tillämpas aldrig automatiskt (standard: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Uppdateringskanal`},help:{"v1-lqtdvf-5b":`Uppdateringskanal för git- och npm-installationer ("stable", "extended-stable", "beta" eller "dev"). extended-stable gäller endast paket: installation sker endast i förgrunden, med valfria skrivskyddade tips vid start.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Uppdateringskontroll vid start`},help:{"v1-qy3q9g-5v":`Söker efter uppdateringar när Gateway startar, inklusive skrivskyddade tips för extended-stable (standard: true). Ange false för att inaktivera automatiska uppdateringskontroller, tillämpning av uppdateringar och anonyma uppdateringspingar för Gateway och noder utan grafiskt gränssnitt.`}},voicewake:{label:{"v1-txt1wb-a":`Röstväckning`}},web:{label:{"v1-1ae9z56-b":`Webbkanal`}},wizard:{label:{"v1-28jonk-h":`Konfigurationsinställningar`},help:{"v1-14jh6rm-3b":`Användarägda installationsinställningar. Maskinägd guidehistorik och bekräftelsestatus lagras i den delade tillståndsdatabasen.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Åtkomst för identifiering vid installation`},help:{"v1-1nqxt0w-38":`Samtycke till identifiering vid guidad installation: "full" söker utan att fråga, medan "guarded" ber om tillåtelse innan lokala program undersöks.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Apprekommendationer vid installation`},help:{"v1-ub8uoi-30":`Styr om den guidade installationen får använda installerade programs etiketter för att rekommendera relevanta insticksprogram och färdigheter.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Tidsstämpel för guidens senaste körning`},help:{"v1-1y0fbk-1k":`Tidsstämpel för den senaste guidekörningen som sparades utan fel.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Kommando för guidens senaste körning`},help:{"v1-x2pfkk-15":`Kommandot som startade den senaste guidekörningen.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit för guidens senaste körning`},help:{"v1-h0jkmt-1i":`Källkodens commit som användes vid den senaste körningen av guiden i utvecklingsmiljön.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Läge för guidens senaste körning`},help:{"v1-16508qy-1r":`Om den senaste guidekörningen avsåg installation i läget "local" eller "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Version för guidens senaste körning`},help:{"v1-1tr4z9d-19":`OpenClaw-versionen som användes vid den senaste guidekörningen.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Tidsstämpel för säkerhetsbekräftelse i guiden`},help:{"v1-86i182-2a":`Tidsstämpel för säkerhetsbekräftelsen vid installation, sparad tillsammans med målkonfigurationen.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Acceleration av arbetsträd`},help:{"v1-9es3gc-4r":`Använd filsystemsacceleration för nya hanterade arbetsträd när det stöds (standard: true). Ange false för att använda vanlig Git-utcheckning och filkopiering. Gäller endast nya arbetsträd.`}},worktreeMaxCount:{label:{"v1-1gj5fhm-p":`Maximalt antal hanterade arbetsträd`},help:{"v1-6z5l36-7q":`Maximalt antal befintliga hanterade arbetsträd för alla agenter och kodarkiv (standard: 4096). Tar först bort grenar som har slagits samman eller squashats, därefter de äldsta inaktiva arbetsträden, inklusive osparade data. Pågående körningar skyddas; höj detta värde om de fyller kvoten. Kravet på tillgängligt diskutrymme gäller fortfarande.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Rotkatalog för arbetsträd`},help:{"v1-1tgti9j-5d":`Global katalog för nya hanterade arbetsträd. Använd en absolut sökväg eller ~ för din hemkatalog; standardvärdet är <state-dir>/worktrees. Befintliga arbetsträd behåller sina registrerade sökvägar när detta ändras.`}}}}})))()}export{t as n,n as t};